MultiLanguageItemData['en'][199815] = {name = "[q3]Formula: Enchant Cloak - Regenerative Leech", additional_info = "Binds when picked up\n[q2]Use: Teaches you how to perform the Regenerative Leech enchantment.\n[q2]Permanently enchants a cloak to increase your Leech by 75 and heal for 9925 every 5 sec while out of combat. Cannot be applied to items lower than level 10.\nRequires Dragon Isles Enchanting (25)\nRequires Renown Rank 10 with the Iskaara Tuskarr.\nSell Price:"}
MultiLanguageItemData['en'][199816] = {name = "[q3]Formula: Enchant Chest - Accelerated Agility", additional_info = "Binds when picked up\n[q2]Use: Teaches you how to perform the Accelerated Agility enchantment.\n[q2]Permanently enchants a chestpiece to increase your Agility by 77 and Speed by 200. Cannot be applied to items lower than level 10.\nRequires Dragon Isles Enchanting (25)\nRequires Renown Rank 10 with the Iskaara Tuskarr.\nSell Price:"}
MultiLanguageItemData['en'][199817] = {name = "[q3]Formula: Enchant Cloak - Homebound Speed", additional_info = "Binds when picked up\n[q2]Use: Teaches you how to perform the Homebound Speed enchantment.\n[q2]Permanently enchants a cloak to increase your Speed by 75 and reduce the cooldown of your Hearthstone by 0 minutes while in the Dragon Isles. Cannot be applied to items lower than level 10.\nRequires Dragon Isles Enchanting (25)\nRequires Renown Rank 11 with the Valdrakken Accord.\nSell Price:"}
