MultiLanguageItemData['en'][199899] = {name = "[q3]Iskaara Tug Sled", additional_info = "Binds when picked up\nUnique\nToy\n[q2]Use: Pull a tuskarr child's sled that someone can ride on.\nRequires Renown Rank 26 with the Iskaara Tuskarr.\nRequires Renown Rank 27 with the Iskaara Tuskarr.\n[q]\"It is said among the tuskarr that one who pulls the sled for another is a pillar of the community... but that doesn't stop kids from fighting over who gets to ride, instead.\""}
MultiLanguageItemData['en'][199900] = {name = "[q3]Secondhand Survey Tools", additional_info = "Binds when picked up\nToy\n[q2]Use: Set up survey equipment, so it looks as if you are doing something very important. (30 Min Cooldown)\n[q]\"Great for looking like you are doing something.\"\nSell Price:"}
