MultiLanguageItemData['en'][199924] = {name = "Strong Sea Kelp", additional_info = "Iskaaran Fishing Gear Material\nBinds when picked up\nUnique (3)\n[q]\"Often washed ashore in Iskaara. Bring this to Tavio.\""}
MultiLanguageItemData['en'][199925] = {name = "Stone With Hole", additional_info = "Iskaaran Fishing Gear Material\nBinds when picked up\nUnique (2)\n[q]\"Not uncommon on the rocky shores of the Azure Span. Tavio in Iskaara will make use of it.\""}
MultiLanguageItemData['en'][199927] = {name = "[q2]zzOldSheet Music: The Lazy Turnip", additional_info = "[q2]Use:"}
MultiLanguageItemData['en'][199928] = {name = "Flamethrower Torch", additional_info = "Quest Item\nUnique\n[q2]Use: Use the torch flamethrower to deal 88219 Fire damage every 0.3 sec over 6 sec. (8 Sec Cooldown)\n[q]\"Enchanted with air and fire elements, this torch will pack a punch. Point it away from your face.\""}
MultiLanguageItemData['en'][199930] = {name = "Ice Cold Antidote", additional_info = "Quest Item\nUnique\n[q]\"The bottle is cold to the touch. It's hard to believe this will cure anyone.\""}
MultiLanguageItemData['en'][200061] = {name = "[q3]Prismatic Leaper", additional_info = "Crafting Reagent\n\"The scales shimmer in multiple colors. Aside from its Cooking properties, this fish looks to be Millable.\"\nSell Price:"}
MultiLanguageItemData['en'][200063] = {name = "Observant Riddle \"Treat\"", additional_info = "Quest Item\n[q2]Use: Throw the \"treat\" at the Possessive Hornswog.\n[q]\"A dubiously-crafted morsel for a cantankerous hornswog.\""}
MultiLanguageItemData['en'][200064] = {name = "Marmoni's Prize", additional_info = "Binds when picked up\nUnique\n[q2]Use: Combine the riddle ingredients into a dubious \"treat\".\nRequires level 10 to 70 ( 70)\n[q]\"A shimmery yellow banana ferreted away for safekeeping.\""}
MultiLanguageItemData['en'][200065] = {name = "Adventurer's Lost Soap Bar", additional_info = "Binds when picked up\nUnique\n[q2]Use: Combine the riddle ingredients into a dubious \"treat\".\nRequires level 10 to 70 ( 70)\n[q]\"A necessary item long forgotten by a hapless adventurer.\""}
MultiLanguageItemData['en'][200066] = {name = "Well-Preserved Bone", additional_info = "Binds when picked up\nUnique\n[q2]Use: Combine the riddle ingredients into a dubious \"treat\".\nRequires level 10 to 70 ( 70)\n[q]\"A dry, crusty piece of bone long protected from the elements.\""}
MultiLanguageItemData['en'][200067] = {name = "[q2]Whispering Shard", additional_info = "Quest Item\n[q]\"This shard whispers many compliments into your mind. You are pretty great, aren't you?\""}
MultiLanguageItemData['en'][200069] = {name = "[q2]Obsidian Cache", additional_info = "Binds when picked up\n[q]\"Contains gold, Dragon Isles Supplies, rare Dragon Isles Artifacts and Titan Relics as well as a chance for cosmetic Djaradin weapons and armor.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][200070] = {name = "[q4]Obsidian Strongbox", additional_info = "Binds when picked up\n[q]\"Contains gold, Dragon Isles Supplies, rare artifacts and relics as well as a chance for cosmetic Djaradin weapons and armor.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][200071] = {name = "[q2]Sacred Tuskarr Totem", additional_info = "Binds when picked up\n[q]\"Stolen from the Iskaara Tuskarr, Elder Poa would reward you if you returned it to them.\""}
MultiLanguageItemData['en'][200072] = {name = "[q4]Dragonbane Keep Strongbox", additional_info = "Binds when picked up\n[q]\"Contains plundered items, supplies, gold and artifacts.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][200073] = {name = "[q4]Valdrakken Treasures", additional_info = "Binds when picked up\nUnique\n[q]\"Contains equipment, supplies, and treasures gathered throughout the ages.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][200074] = {name = "[q3]Frosted Rimefin Tuna", additional_info = "[q2]Use: Brush off the ice coating this fish.\nCrafting Reagent\n[q]\"A sturdy fish coated in a frosted outer shell.\"\nSell Price:"}
MultiLanguageItemData['en'][200075] = {name = "Flying Fish Bones", additional_info = "Iskaaran Fishing Gear Material\nBinds when picked up\nUnique\n[q]\"Should be plentiful in fishing villages, such as Iskaara. Bring this to Tavio.\""}
MultiLanguageItemData['en'][200076] = {name = "Harpoon Head", additional_info = "Iskaaran Fishing Gear Material\nBinds when picked up\nUnique\n[q]\"Skilled blacksmiths, such as Iskaara Tuskarr, should have one. Bring it to Tavio in Iskaara.\""}
MultiLanguageItemData['en'][200077] = {name = "Wooden Pole", additional_info = "Iskaaran Fishing Gear Material\nBinds when picked up\nUnique\n[q]\"Should be easy to find somewhere in the forests of western Azure Span. Bring to Tavio in Iskaara.\""}
MultiLanguageItemData['en'][200078] = {name = "Pickaxe Blade", additional_info = "Iskaaran Fishing Gear Material\nBinds when picked up\nUnique\n[q]\"You could probably \"borrow\" one in a Dragonscale Expedition camp, such as Three-Falls Lookout. Bring it to Tavio in Iskaara.\""}
MultiLanguageItemData['en'][200079] = {name = "Sea-Polished Basalt", additional_info = "Iskaaran Fishing Gear Material\nBinds when picked up\nUnique (3)\n[q]\"Should be abundant where lava meets the sea, such as Wild Coast. Bring to Tavio in Iskaara.\""}
MultiLanguageItemData['en'][200080] = {name = "[q2]Draconium Nugget", additional_info = "Iskaaran Fishing Gear Material\n[q7]Binds to Warband\n[q]\"Used to improve Iskaaran fishing net. Bring to Tavio in Iskaara. Can be fished in Dragon Isles highlands, ice holes, or lava pools.\""}
MultiLanguageItemData['en'][200081] = {name = "[q2]Strong Seavine", additional_info = "Iskaaran Fishing Gear Material\n[q7]Binds to Warband\n[q]\"Used to improve Iskaaran harpoon. Bring to Tavio in Iskaara. Can be fished in Dragon Isles highlands, ice holes, or lava pools.\""}
MultiLanguageItemData['en'][200082] = {name = "[q2]Battered Imbu-made Net", additional_info = "Iskaaran Fishing Gear Material\n[q7]Binds to Warband\n[q]\"Used to improve Iskaaran fishing net. Bring to Tavio in Iskaara. Can be fished in Dragon Isles highlands, ice holes, or lava pools.\""}
