MultiLanguageItemData['en'][200084] = {name = "[q2]Salinated Serevite", additional_info = "Iskaaran Fishing Gear Material\n[q7]Binds to Warband\n[q]\"Used to improve Iskaaran harpoon. Bring to Tavio in Iskaara. Can be fished in Dragon Isles highlands, ice holes, or lava pools.\""}
MultiLanguageItemData['en'][200085] = {name = "[q3]Khaz'gorite Wire", additional_info = "Iskaaran Fishing Gear Material\n[q7]Binds to Warband\n[q]\"Used to further improve Iskaaran fishing net. Bring to Tavio in Iskaara. Can be caught with fishing net.\""}
MultiLanguageItemData['en'][200086] = {name = "[q3]Khaz'gorite-Infused Resin", additional_info = "Iskaaran Fishing Gear Material\n[q7]Binds to Warband\n[q]\"Used to further improve your Iskaaran harpoon. Bring to Tavio in Iskaara. Can be obtained from BIG fish in the Dragon Isles with an Iskaaran harpoon.\""}
MultiLanguageItemData['en'][200087] = {name = "Fallingwater Mote", additional_info = "Quest Item\n[q]\"This viscous liquid is difficult to hold onto.\""}
MultiLanguageItemData['en'][200093] = {name = "[q2]Centaur Hunting Trophy", additional_info = "Dragon Isles Artifacts\nBinds when picked up\n[q]\"Can be turned in to Hunt Instructor Basku in Maruukai to increase your standing with the Maruuk Centaurs.\""}
MultiLanguageItemData['en'][200094] = {name = "[q4]Caravan Strongbox", additional_info = "Binds when picked up\n[q]\"Clan Aylaag is known for trade, but also generosity to those who help them. Valuable equipment, artifacts and trade items can be found in their strongboxes.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][200095] = {name = "[q4]Supply-Laden Soup Pot", additional_info = "Binds when picked up\nUnique\n[q]\"As a sign of thanks, the pot is full of supplies and food. There just might be an artifact or piece of equipment buried at the bottom.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][200099] = {name = "M.R.E.", additional_info = "[q2]Use: Restores ( 70313 / 5 * 20) health over 20 sec.\n Must remain seated while eating.\n[q]\"Meat Ready to Eat.\"\nSell Price:"}
