MultiLanguageItemData['en'][200114] = {name = "[q3]Stormie", additional_info = "Binds when picked up\n[q2]Use: Teaches you how to summon and dismiss this companion.\n[q2]Right Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)\nSell Price:"}
MultiLanguageItemData['en'][200115] = {name = "Sarantuya the Ever-True", additional_info = "Quest Item\n[q]\"By moonlight, assassins were sent for Maruuk. By moonlight, Teera slayed them first.\""}
MultiLanguageItemData['en'][200116] = {name = "[q3]Everlasting Horn of Lavaswimming", additional_info = "Binds when picked up\nToy\n[q2]Use: Drink from this horn to become immune to lava outdoors in the Dragon Isles for 10 minutes. (30 Min Cooldown)\n[q]\"Just don't be swimming when it wears off.\""}
MultiLanguageItemData['en'][200117] = {name = "Watcher's Golden Girdle", additional_info = "Quest Item\nUnique\n[q]\"Holds many potential secrets of the Titans, metalworking, and most importantly... fashion.\""}
MultiLanguageItemData['en'][200118] = {name = "[q4]Yellow Scouting Ottuk", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 25 with the Iskaara Tuskarr.\n\n\n[q]\"The yellow scouting ottuk love to hide and they blend in well to their surroundings. When not 'playing' hide and seek with their riders, they are perfect companions when scouting enemy encampments.\"\nFaction:\nIskaara Tuskarr\nRenown:\n25\nVendor:\nTatto\nLocation:\nIskaara\nCost:\n2\n2\n750"}
MultiLanguageItemData['en'][200119] = {name = "Everblazing Fireheart", additional_info = "Quest Item\nUnique\n[q]\"They say that Firava's heart grew three sizes that day, thanks to the Primalists.\""}
MultiLanguageItemData['en'][200120] = {name = "[q4]Irideus' Power Core", additional_info = "Quest Item\n[q2]Use: Attune the Power Core to an elite titanic denizen of Tyrhold, weakening it.\n[q]\"Taken from the Halls of Infusion, this device once powered up Watcher Irideus. Now it must be attuned again to regain its original power output.\""}
