MultiLanguageItemData['en'][200549] = {name = "[q3]Restored Titan Artifact", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+244 Intellect\n[q2]Use: Shield an ally for up to 37740 from a great distance and gain up to 5726 Speed. The Absorb and Speed amounts vary depending on the distance between you and your target, with the Absorb increasing and the Speed decreasing the closer you are. (1 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][200550] = {name = "[q3]Very Comfortable Pelt", additional_info = "Binds when picked up\nToy\n[q2]Use: Lounge around, Maruuk style! (20 Min Cooldown)\nRequires Renown 3 with the Maruuk Centaur and completing the quest \"Cultural Exchange\".\nSell Price:"}
MultiLanguageItemData['en'][200551] = {name = "[q3]Comfortable Pile of Pelts", additional_info = "Binds when picked up\nToy\n[q2]Use: Rest like a khanam wherever you go! (20 Min Cooldown)\nRequires Renown 3 with the Maruuk Centaur and completing the quest \"Cultural Exchange\".\nSell Price:"}
MultiLanguageItemData['en'][200552] = {name = "[q3]Torrent Caller's Shell", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+244 Strength\n[q2]Use: Channel torrents around you dealing [ 1906 * (6) * (1 + Versatility)] nature damage to nearby enemies over 3 sec. Then unleash a powerful blast dealing 53355 nature damage split between all nearby enemies. (2 Min, 30 Sec Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][200553] = {name = "Panthis Nectar", additional_info = "Dragon Isles Supplies\nBinds when picked up\n[q2]Add the Panthis Nectar to your Dragon Isles Supplies.\n[q]\"The bowl-shaped flower creates a well for nectar to pool. High in sugars, the nectar is highly desired when refined for cooking.\"\nSell Price:"}
MultiLanguageItemData['en'][200554] = {name = "Dropcap Head", additional_info = "Dragon Isles Supplies\nBinds when picked up\n[q2]Add the Oily Dropcap Head to your Dragon Isles Supplies.\n[q]\"The drop cap leaks an oil when it matures, this oil is highly prized as a fire accelerant.\"\nSell Price:"}
MultiLanguageItemData['en'][200555] = {name = "Inferno Seeds", additional_info = "Dragon Isles Supplies\nBinds when picked up\n[q2]Add the Inferno Seeds to your Dragon Isles Supplies.\n[q]\"Akin to a gunpowder, the Inferno Pods explode when fully mature spreading the seeds. The Djaradin gather them when they are just flowering and use them to get their forges to near molten temperatures.\"\nSell Price:"}
