MultiLanguageItemData['en'][200613] = {name = "Aylaag Windstone Fragment", additional_info = "[q7]Binds to Warband\nUnique\n[q2]Use: Return to the Aylaag camp, wherever they happen to be. Not available while the clan is moving. (15 Min Cooldown)\n5 Charges\nRequires Renown 11 with the Maruuk Centaur and completing the quest \"Whistling Rocks\".\n[q]\"A small amount of the wind's blessing, just enough to carry a whisper and the whisperer.\""}
MultiLanguageItemData['en'][200617] = {name = "Shattering Totem", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: Causes the earth at the target location to tremble and break, dealing Nature damage every 1 sec to enemies in 10 yard radius. Lasts 10 sec.\n\n Usable in the Obsidian Citadel and adjacent lava fields. (8 Sec Cooldown)\n[q]\"A powerful totem created by Earthmender Govrum.\"\nSell Price:"}
MultiLanguageItemData['en'][200619] = {name = "Scaralesh's Special", additional_info = "[q2]Use: Restores ( 42188 / 5 * 20) health over 20 sec.\n Must remain seated while eating.\n[q]\"Made with charred chilis, fine wine, imitation crab, and dracthyr resourcefulness.\"\nSell Price:"}
