MultiLanguageItemData['en'][200880] = {name = "[q3]Wind-Sealed Mana Capsule", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+244 Intellect\n[q2]Equip: Casting spells and abilities has a low chance to refund 1121 mana. If below 50% mana the seal breaks restoring 16820 mana.\n The seal can only be broken once every 5 minutes. (1s cooldown)\nSell Price:"}
MultiLanguageItemData['en'][200882] = {name = "[q4]Big Kinook's Spare Ladle", additional_info = "Cosmetic\n[q7]Binds to Warband\n{Two-Hand} {Staff}\n{1 - 2 Damage} {Speed 3.60}\n(0.4 damage per second)\n[q2]Use: Add this appearance to your Warband collection.\nSell Price:"}
MultiLanguageItemData['en'][200883] = {name = "[q3]Illusion: Primal Air", additional_info = "[q2]Use: Collect the weapon enchantment appearance of Primal Air.\nSell Price:"}
MultiLanguageItemData['en'][200884] = {name = "[q3]Ensemble: Glorious Dragonrider's Mail", additional_info = "[q7]Binds to Warband\nClasses: Hunter , Shaman , Evoker\n[q2]Use: Collect the appearances of the Glorious Dragonrider's Mail armor set.\n[q]\"The gold and crimson mark a Drekirjar as a force to be reckoned with.\""}
MultiLanguageItemData['en'][200885] = {name = "Cinna-Cinderbloom Tea", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: Steeped from Hyjal's sparking flower petals, this brew is sure to put a pep or two in your step. Increases movement speed by 30% for 1 hour.\n\n Only active while in the Dragon Isles.\nSell Price:"}
MultiLanguageItemData['en'][200886] = {name = "Lemon Silverleaf Tea", additional_info = "[q7]Binds to Warband\n[q2]Use: Keep yourself feeling prim and proper with this classic brew from the Eastern Kingdoms.\nSell Price:"}
MultiLanguageItemData['en'][200887] = {name = "Charred Porter", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: A loa-blessed mug of charred porter to settle your meal of meats. Increases Primary Stat by 10% for 1 hour.\n\n Only active while in the Dragon Isles.\nSell Price:"}
MultiLanguageItemData['en'][200888] = {name = "Coal-Fired Rib Rack", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: Roasted over a bed of anchor weed, siren's pollen, and fresh vorquin coal of a hearty flavor that courses through your very being! Increases Stamina by 20% for 1 hour.\n\n Only active while in the Dragon Isles.\nSell Price:"}
MultiLanguageItemData['en'][200889] = {name = "Highly Spiced Haunch", additional_info = "[q7]Binds to Warband\n[q2]Use: A delicious direhorn haunch dry-rubbed with generous helpings of ground Akunda's Bite fills your belly! You suddenly feel like a mighty warrior!\nSell Price:"}
MultiLanguageItemData['en'][200890] = {name = "Stonetalon Bloom Skewer", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: A skewer of lightly grilled and freshly seasoned vegetables straight from the Bloodhoof farms of Kalimdor. Increases mana regen by 30% for 1 hour.\n\n Only active while in the Dragon Isles.\nSell Price:"}
MultiLanguageItemData['en'][200891] = {name = "Druidic Dreamsalad", additional_info = "[q7]Binds to Warband\n[q2]Use: Nighthaven berries over a bed of spirit-enhancing greens, filling you with the glory of growing life wherever you roam!\nSell Price:"}
MultiLanguageItemData['en'][200892] = {name = "Dragonfruit Punch", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: Kick back and relax with a cup of the finest Dragon Isles fruits and berries this side of the Cascades. Reduces fall speed.\n\n Only active while in the Dragon Isles.\nSell Price:"}
MultiLanguageItemData['en'][200893] = {name = "Azsunian Poached Lobster", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: Bold, Nor'danil lobster brined & poached in the traditional Broken Isles method. Increases all stats by 5% for 1 hour.\n\n Only active while in the Dragon Isles.\nSell Price:"}
MultiLanguageItemData['en'][200894] = {name = "Rare Vintage Arcwine", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: The sweet, tannic notes of this arcwine sing of Suramar while sharpening your senses. Increases critical damage by 30% for 1 hour.\n\n Only active while in the Dragon Isles.\nSell Price:"}
MultiLanguageItemData['en'][200895] = {name = "Fine Taladorian Cheese Platter", additional_info = "[q7]Binds to Warband\n[q2]Use: From the milks of draenei-farmed, orchid-fed talbuk, clefthoof, and elekks, a wondrously pungent array of fine aged cheeses fills the air!\nSell Price:"}
MultiLanguageItemData['en'][200896] = {name = "Captain's Caramelized Catfish", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: Crispy baked Bridgeport catfish fit for a Proudmoore. Increases armor by 30% for 1 hour.\n\n Only active while in the Dragon Isles.\nSell Price:"}
MultiLanguageItemData['en'][200897] = {name = "Venrik's Goat Milk", additional_info = "[q7]Binds to Warband\n[q2]Use: Even without the traditional skull mug, this makes you feel like a real Freehold pirate!\nSell Price:"}
MultiLanguageItemData['en'][200898] = {name = "Mantis Shrimp Cocktail", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: Lemon-brined Mantis Shrimp from Binan Village, dipped in tangy cindergut sauce. Grants water breathing.\n\n Only active while in the Dragon Isles.\nSell Price:"}
MultiLanguageItemData['en'][200899] = {name = "Seared Sea Mist Noodles", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: Hot Sea Mist noodles straight from the pan garnished with cute cubed Paw'don roots and vegetables. Increases haste by 10% for 1 hour.\n\n Only active while in the Dragon Isles.\nSell Price:"}
MultiLanguageItemData['en'][200900] = {name = "Fried Emperor Wraps", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: Emperor salmon crispy-fried in Pandaren oils and spices, housed in wraps made from freshly-milled Zandalari flour. Increases mastery by 20% for 1 hour.\n\n Only active while in the Dragon Isles.\nSell Price:"}
MultiLanguageItemData['en'][200901] = {name = "Roquefort-Stuffed Peppers", additional_info = "[q7]Binds to Warband\n[q2]Use: Spicy Krasarang peppers stuffed with aged roquefort cheese sourced from the herb-grazing goats of Lakeshire.\nSell Price:"}
MultiLanguageItemData['en'][200902] = {name = "Ravenberry Panacotta Delight", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: A silky-sweet treat made of baked Mildenhall honey and cheeses, drenched in a heavy ravenberry syrup. Increases attack power by 10% for 1 hour.\n\n Only active while in the Dragon Isles.\nSell Price:"}
MultiLanguageItemData['en'][200903] = {name = "Moira's Choice Espresso", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: Roasted over a molten flame, brewed with blackberries, and mixed with malt, there's no wonder it's the Queen Regent's favorite blend! Increases attack speed by 30% for 1 hour.\n\n Only active while in the Dragon Isles.\nSell Price:"}
