MultiLanguageItemData['en'][201413] = {name = "Eternity-Infused Burrata", additional_info = "[q2]Use: Restores ( 45000 / 5 * 20) health and ( 60000 / 5 * 20) mana over 20 sec. Must remain seated while eating.\n[q]\"Infused with water from the Well of Eternity itself, this treat was once highly prized amongst the Kaldorei. Prior to the Sundering, of course.\"\nSell Price:"}
