MultiLanguageItemData['en'][201425] = {name = "[q4]Yellow War Ottuk", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 30 with the Iskaara Tuskarr.\n\n\n[q]\"The yellow ottuks of the Azure Span are sleek, sneaky, and smart. Those trained for war are the finest tuskarr cavalry mounts, equally capable on the ground and in the waters.\"\nFaction:\nIskaara Tuskarr\nRenown:\n30\nVendor:\nTatto\nLocation:\nIskaara\nCost:\n5\n5\n1000"}
MultiLanguageItemData['en'][201426] = {name = "[q4]Brown War Ottuk", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 30 with the Iskaara Tuskarr.\n\n\n[q]\"The tuskarr of Iskaara are loathe to war against anyone, but many tuskarr and their allies have nonetheless taken up the spear with a war ottuk beside them.\"\nFaction:\nIskaara Tuskarr\nRenown:\n30\nVendor:\nTatto\nLocation:\nIskaara\nCost:\n5\n5\n1000"}
