MultiLanguageItemData['en'][204354] = {name = "[q3]Hollowed Furbolg Food Pack", additional_info = "Cosmetic\n[q7]Binds to Warband\nBack\nRequires Honored reputation with the Winterpelt Furbolg on at least one character in your Warband.\n[q2]Use: Add this appearance to your Warband collection.\nSell Price:"}
MultiLanguageItemData['en'][204355] = {name = "[q3]Hollowed Winterpelt Food Pack", additional_info = "Cosmetic\n[q7]Binds to Warband\nBack\nRequires Revered reputation with the Winterpelt Furbolg on at least one character in your Warband.\n[q2]Use: Add this appearance to your Warband collection.\nSell Price:"}
MultiLanguageItemData['en'][204356] = {name = "[q2]Illustrious Gemdust", additional_info = "Binds when picked up\nCrafting Reagent\n[q]\"Acquired by Jewelcrafters by crushing gems revealed by the Cataclysm. Can be exchanged in Stormwind or Orgrimmar for Illustrious Jewelcrafter's Tokens.\"\nSell Price:"}
MultiLanguageItemData['en'][204359] = {name = "[q3]Reach Racer's Purse", additional_info = "Binds when picked up\n[q]\"Filled with gold, Dragon Isles Supplies, and a chance for a Drakewatcher's Manuscript.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][204360] = {name = "[q3]Strange Petrified Orb", additional_info = "Binds when picked up\n[q2]Use: Combine the Strange Petrified Orb and a Scrap of Black Dragonscales to reverse the petrification.\n[q]\"Trapped in the vaults for thousands of years, this object is completely rock hard. Perhaps a powerful source of earth magic could restore it.\""}
MultiLanguageItemData['en'][204361] = {name = "[q4]Winding Slitherdrake", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n[q]\"These drakes feel at home in the depths of the earth and the far reaches of the sky.\"\nAchievement:\nA Serpentine Discovery"}
MultiLanguageItemData['en'][204363] = {name = "[q3]Particularly Ordinary Egg", additional_info = "Binds when picked up\n[q2]Use: Combine your Particularly Ordinary Egg and a Drop of Blue Dragon Magic to enchant it.\n[q]\"There seems to be nothing unique about this egg at all. Maybe it can be empowered by something found within the vaults.\""}
MultiLanguageItemData['en'][204364] = {name = "[q3]Magically Altered Egg", additional_info = "Binds when picked up\n[q2]Use: Combine your Magically Altered Egg and some Everburning Ruby Coals to hatch it.\n[q]\"An egg that has been enhanced with mysterious blue dragon magic. If only you could find something in the vaults that could hatch it.\""}
MultiLanguageItemData['en'][204365] = {name = "Bundle of Ebon Spears", additional_info = "Quest Item\n[q2]Use: Drive an Ebon Spear into the corpse of a Zaqali djaradin. (5 Sec Cooldown)\n[q]\"A collection of spears wielded by the black dragonflight, still as sharp as the day they were forged.\""}
MultiLanguageItemData['en'][204366] = {name = "[q3]Egg of Unknown Contents", additional_info = "Binds when picked up\n[q2]Use: Combine your Egg of Unknown Contents and a Speck of Bronze Dust to age your egg.\n[q]\"The mysterious egg has finally hatched, but you can't make out what creature is inside. Maybe it will look better when it's grown up. Something in the vaults should speed it along.\""}
MultiLanguageItemData['en'][204367] = {name = "[q3]Sleeping Ancient Mammoth", additional_info = "Binds when picked up\n[q2]Use: Combine your Sleeping Ancient Mammoth and an Emerald Dragon Brooch to waken it.\n[q]\"Your altered egg grew into a mammoth? That doesn't seem right, but there's no use stopping now. Find a way to wake it up and claim your prize!\""}
MultiLanguageItemData['en'][204369] = {name = "[q3]Scrap of Black Dragonscales", additional_info = "Binds when picked up\n[q2]Use: Combine the Strange Petrified Orb and a Scrap of Black Dragonscales to reverse the petrification.\n[q]\"A glimmer of earth magic still resides within these molted black dragon scales. It might be able to reverse minor petrifications.\""}
MultiLanguageItemData['en'][204370] = {name = "Stinky Bright Potion", additional_info = "Toxic\n[q2]Use: Brightens the world around you.\n[q]\"Mix two parts crushed saxifrage, one part pure decay, and throw in some mysterious spores to keep the imbiber on their toes.\"\nSell Price:"}
MultiLanguageItemData['en'][204371] = {name = "[q3]Drop of Blue Dragon Magic", additional_info = "Binds when picked up\n[q2]Use: Combine your Particularly Ordinary Egg and a Drop of Blue Dragon Magic to enchant it.\n[q]\"The picture on the vial is hard to make out, but you're sure it's a dragon. They should consider relabeling these.\""}
MultiLanguageItemData['en'][204372] = {name = "[q3]Speck of Bronze Dust", additional_info = "Binds when picked up\n[q2]Use: Combine your Egg of Unknown Contents and a Speck of Bronze Dust to age your egg.\n[q]\"Nobody would hide dust in a treasure vault. This is likely a potent bronze dragon catalyst for time magic. Be careful not to use too much!\""}
MultiLanguageItemData['en'][204373] = {name = "[q3]Banged-up Rumble Foil", additional_info = "[q7]Binds to Warband\n[q2]Use: Flatten this out.\n[q]\"Flatten this out.\""}
MultiLanguageItemData['en'][204374] = {name = "[q3]Emerald Dragon Brooch", additional_info = "Binds when picked up\n[q2]Use: Combine your Sleeping Ancient Mammoth and an Emerald Dragon Brooch to waken it.\n[q]\"Though cracked, you can feel the power of the Emerald Dream hidden within. This should wake any creature.\""}
MultiLanguageItemData['en'][204375] = {name = "[q3]Everburning Ruby Coals", additional_info = "Binds when picked up\n[q2]Use: Combine your Magically Altered Egg and some Everburning Ruby Coals to hatch it.\n[q]\"A handful of coals that are warm to the touch. This must be from the healing fires of an ancient Red Dragon. Maybe this can help grant life in something small.\""}
MultiLanguageItemData['en'][204377] = {name = "Glow Spores", additional_info = "Quest Item\n[q]\"Glowing fungus that sniffing mice have a particular aptness to track down.\""}
MultiLanguageItemData['en'][204378] = {name = "[q4]Brimming Dragonscale Expedition Supply Pack", additional_info = "[q7]Binds to Warband\n[q]\"Contains a variety of rewards for those who have proven themselves true allies of the Dragonscale Expedition.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][204379] = {name = "[q4]Brimming Iskaaran Supply Pack", additional_info = "[q7]Binds to Warband\n[q]\"Contains a variety of rewards for those who have proven themselves true allies of the Iskaara Tuskarr.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][204380] = {name = "[q4]Brimming Maruuk Centaur Supply Satchel", additional_info = "[q7]Binds to Warband\n[q]\"Contains a variety of rewards for those who have proven themselves true allies of the Maruuk Centaur.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][204381] = {name = "[q4]Brimming Valdrakken Accord Supply Pack", additional_info = "[q7]Binds to Warband\n[q]\"Contains a variety of rewards for those who have proven themselves true allies of the Valdrakken Accord.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][204382] = {name = "[q4]Noble Bruffalon", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"It is a great honor to be trusted with one of the Maruuk's loyal hunting companions. This Bruffalon is reliable and steadfast through any hardship.\"\nVendor:\nStorykeeper Ashekh\nZone:\nThe Forbidden Reach\nCost:\n100000"}
MultiLanguageItemData['en'][204383] = {name = "[q3]Sack of Oddities", additional_info = "Binds when picked up\n[q]\"The Dragonscale Expedition collect such a wide assortment of trinkets and baubles even they aren't certain what's inside.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][204386] = {name = "[q3]Pocket Darkened Elemental Core", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+329 [Agility or Strength or Intellect]\n[q2]Use: Throw a small Darkened Elemental Core at the target location dealing 63430 Shadowflame damage split between all enemies. (1 Min, 30 Sec Cooldown)\n[q]\"Even at this size, elemental cores can syphon enough of the surrounding Shadowflame energy to turn into a small but deadly explosive.\"\nSell Price:"}
MultiLanguageItemData['en'][204387] = {name = "[q3]Buzzing Orb Core", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+320 [Agility or Strength or Intellect]\n[q2]Equip: Slowly build up stacks of titan energy. The amount of stacks gained per second can vary but when fully charged at 120 stacks the Buzzing Orb Core will increase a random secondary stat by 1075 , as well as your movement speed by 1075 for 20 sec.\n[q]\"This titan artifact stores energy that can be used to power the carrier's abilities.\"\nSell Price:"}
MultiLanguageItemData['en'][204388] = {name = "[q3]Draconic Cauterizing Magma", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+329 Intellect\n[q2]Use: Shield an ally for 53847 while channeling a beam of molten flame dealing [ 1264 * (5)] Fire damage over 2.5 sec to them. If they survive the channel, heal them for 134618 . (2 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][204389] = {name = "[q3]Stone Breaker", additional_info = "Binds when picked up\nToy\n[q2]Use: Have a smashing good time! (10 Min Cooldown)\n[q]\"Absolutely smashing!\""}
