MultiLanguageItemData['en'][205200] = {name = "[q2]Stirring Twilight Ember", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+244 [Agility or Strength or Intellect]\n[q2]Equip: Your abilities have a chance to ignite the ember, dealing 18935 Shadowflame damage to yourself over 10 sec and increasing your Haste by 1367 .\n[q2]Equip: Taking Shadowflame damage has a chance to increase your Speed by 382 for 10 sec.\nSell Price:"}
MultiLanguageItemData['en'][205201] = {name = "[q2]Smoldering Howler Horn", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+244 [Agility or Strength or Intellect]\n[q2]Use: Call a hound to unleash a smoldering howl, increasing your Critical Strike by 1230 for 20 sec. (1 Min, 30 Sec Cooldown)\nSell Price:"}
