MultiLanguageItemData['en'][205203] = {name = "[q4]Cobalt Shalewing", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Brood of Karokta, raised in the underlight of Zaralek Cavern.\"\nDrop:\nKarokta\nZone:\nZaralek Cavern"}
MultiLanguageItemData['en'][205204] = {name = "[q4]Flaming Shalewing Subject 01", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon a Cataloged Shalewing mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"The first instance of a flaming shalewing ever discovered. Nine out of ten researchers agree: it's hot!\"\nZone:\nZaralek Cavern\nPublic Event:\nResearchers Under Fire"}
MultiLanguageItemData['en'][205205] = {name = "[q4]Shadowflame Shalewing", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Born from the magma, its carapace was originally molten blobs cooled to form dark-colored volcanic rock. Being imbued by shadowflame has only solidified its unbreakable nature.\"\nAchievement:\nGlory of the Aberrus Raider"}
MultiLanguageItemData['en'][205207] = {name = "[q4]Morsel Sniffer Reins", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 18 with the Loamm Niffen.\n\n\n[q]\"A breed of shalewings trained by the niffen to find the deepest of morsels.\"\nVendor:\nHarlowe Marl\nZone:\nZaralek Cavern\nCost:\n800"}
MultiLanguageItemData['en'][205208] = {name = "[q4]Sandy Shalewing", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"The patterns on the wings of that creature resemble sand flowing through an hourglass. One could gaze upon them for ages...\"\nVendor:\nAny Timewalking Vendor\nCost:\n5000"}
MultiLanguageItemData['en'][205209] = {name = "[q4]Boulder Hauler Reins", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"These shalewings have been specially trained to carry large amounts of Barter Boulders for the niffen's bartering activities.\"\nVendor:\nPonzo\nZone:\nZaralek Cavern\nCost:\n85"}
