MultiLanguageItemData['en'][206012] = {name = "[q3]Designs of Mind", additional_info = "Binds when picked up\n[q2]Use: Combine the Ouroboros Tablet with Designs of Mind.\n[q]\"Decorated in ancient symbols of mind and fire.\""}
MultiLanguageItemData['en'][206013] = {name = "[q3]Designs of Soul", additional_info = "Binds when picked up\n[q2]Use: Combine the Ouroboros Tablet with Designs of Soul.\n[q]\"Decorated in ancient symbols of soul and air.\""}
MultiLanguageItemData['en'][206014] = {name = "[q3]Ouroboros Tablet", additional_info = "Binds when picked up\n[q2]Use: Combine the Ouroboros Tablet with Designs of Bone.\n[q]\"Circular designs show a large spiral pattern starting from the left side. Symbols of water and blood flow into it and the missing spaces along the bottom.\""}
MultiLanguageItemData['en'][206015] = {name = "[q3]Ouroboros Tablet", additional_info = "Binds when picked up\n[q2]Use: Combine the Ouroboros Tablet with Designs of Mind.\n[q]\"Symbols of bone and earth line the pathway of the spiral design as it continues up from the bottom and into the missing right side.\""}
MultiLanguageItemData['en'][206016] = {name = "[q3]Ouroboros Tablet", additional_info = "Binds when picked up\n[q2]Use: Combine the Ouroboros Tablet with Designs of Soul.\n[q]\"As symbols of mind and fire wrap around the carved spiral, they move inward and up into the open space at the top.\""}
MultiLanguageItemData['en'][206017] = {name = "[q3]Ouroboros Tablet", additional_info = "Binds when picked up\n[q2]Use: Combine the Ouroboros Tablet with the Kob'rok's Luminescent Scale.\n[q]\"Delicately drawn symbols of soul and air decorate the top as the spiral continues inward. The ouroboros in the center glows brightly as a violet energy is siphoned through the spiral and into the center.\""}
