MultiLanguageItemData['en'][206564] = {name = "Time-Displaced Titanic Disc", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\n[q]\"This item is clearly of titan origin. Despite the saliva dripping from it, it still appears to be functional.\""}
MultiLanguageItemData['en'][206565] = {name = "[q3]Plagued Grain", additional_info = "Binds when picked up\nToy\n[q2]Use: Place down a crate of ordinary grain for 3 min. Nobody will suspect a thing. (2 Hrs Cooldown)\n[q]\"A crate postmarked for Light's Hope Chapel. Fortunately, it never arrived.\""}
MultiLanguageItemData['en'][206566] = {name = "[q4]Reins of the Scarlet Pterrordax", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon a Scarlet Pterrordax.\n[q2]Summons and dismisses your Scarlet Pterrordax.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"This pterrordax was so eager to take to the skies that its handler couldn't finish training it.\"\nQuest:\nTime to Fly"}
MultiLanguageItemData['en'][206567] = {name = "[q4]Harbor Gryphon", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon a Harbor Gryphon.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"This gryphon was the runt of its pride, left behind when its brethren were sent for training. Today, however, it is ready to prove its worth.\"\nQuest:\nTime to Fly"}
