MultiLanguageItemData['en'][206653] = {name = "Fel Pinecone", additional_info = "Binds when picked up\nUnique (4)\nRequires level 70 to 70 ( 70)\n[q]\"Fel, foul, rotten - perfect for stuffing up a fel cannon!\""}
MultiLanguageItemData['en'][206670] = {name = "[q3]Darkroot Grippers", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: Wear a pair of Darkroot Grippers over your armor allowing you to pull Shadowrooted Vines out of the ground.\n\n Vines can be found in the Fungal Field and nearby keyflame areas. (5 Sec Cooldown)\n[q]\"Tough armored gloves to grasp lasher vines safely.\""}
MultiLanguageItemData['en'][206671] = {name = "[q4]Obsidian Gladiator's Halberd", additional_info = "Binds when picked up\n{Two-Hand} {Polearm}\n{836 - 1,553 Damage} {Speed 3.60}\n(331.8 damage per second)\n+441 Strength\n+1,295 Stamina\n[q2]+ 207 Haste\n[q2]+ 517 Versatility\nDurability 120 / 120\nSell Price:"}
MultiLanguageItemData['en'][206673] = {name = "[q4]Horn of the White War Wolf", additional_info = "[q7]Binds to Warband\nMount\n[q0](Account-wide)\nRequires any Horde race\n[q2]Use: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Can a wolf's hunger ever be satiated? These lupine brutes seek and devour the enemies of the Horde.\"\nHorde\nDrop:\nTime Rifts\nVendor:\nWarden Krizzik\nZone:\nTyrhold Reservoir\nCost:\n3000\n\nAlliance\nItem:\nGift of the White War Wolf"}
MultiLanguageItemData['en'][206674] = {name = "[q4]Reins of the Ravenous Black Gryphon", additional_info = "[q7]Binds to Warband\nMount\n[q0](Account-wide)\nRequires any Alliance race\n[q2]Use: Teaches you how to summon a Ravenous Black Gryphon.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"War corrupted these once-proud creatures. The susurration of their wings now whispers omens of imminent demise.\"\nAlliance\nDrop:\nTime Rifts\nVendor:\nWarden Krizzik\nZone:\nTyrhold Reservoir\nCost:\n3000\n\nHorde\nItem:\nGift of the Ravenous Black Gryphon"}
MultiLanguageItemData['en'][206675] = {name = "[q4]Gold-Toed Albatross", additional_info = "[q7]Binds to Warband\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Soaring from a distant timeway, this never-before-seen avian variant was born in a world of order.\"\nDrop:\nTime Rifts\nVendor:\nSorotis\nZone:\nTyrhold Reservoir\nCost:\n3000"}
MultiLanguageItemData['en'][206676] = {name = "[q4]Felstorm Dragon", additional_info = "[q7]Binds to Warband\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"The Burning Legion defeated dragons in a distant timeway. These foul fel wyrms chose corruption and servitude over destruction.\"\nDrop:\nTime Rifts\nVendor:\nFalara Nightsong\nZone:\nTyrhold Reservoir\nCost:\n3000"}
MultiLanguageItemData['en'][206678] = {name = "[q4]Sulfur Hound's Leash", additional_info = "[q7]Binds to Warband\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"The Black Empire subjugated these humbled and hateful hounds. Utterly obedient, they still serve the strong.\"\nDrop:\nTime Rifts\nVendor:\nProvisioner Qorra\nZone:\nTyrhold Reservoir\nCost:\n3000"}
MultiLanguageItemData['en'][206679] = {name = "[q4]Perfected Juggernaut", additional_info = "[q7]Binds to Warband\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon Perfected Juggernaut. This is a ground mount.\n[q2]Summons and dismisses Juggernaut Perfected.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Perfection, like beauty, is in the eye of the beholder. But eyesight can be surgically enhanced.\"\nDrop:\nTime Rifts\nVendor:\nGill the Drill\nZone:\nTyrhold Reservoir\nCost:\n3000"}
MultiLanguageItemData['en'][206680] = {name = "[q4]Reins of the Scourgebound Vanquisher", additional_info = "[q7]Binds to Warband\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Once bound in service to the Scourge, these undead dragons exist only to spread death, disease, and destruction.\"\nDrop:\nTime Rifts\nVendor:\nBaron Silver\nZone:\nTyrhold Reservoir\nCost:\n3000"}
