MultiLanguageItemData['en'][206696] = {name = "[q3]Tricked-Out Thinking Cap", additional_info = "Secrets of Azeroth\nBinds when picked up\nToy\n[q2]Use: Equip your Tricked-Out Thinking Cap to start tracking coordinates from your location, and listen for any stray thoughts.\n\n Used to solve the Secrets of Azeroth.\n[q]\"Equipped with a Cogs-and-Bolts-o-Meter.\"\nSell Price:"}
MultiLanguageItemData['en'][206749] = {name = "Oil-Soaked Log Book", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\n[q]\"Despite the oil dripping from it, there is enough legible text to provide some clue as to the nature of the timeline this came from.\""}
