MultiLanguageItemData['en'][206771] = {name = "[q4]Pattern: Cursed Cloth", additional_info = "[q7]Binds to Warband\n[q2]Use: Teaches you how to craft Cursed Cloth.\n[q2]This cursed item latches onto the first soul it comes into contact with and thus can only be created for others via a Crafting Order.\nRequires Classic Tailoring (300)\nRequires the achievement Drop Dead, Gorgeous to be completed.\nSell Price:\n[q4]Cursed Cloth\nBinds when picked up\n[q2]Use: Repair a piece of Lamented Crusader's equipment with corrupted materials, partially restoring it to its former glory.\n\n The resulting item will become Warbound and the desecration can be purified by a Mage, Priest, or Warlock who is willing to acquire the necessary reagents.\nSell Price:\nRequires Wartorn Scrap (50), Felcloth (20), Essence of Undeath (6), Dark Rune (2), Frozen Rune"}
MultiLanguageItemData['en'][206772] = {name = "[q4]Pattern: Languished Leather", additional_info = "[q7]Binds to Warband\n[q2]Use: Teaches you how to craft Languished Leather.\n[q2]This cursed item latches onto the first soul it comes into contact with and thus can only be created for others via a Crafting Order.\nRequires Classic Leatherworking (300)\nRequires the achievement Drop Dead, Gorgeous to be completed.\nSell Price:\n[q4]Languished Leather\nBinds when picked up\n[q2]Use: Repair a piece of Lamented Crusader's equipment with corrupted materials, partially restoring it to its former glory.\n\n The resulting item will become Warbound and the desecration can be purified by a Druid or Rogue who is willing to acquire the necessary reagents.\nSell Price:\nRequires Wartorn Scrap (50), Enchanted Leather (40), Essence of Undeath (6), Dark Rune (2), Frozen Rune"}
MultiLanguageItemData['en'][206773] = {name = "[q4]Pattern: Scourged Scales", additional_info = "[q7]Binds to Warband\n[q2]Use: Teaches you how to craft Scourged Scales.\n[q2]This cursed item latches onto the first soul it comes into contact with and thus can only be created for others via a Crafting Order.\nRequires Classic Leatherworking (300)\nRequires the achievement Drop Dead, Gorgeous to be completed.\nSell Price:\n[q4]Scourged Scales\nBinds when picked up\n[q2]Use: Repair a piece of Lamented Crusader's equipment with corrupted materials, partially restoring it to its former glory.\n\n The resulting item will become Warbound and the desecration can be purified by a Hunter or Shaman who is willing to acquire the necessary reagents.\nSell Price:\nRequires Wartorn Scrap (50), Enchanted Leather (40), Essence of Undeath (6), Dark Rune (2), Frozen Rune"}
MultiLanguageItemData['en'][206774] = {name = "[q4]Plans: Undeath Metal", additional_info = "[q7]Binds to Warband\n[q2]Use: Teaches you how to craft Undeath Metal.\n[q2]This cursed item latches onto the first soul it comes into contact with and thus can only be created for others via a Crafting Order.\nRequires Classic Blacksmithing (300)\nRequires the achievement Drop Dead, Gorgeous to be completed.\nSell Price:\n[q4]Undeath Metal\nBinds when picked up\n[q2]Use: Repair a piece of Lamented Crusader's equipment with corrupted materials, partially restoring it to its former glory.\n\n The resulting item will become Warbound and the desecration can be purified by a Paladin or Warrior who is willing to acquire the necessary reagents.\nSell Price:\nRequires Wartorn Scrap (50), Arcanite Bar (10), Essence of Undeath (6), Dark Rune (2), Frozen Rune"}
MultiLanguageItemData['en'][206775] = {name = "Map to Suramar", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\n[q]\"It's not clear if this timeway's Suramar is hidden, but it does seem to be in the same place as the Suramar in your own timeline.\""}
