MultiLanguageItemData['en'][206956] = {name = "[q4]Paracausal Fragment of Sulfuras", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+396 [Agility or Strength]\n[q2]Equip: Your melee swings have a chance to deal 9875 additional Fire damage. Your harmful melee abilities have a chance to make the Fragment erupt, dealing 8229 Fire damage split between all nearby enemies. The Fragment also has a chance to react to your damage taken, counterattacking for 9875 Fire damage.\nSell Price:"}
MultiLanguageItemData['en'][206957] = {name = "Boffins", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\n[q]\"This little robot happily jumped into your arms as you picked it up. It buzzes happily in your pack and almost sounds like it's purring.\""}
