MultiLanguageItemData['en'][208572] = {name = "[q4]Azure Worldchiller", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount. This is a flying mount.\n[q2]Summons and dismisses this mount. This mount changes depending on your riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"In the corners of Azeroth, stories are told of a dreaded dragon who swept a pall of torment over the land. In some versions of this story, his fiery presence brought cataclysmic death and destruction worldwide. In other versions, he is blue.\"\nDrop:\nDoomwalker\nZone:\nTanaris"}
MultiLanguageItemData['en'][208576] = {name = "Thriving Restoration Mote", additional_info = "Quest Item\n[q]\"A mote capable of restoring the Tattered Dreamleaf a large amount.\""}
MultiLanguageItemData['en'][208577] = {name = "[q5]Symbiotic Glowspore Grip", additional_info = "Binds when picked up\n[q]\"This adaptive grip is capable of withstanding immense amounts of fluctuating shadowflame. Crafted in tandem with Master Leatherworker Erden.\""}
