MultiLanguageItemData['en'][208614] = {name = "[q4]Augury of the Primal Flame", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 616 Critical Strike\n[q2]Equip: Your spells and abilities have a low chance to grant Annihilating Flame for 20 sec, causing your critical strikes to deal 50% additional damage as Fire split between nearby enemies. The Flame may deal [ 97891 * (1 + Versatility)] total damage before fading, further increased by critical strikes.\n\n Damage and cap increased per enemy struck, up to 5.\n[q]\"A vision of endless flame.\"\nSell Price:"}
MultiLanguageItemData['en'][208615] = {name = "[q4]Nymue's Unraveling Spindle", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+570 Intellect\n[q2]Use: Channel to unravel your target's essence, dealing 247877 Nature damage over 3 sec and granting you up to 2790 Mastery for 18 sec.\n\n Damage increased by 30% against immobilized targets. (2 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][208616] = {name = "[q4]Dreambinder, Loom of the Great Cycle", additional_info = "Binds when picked up\n{Two-Hand} {Staff}\n{690 - 934 Damage} {Speed 3.60}\n(225.6 damage per second)\n+2,666 Intellect\n+2,128 Stamina\n[q2]+ 581 Haste\n[q2]+ 282 Mastery\nDurability 120 / 120\n[q2]Use: Weave a web of dreams beneath your target after 2 sec, dealing 80339 Nature damage split between all enemies within 8 yds. Your target is immobilized for 4 sec while additional enemies are slowed by 80%. Less effective against enemy players.\n\n Damage increased per enemy struck, up to 5. (2 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][208617] = {name = "[q2]Ebon Blade Commendation Badge", additional_info = "Binds when picked up\n[q2]Use: Increases your Knights of the Ebon Blade reputation by 260."}
