MultiLanguageItemData['en'][208937] = {name = "A Muddy Journal", additional_info = "[q]\"You found this journal in the grass, its pages are covered with mud. The very last pages of its content is a window to a broken soul.\"\n[q2]<Right Click to Read>\nSell Price:"}
MultiLanguageItemData['en'][208938] = {name = "Metamorphic Soot", additional_info = "Quest Item\n[q]\"The lingering embers in this ash seem to change shape as you watch them.\""}
MultiLanguageItemData['en'][208939] = {name = "[q4]Gorridar, Darkblade of the Sunderer", additional_info = "Cosmetic\n[q7]Binds to Warband\n{One-Hand} {Sword}\n{1 Damage} {Speed 2.60}\n(0.4 damage per second)\nThis item is not available for direct sale. Consult your Traveler's Log for how to obtain the Cosmic Weapon Cache.\n[q]\"Malice and hatred honed into a weapon designed to lay waste to entire worlds. Beware of any who envy such a blade.\"\n[q2]Use: Add this appearance to your Warband collection.\nSell Price:"}
MultiLanguageItemData['en'][208940] = {name = "[q4]Voidsong, Stave of the Harbinger", additional_info = "Cosmetic\n[q7]Binds to Warband\n{Two-Hand} {Staff}\n{1 - 2 Damage} {Speed 3.60}\n(0.4 damage per second)\nThis item is not available for direct sale. Consult your Traveler's Log for how to obtain the Cosmic Weapon Cache.\n[q]\"A gift of Dimensius bestowed at the height of the Black Empire. Those touched by shadow are drawn to its haunting whispers.\"\n[q2]Use: Add this appearance to your Warband collection.\nSell Price:"}
MultiLanguageItemData['en'][208941] = {name = "[q4]M'thorus, Dagger of the Grand Design", additional_info = "Cosmetic\n[q7]Binds to Warband\n{One-Hand} {Dagger}\n{1 Damage} {Speed 1.80}\n(0.6 damage per second)\nThis item is not available for direct sale. Consult your Traveler's Log for how to obtain the Cosmic Weapon Cache.\n[q]\"Shadows cannot be allowed to fester. Disorder must be struck down wherever it takes hold. True children of the titans will heed their makers' call.\"\n[q2]Use: Add this appearance to your Warband collection.\nSell Price:"}
MultiLanguageItemData['en'][208942] = {name = "Preservationist's Dispatch Three", additional_info = "Secrets of Azeroth\nBinds when picked up\n[q]\"A note describing an orb artifact that the Preservationists need to be collected.\"\n[q2]<Right Click to Read>"}
MultiLanguageItemData['en'][208943] = {name = "[q4]Arsenal: Cosmic Weapons Cache", additional_info = "[q7]Binds to Warband\n[q2]Use: Collect the appearances contained in the Cosmic Weapons Cache.\n[q]\"Armaments forged from the primal fabric of the cosmos. Who assembled this collection and why remains a mystery. Wielding them will draw the eye of those who covet such power.\""}
MultiLanguageItemData['en'][208944] = {name = "Orb of Rathmus", additional_info = "Secrets of Azeroth\nBinds when picked up\nThis Item Begins a Quest\n[q]\"Titan script adorns the metal bands encircling the glowing orb.\""}
MultiLanguageItemData['en'][208945] = {name = "[q7]Paracausal Crate", additional_info = "[q7]Binds to Warband\n[q2]Use: Open to gain 500 Paracausal Flakes.\n[q]\"Unfortunately, for the health of the timeline, it is recomended this be opened after being sent.\""}
MultiLanguageItemData['en'][208946] = {name = "Burning Rune", additional_info = "Quest Item\n[q]\"A mysterious etching that emanates an uncomfortable heat.\""}
MultiLanguageItemData['en'][208947] = {name = "Enchanted Watering Can", additional_info = "Quest Item\nUnique\n[q2]Use: Sprinkle water upon enchanted shrubs, giving them the energy to deliver themselves to Magnolia Oaken.\n[q]\"More powerful than an average watering can.\""}
MultiLanguageItemData['en'][208949] = {name = "Heated Hearthstone", additional_info = "Quest Item\n[q]\"Warm and inviting, great for heating up hands.\""}
MultiLanguageItemData['en'][208950] = {name = "Emerald Fiber", additional_info = "Quest Item\n[q]\"A hearty fiber that possesses remarkable tensile strength.\""}
MultiLanguageItemData['en'][208951] = {name = "[q7]Paracausal Cluster", additional_info = "[q7]Binds to Warband\n[q2]Use: Crush to gain 1000 Paracausal Flakes.\n[q]\"A crystal formation emerging just before the collision of two timeways, made of compressed sands of time.\""}
MultiLanguageItemData['en'][208952] = {name = "[q7]Soridormi's Letter of Commendation", additional_info = "[q7]Binds to Warband\n[q2]Use: Read to gain 1000 reputation with Soridormi.\n[q]\"A letter of recognition signed by Soridormi.\""}
MultiLanguageItemData['en'][208955] = {name = "Pilfered Dreamshard", additional_info = "Quest Item"}
MultiLanguageItemData['en'][208956] = {name = "Intact Primalist Garb", additional_info = "Quest Item\n[q]\"It is a good thing blood on the clothes was optional. It may have taken a very long time otherwise.\""}
MultiLanguageItemData['en'][208957] = {name = "Conduit of the Southern Storm", additional_info = "Quest Item\nRequires level 80 to 80 ( 80)\n[q]\"This ancient obelisk looks to have been carved from a piece of electrically charged glass or crystal.\""}
MultiLanguageItemData['en'][208958] = {name = "Ancient Tyrhold Artifact Notes", additional_info = "Secrets of Azeroth\nBinds when picked up\n[q]\"Contains notes written by Kathos and Bobby regarding the artifact's safeguards at Tyrhold.\"\n[q2]<Right Click to Read>"}
MultiLanguageItemData['en'][208959] = {name = "[q4]Taesavir, Sword of the Grand Design", additional_info = "Cosmetic\n[q7]Binds to Warband\n{One-Hand} {Sword}\n{1 Damage} {Speed 2.60}\n(0.4 damage per second)\nThis item is not available for direct sale. Consult your Traveler's Log for how to obtain the Cosmic Weapon Cache.\n[q]\"An edge so sharp it could only be honed by Aggramar himself. Any who defy the will of the titans should beware its wielder.\"\n[q2]Use: Add this appearance to your Warband collection.\nSell Price:"}
MultiLanguageItemData['en'][208960] = {name = "[q3]Titan Focusing Crystal", additional_info = "Secrets of Azeroth\nBinds when picked up\n[q]\"This is clearly one of the objects that was shattered and is needed for the second set of artifact locks.\""}
MultiLanguageItemData['en'][208962] = {name = "[q4]Seetheras, Broadsword of the Sunderer", additional_info = "Cosmetic\n[q7]Binds to Warband\n{Two-Hand} {Sword}\n{1 - 2 Damage} {Speed 3.60}\n(0.4 damage per second)\nThis item is not available for direct sale. Consult your Traveler's Log for how to obtain the Cosmic Weapon Cache.\n\"Forged from malignant chaos to strike at the target's heart. Those whose souls burn with all-consuming rage are drawn to its dark fire.\"\n[q2]Use: Add this appearance to your Warband collection.\nSell Price:"}
