MultiLanguageItemData['en'][209947] = {name = "[q4]Reins of the Blossoming Dreamstag", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 18 with the Dream Wardens.\nSell Price:\n[q]\"The pelts of young dreamstags flower with the vibrant colors of the dream.\"\nVendor:\nTalisa Whisperbloom\nZone:\nEmerald Dream\nCost:\n1"}
MultiLanguageItemData['en'][209948] = {name = "[q3]Spring's Keeper", additional_info = "Binds when picked up\n{Two-Hand} {Polearm}\n{1,007 - 1,872 Damage} {Speed 3.60}\n(399.9 damage per second)\n+531 Strength\n+1,759 Stamina\n[q2]+ 283 Haste\n[q2]+ 525 Mastery\nDurability 120 / 120\n[q2]Use: Transforms Spring's Keeper into Winter's Stand.\n[q2]Equip: Autoattacks have a chance to heal a nearby ally for 24357 .\nSell Price:"}
MultiLanguageItemData['en'][209949] = {name = "[q4]Reins of the Suntouched Dreamstag", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 17 with the Dream Wardens.\nSell Price:\n[q]\"The sun's radiant energy nurtures these dreamstags, helping them rapidly reach maturity.\"\nVendor:\nMoon Priestess Lasara\nZone:\nEmerald Dream\nCost:\n1200"}
MultiLanguageItemData['en'][209950] = {name = "[q4]Reins of the Rekindled Dreamstag", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 18 with the Dream Wardens.\nSell Price:\n[q]\"Ashes of fallen leaves are fertile soil for dreamstags to arise from.\"\nVendor:\nTalisa Whisperbloom\nZone:\nEmerald Dream\nCost:\n1"}
MultiLanguageItemData['en'][209951] = {name = "[q4]Reins of the Lunar Dreamstag", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 17 with the Dream Wardens.\nSell Price:\n[q]\"The moon's pale light is reflected in the pelt of these elusive nocturnal creatures.\"\nVendor:\nMoon Priestess Lasara\nZone:\nEmerald Dream\nCost:\n1200"}
