MultiLanguageItemData['en'][209996] = {name = "Tethercoil Rune", additional_info = "Binds when picked up\n[q2]Use: Inflict Tethercoil Siphon to yourself by binding to any Rare creature in the Emerald Dream.\n\n Defeating Rare creatures while Tethercoil Siphon is active will earn Taut Tethercoil. (5 Sec Cooldown)\n[q]\"Lydiara's rune to siphon Taut Tethercoil from powerful creatures throughout the Emerald Dream.\""}
MultiLanguageItemData['en'][209997] = {name = "[q3]Distilled Knowledge of Timeways", additional_info = "[q7]Binds to Warband\nUnique (5)\n[q2]Use: Increases experience gained from killing monsters and completing quests by 5%.\n\n Completing Timewalking dungeons increases the effect and refreshes the duration.\n\n Upon reaching 4 applications, transforms to Mastery of Timeways , increasing that effect to 30%."}
MultiLanguageItemData['en'][209998] = {name = "[q4]Lydiara's Binding Rune", additional_info = "Binds when picked up\n[q]\"Crafted in tandem with Lydiara Whisperfeather.\""}
MultiLanguageItemData['en'][209999] = {name = "Lydiara's Rune of Shadowbinding", additional_info = "Binds when picked up\n[q2]Use: Tether yourself to Gnarlroot, Igira, or Volcoross, becoming Shadowbound.\n\n While Shadowbound you will be afflicted with Roaring Shadowflame, slowing you between 0-50% based on the distance from your target and has a chance to hinder your mobility every 5 sec. (5 Sec Cooldown)\n[q]\"A Rune of Shadowbinding ready for attunement with Fyr'alath.\""}
MultiLanguageItemData['en'][210001] = {name = "[q4]Prototype Order Vellum", additional_info = "Binds when picked up\n[q]\"A prototype vellum made by Shalasar from flecks of radiant ash.\""}
MultiLanguageItemData['en'][210002] = {name = "Ashen Dowsing Rod", additional_info = "Quest Item\n[q2]Use: Extracts Radiant Fleck of Ash from powerful (EPIC) quality weapons or armor. The targeted item will be DESTROYED and will not be retrievable. (5 Min Cooldown)\n[q]\"A dowsing rod that allows the user the ability to disenchant powerful pieces of equipment in order to find Radiant Fleck of Ash.\""}
MultiLanguageItemData['en'][210003] = {name = "[q4]Shalasar's Sophic Vellum", additional_info = "Binds when picked up\n[q]\"Crafted in tandem with Shalasar Glimmerdusk.\""}
MultiLanguageItemData['en'][210005] = {name = "[q3]10.2 Monster - Weapon - Staff - 10.1.5 Weapon Staff - Staff_2H_Druid_C_02_Color1", additional_info = "Binds when equipped\n{Two-Hand} {Staff}\n{7 - 10 Damage} {Speed 3.60}\n(2.4 damage per second)\n+28 Intellect\n+9 Stamina\n[q2]+ 8 Critical Strike\n[q2]+ 5 Haste\nSell Price:"}
MultiLanguageItemData['en'][210008] = {name = "[q4]Smoldering Rune of Binding", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"By fire be purged the obstacles in your path!\"\nPromotion:\nCataclysm Classic"}
MultiLanguageItemData['en'][210009] = {name = "[q4]Prototype Dreamleaf Grip", additional_info = "Binds when picked up\n[q]\"A prototype rune made by Erden from leathery Shadowed Dreamleaf.\""}
MultiLanguageItemData['en'][210010] = {name = "Erden's Notes on Symbiotic Spores", additional_info = "Binds when picked up\n[q2]Use: Share Erden's notes with a friendly Leatherworker and temporarily teach them how to craft Erden's Dreamleaf Grip. Leatherworker must be in the same party. (30 Min Cooldown)\n[q]\"Notes detailing the necessities to craft an experimental Symbiotic Glowspore Grip. Written by Master Leatherworker Erden.\""}
MultiLanguageItemData['en'][210011] = {name = "Shalasar's Notes on Sophic Magic", additional_info = "Binds when picked up\n[q2]Use: Share Shalasar's notes with a friendly Enchanter and temporarily teach them how to craft Shalasar's Sophic Vellum. Enchanter must be in the same party. (30 Min Cooldown)\n[q]\"Notes detailing the necessities to craft an experimental Sophic Vellum. Written by Master Enchantress Shalasar Glimmerdusk.\""}
MultiLanguageItemData['en'][210012] = {name = "Erden's Symbiotic Glowspore Grip", additional_info = "Binds when picked up\n[q2]Use: Attempt to bind the Symbiotic Glowspore Grip to Fyr'alath, taking between 10-25% of your maximum health as shadowflame damage every second for 10 sec. (30 Sec Cooldown)\n[q]\"An untested Glowspore Grip.\""}
MultiLanguageItemData['en'][210014] = {name = "[q3]Mysterious Ageless Seeds", additional_info = "Quest Item\nUnique (20)\n[q2]Use: Plant a seed of the appropriate size at a nearby patch of Dreamseed Soil.\n[q]\"Dreamseeds waiting to be awakened.\""}
MultiLanguageItemData['en'][210016] = {name = "Somnowl's Shroud", additional_info = "Quest Item\nUnique\n[q2]Use: Enter stealth. Entering combat and casting abilities will break the effect. Enemies will detect you if you are too close to them. (8 Sec Cooldown)\n[q]\"Call upon somnowl Bodwin to give you a temporary stealth aura.\""}
