MultiLanguageItemData['en'][210052] = {name = "[q2]Ageless Blossom", additional_info = "Quest Item\n[q]\"This wondrous blossom contains many secrets.\""}
MultiLanguageItemData['en'][210054] = {name = "[q3]Forsaken Champion's Vest", additional_info = "Cosmetic\n[q7]Binds to Warband\n{Chest} {Cosmetic}\n[q2]Use: Add this appearance to your Warband collection.\nSell Price:"}
MultiLanguageItemData['en'][210057] = {name = "[q4]Reins of the Morning Flourish Dreamsaber", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 18 with the Dream Wardens.\nSell Price:\n[q]\"Known for the lavish energy that emanates from them, these sabers are notorious tricksters. Their roar scatters the early birds that wake them.\"\nVendor:\nTalisa Whisperbloom\nZone:\nEmerald Dream\nCost:\n1"}
MultiLanguageItemData['en'][210058] = {name = "[q4]Reins of the Evening Sun Dreamsaber", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 18 with the Dream Wardens.\nSell Price:\n[q]\"These dreamsabers are ferocious in battle, yet lethargic and often found lazily outstretched upon open fields. After soaking in the warmth of daylight, their flame flares that much brighter.\"\nVendor:\nTalisa Whisperbloom\nZone:\nEmerald Dream\nCost:\n1"}
MultiLanguageItemData['en'][210059] = {name = "[q4]Reins of the Winter Night Dreamsaber", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n[q]\"These nocturnal dreamsabers carry the chill of winter with them and will often hibernate for days on end if not otherwise awoken.\"\nDrop:\nDreamseed Cache\nZone:\nEmerald Dream"}
MultiLanguageItemData['en'][210060] = {name = "[q4]Reins of the Shadow Dusk Dreamsaber", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n[q]\"A dreamsaber strikes quickly from the shadows, capturing small animals and slipping back into darkness without a sound. The lucky few who have seen a feeding dreamsaber can see them revel in lazily toying with their prey before beginning their meal.\"\nAchievement:\nGlory of the Dream Raider\nCategory:\nDungeons & Raids"}
MultiLanguageItemData['en'][210061] = {name = "[q4]Reins of Anu'relos, Flame's Guidance", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses Anu'relos, Flame's Guidance.\n\n This mount can use Ride Along.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n[q]\"Though her feathers flicker with flame's destructive potential, they do not scorch, but simply radiate a comfortable heat.\"\nDrop:\nFyrakk\nZone:\nAmirdrassil, the Dream's Hope (Mythic)"}
