MultiLanguageItemData['en'][210826] = {name = "[q2]Harvestbot Repair Kit", additional_info = "Binds when picked up\nUnique\n[q2]Use: Learn the basics of using Radiant Remnants to repair Disabled Harvestbots.\n\n Once repaired they will help battle enemies near them.\n[q]\"Ezgi's instructions and tools to repair harvestbots.\"\nSell Price:"}
MultiLanguageItemData['en'][210827] = {name = "[q4]Ezgi's Gizmo", additional_info = "Binds when picked up\nUnique (10)\n[q2]Use: An emergency signal that activates available harvestbot to help clear Stillstone Pond and Torchlight Mine of threats.\nRequires Renown Rank 12 with the Hallowfall Arathi.\n[q]\"Once you've learned to fixed one, the rest are easy!\"\nSell Price:"}
MultiLanguageItemData['en'][210828] = {name = "Dilution Solution", additional_info = "Binds when picked up\nCrafting Reagent\n\"An alchemical reagent used for neutralizing the effects of potions and flasks. Can be purchased from Alchemy suppliers throughout Khaz Algar.\"\nSell Price:"}
MultiLanguageItemData['en'][210829] = {name = "[q3]Neutralize Concoctions", additional_info = "[q]\"Extract Coreway Catalysts from a large quantity of unwanted potions or flasks.\""}
MultiLanguageItemData['en'][210830] = {name = "Finished Rush'kah Mask", additional_info = "Quest Item\nRequires level 50 to 80 ( 80)\n[q]\"A newly created Darkspear rush'kah mask.\""}
MultiLanguageItemData['en'][210831] = {name = "[q4]Delugen", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nYou must have a Ottuk mount in your collection to be able to infuse a new one with dream energy.\n\n\n[q]\"Imagine being so engrossed by a dream that it feels real; some might even call it a delusion.\"\nVendor:\nElianna\nZone:\nEmerald Dream\nCost:\n1"}
MultiLanguageItemData['en'][210833] = {name = "[q4]Talont", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nYou must have a Dreamtalon mount in your collection to be able to infuse a new one with dream energy.\n\n\n[q]\"Some daydreams are filled with wondrous possibilities, but shatter when reminded of reality's limitations. Some dreams are not so burdened, even when they carry a rider.\"\nVendor:\nElianna\nZone:\nEmerald Dream\nCost:\n1"}
MultiLanguageItemData['en'][210834] = {name = "Archivist's Earth Totem", additional_info = "Quest Item\nUnique\n[q2]Use: Summons an earth totem to your location, to help with excavation. (5 Sec Cooldown)"}
