MultiLanguageItemData['en'][210929] = {name = "Comfort Food Package", additional_info = "Binds when picked up\n[q2]Use: Restores ( 630000 / 5 * 15) health over 15 sec. If you spend at least 15 seconds eating you will feel the love and gain a boost in morale for 2 hrs.\nRequiresLove is in the Air\n[q]\"Tasty treats for tough days.\""}
MultiLanguageItemData['en'][210939] = {name = "[q3]Null Stone", additional_info = "Crafting Reagent\n\"Sometimes gathered by players with the Mining skill. Can be bought and sold on the Auction House.\"\nSell Price:"}
MultiLanguageItemData['en'][210944] = {name = "[q4]Emerald Mark of Mastery", additional_info = "Dragonflight Season 3\nBinds when picked up\nUnique\n[q]\"Awarded for outstanding service to Dragonkind. Bring it to Theozhaklos the Curious at the Wellspring Overlook in the Emerald Dream to receive powerful equipment for your efforts.\""}
MultiLanguageItemData['en'][210945] = {name = "[q4]Stargrazer", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nYou must have a Dreamstag mount in your collection to be able to infuse a new one with dream energy.\n\n\n[q]\"One can't help but think what it might feel like to pluck the stars from their fixture in the sky. Perhaps, Stargrazer will show us how someday.\"\nVendor:\nElianna\nZone:\nEmerald Dream\nCost:\n1"}
MultiLanguageItemData['en'][210946] = {name = "[q4]Mammyth", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nYou must have a Magmammoth mount in your collection to be able to infuse a new one with dream energy.\n\n\n[q]\"In the Dream, sometimes the myth is more real than its basis.\"\nVendor:\nElianna\nZone:\nEmerald Dream\nCost:\n1"}
MultiLanguageItemData['en'][210947] = {name = "[q4]Flame-Warped Curio", additional_info = "Binds when picked up\n[q]\"A reminder of the fiery future Fyrakk sought. Kirasztia at the Wellspring Overlook in the Emerald Dream may know how to unlock the secrets that lay within.\"\nSell Price:"}
MultiLanguageItemData['en'][210948] = {name = "[q4]Imagiwing", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nYou must have a Shalewing mount in your collection to be able to infuse a new one with dream energy.\n\n\n[q]\"There's nothing more beautiful than watching your imagination take flight.\"\nVendor:\nElianna\nZone:\nEmerald Dream\nCost:\n1"}
MultiLanguageItemData['en'][210950] = {name = "[q3]Insight of Q'onzu", additional_info = "Binds when picked up\n[q2]Use: Grants the BEST amount of reputation with the Dream Wardens. (2 Sec Cooldown)\n[q]\"Who needs material possessions when you've witnessed Q'onzu?\""}
MultiLanguageItemData['en'][210951] = {name = "[q3]Treacherous Research Notes", additional_info = "Binds when picked up\n[q2]Use: Grants 250 reputation with the Dream Wardens. (2 Sec Cooldown)"}
MultiLanguageItemData['en'][210952] = {name = "[q3]Spare Heated Hearthstone", additional_info = "Binds when picked up\n[q2]Use: Grants 500 reputation with the Dream Wardens. (2 Sec Cooldown)\n[q]\"Seems to only be good for heating.\""}
