MultiLanguageItemData['en'][210961] = {name = "[q4]Alara'shinu", additional_info = "Binds when picked up\n{One-Hand} {Warglaive}\n{686 - 1,086 Damage} {Speed 2.60}\n(340.8 damage per second)\n+300 Agility\n+1,064 Stamina\n[q2]+ 194 Critical Strike\n[q2]+ 237 Mastery\nDurability 120 / 120\n[q]\"Finding beauty in imperfection.\"\nSell Price:"}
MultiLanguageItemData['en'][210964] = {name = "[q3]Lil' Wrathion", additional_info = "Binds when picked up\n[q2]Use: Teaches you how to summon and dismiss this companion.\n[q2]Right Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)"}
