MultiLanguageItemData['en'][210969] = {name = "[q4]Salatrancer", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nYou must have a Salamanther mount in your collection to be able to infuse a new one with dream energy.\n\n\n[q]\"While most salamanthers' attention jumps freely from one attraction to the next, this one enjoys long periods of deep observation.\"\nVendor:\nElianna\nZone:\nEmerald Dream\nCost:\n1"}
MultiLanguageItemData['en'][210970] = {name = "Crumbled Keepsake", additional_info = "Fungal Folly\n[q]\"An older keepsake meant to stay with the earthen whom it belonged to.\""}
MultiLanguageItemData['en'][210973] = {name = "[q4]Heartseeker Mana Ray", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount. This is a flying mount.\nSummons and dismisses a Heartseeker Mana Ray. This mount changes depending on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n[q]\"Someone once told this mana ray it was adorable. It has been pursuing that positive feeling ever since.\"\nWorld Event:\nLove is in the Air\nCost:\n270"}
