MultiLanguageItemData['en'][212227] = {name = "[q4]Reins of the Fur-endship Fox", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses the Fur-endship Fox mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"These magical creatures thrive on love and friendship.\"\nTrading Post"}
MultiLanguageItemData['en'][212228] = {name = "[q4]Reins of the Soaring Sky Fox", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses the Soaring Sky Fox mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Take to the sky on the most loyal and loving fox on Azeroth.\"\nIn-Game Shop"}
MultiLanguageItemData['en'][212229] = {name = "[q4]Reins of the Twilight Sky Prowler", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses the Twilight Sky Prowler mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Dubbed the midnight trickster by some, many a couple point to him as the reason their paths crossed in the night.\""}
MultiLanguageItemData['en'][212289] = {name = "Vicious Flask of Classical Spirits", additional_info = "[q2]Use: Drink to increase your mana regeneration by 8% whenever you have not cast a beneficial spell that costs mana for 5 sec.\n\n Honor gains increased by 15%.\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour.\nSell Price:"}
MultiLanguageItemData['en'][212292] = {name = "Vicious Flask of Honor", additional_info = "[q2]Use: Drink to increase honor gains by 15%. Can be used in all rated and unrated PvP environments.\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour.\nSell Price:"}
MultiLanguageItemData['en'][212295] = {name = "Vicious Flask of Manifested Fury", additional_info = "[q2]Use: Upon death, your rage manifests into a frenzied elemental to allow you to enact vengeance upon your foes for 10 sec. Can only occur once every 2 min.\n\n Honor gains increased by 15%.\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour.\nSell Price:"}
MultiLanguageItemData['en'][212298] = {name = "Vicious Flask of the Wrecking Ball", additional_info = "[q2]Use: Player killing blows increase your damage dealt by 8% and damage taken by 4% for 20 sec, stacking up to 5 times. If you are slain with this effect, your assailant takes a portion of this power.\n\n Honor gains increased by 15%.\n\nLasts 1 hour and through death. Consuming an identical flask will add another 1 hour.\nSell Price:"}
MultiLanguageItemData['en'][212317] = {name = "Recovered Tinderbox", additional_info = "Quest Item\n[q]\"Keep the holy flame with you, everywhere you go.\""}
MultiLanguageItemData['en'][212329] = {name = "Lynx Leash", additional_info = "Binds when picked up\nUnique (100)\n[q2]Use: Leash up a nearby Lynx allowing it to temporarily aid you in combat.\n\n Usable in Light's Blooming and nearby keyflame areas.\n[q]\"Lynxes love adventure!\"\nSell Price:"}
