MultiLanguageItemData['en'][212367] = {name = "[q3]Clutch of Wyrm's Awakened Crests", additional_info = "Binds when picked up\n[q2]Use: Collect 15 Wyrm's Awakened Crests. These crests ignore the seasonal cap.\nComplete the quest \"Dreaming of Crests\" from Vaskarn in Central Encampment to be able to downgrade your Dreaming Crests.\nYou must complete the quest \"Awakened Crests, Unlimited Possibilities\" from Vaskarn in Valdrakken to downgrade Awakened Crests."}
