MultiLanguageItemData['en'][212449] = {name = "[q4]Sikran's Endless Arsenal", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+1,914 [Agility or Strength]\n[q2]Equip: Assume a martial stance based on the last weapon drawn.\n[q2]Use: Surekian Flourish \nConjure dual swords from the Arsenal to rend your target, dealing ( 1 * 705278 ) Shadow damage over 3 sec. Gain 338 Parry and 225 Avoidance until the next weapon is drawn. (1 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][212450] = {name = "[q4]Swarmlord's Authority", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 1,001 Haste\n[q2]Equip: Your attacks and abilities have a high chance to summon a scarab that retrieves a fortifying chunk of flesh from your target. Scarabs deal 6915 Physical damage and reduce your damage taken by 50% until 172816 damage has been prevented.\n[q2]Use: Send your swarm into a frenzy, summoning 12 scarabs over 3 sec to ravage your foes. The number of scarabs is increased by your Haste. (1 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][212451] = {name = "[q4]Aberrant Spellforge", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+1,914 Intellect\n[q2]Equip: Accumulate dark power from the Spellforge every 15 sec to empower your next [specialization spell] to deal ( 1 * 73672 ) additional Shadow damage.\n[q2]Use: Recklessly intensify the power of the Spellforge, multiplying its current damage by 125% until shortly after leaving combat, up to 5 times. At full power, gain 830 Haste for 6 sec when empowering your [specialization spell].\n\n Beware glimpses of the Unseeming. (1 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][212452] = {name = "[q4]Gruesome Syringe", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 1,001 Critical Strike\n[q2]Equip: Your healing spells have a high chance to cause you to inject yourself with a charge of Volatile Serum . Multiple charges may overlap.\n\n If an ally drops below 70% health, expel a charge to heal them for 240979 . If unconsumed after 15 sec, charges catalyze to grant you 2894 Intellect for 10 sec instead.\nSell Price:"}
MultiLanguageItemData['en'][212453] = {name = "[q4]Skyterror's Corrosive Organ", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+1,914 Strength\n[q2]Use: Spray your target with volatile acid, dealing ( 1 * 7902 ) Nature damage every 1 sec for 20 sec.\n\n Your abilities intensify the acid's damage by an additional ( 1 * 7902 ) per sec for the remaining duration and splash up to 5 nearby enemies for ( 1 * 790 ) Nature damage per stack. (1s cooldown) (2 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][212454] = {name = "[q4]Mad Queen's Mandate", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 1,001 Critical Strike\n[q2]Use: Take what is rightfully yours, gorging on your target's essence to deal ( 1 * 2174283 ) Shadow damage and healing you for 320973 over 2 sec. Damage and healing increased based on the target's missing health.\n\n Cooldown reduced by 60 sec if this effect kills the target. (2 Min Cooldown)\nSell Price:"}
