MultiLanguageItemData['en'][212491] = {name = "Sweet Eclipse", additional_info = "Binds when picked up\nUnique (100)\n[q2]Use: Restores ( 80357 / 5 * 20) health over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and and gain the Sweet Eclipse buff, allowing you to increase Crit Chance 3% for each enemy killed when fighting in the shadows.\n\n Usable in Light's Blooming and nearby keyflame areas."}
MultiLanguageItemData['en'][212492] = {name = "Twilight-Spiced Grouper", additional_info = "Binds when picked up\nUnique (100)\n[q2]Use: Restores ( 80357 / 5 * 20) health over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become Well Fed, increase movement speed by 15%, and gain water walking while in Light's Blooming and nearby keyflame areas.\n\n Usable in Light's Blooming and nearby keyflame areas."}
