MultiLanguageItemData['en'][212682] = {name = "[q3]Water's Beating Heart", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 Intellect\n[q2]Equip: Periodically imbue yourself while in combat with tainted Primal Wellspring water reducing your Versatility by 38 and movement speed by 10% for 15 sec.\n Dispelling the water's impurities reverse the effect, increasing your Versatility by 161 , movement speed by 10% and granting all nearby allies a 1087 shield for 15 sec.\n[q]\"When held the curio slowly pulses, as water begins enveloping and tightening around your heart, slowing your heartbeat.\"\nSell Price:"}
MultiLanguageItemData['en'][212683] = {name = "[q3]Globe of Jagged Ice", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 Agility\n[q2]Use: Imbue your abilities with the globe's powers gaining 50 charges of Frozen Wellspring. Dealing damage consumes a charge dealing 42 additional Frost damage and apply Wellspring's Frost, slowing enemy movement speed by 2% per stack.\n\n When Frozen Wellspring is fully consumed shatter all targets afflicted with Wellspring's Frost dealing 141 Frost damage per stack split between all nearby targets. (2 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][212684] = {name = "[q3]Umbrelskul's Fractured Heart", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 Intellect\n[q2]Equip: Your harmful spells and abilities have a low chance to call upon tragic arcane powers to infect your target with Crystal Sickness, dealing [( 81 * 10 * 11) / 2] Arcane damage over 10 sec, increasing every second.\n\n Creatures, other than players and bosses, who drop below 5% health while afflicted will crystallize, die and infect a nearby enemy with Crystal Sickness. This can happen up to 3 times.\nSell Price:"}
MultiLanguageItemData['en'][212685] = {name = "[q3]Tome of Unstable Power", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 Intellect\n[q2]Equip: Your harmful spells have a chance to create 1 to 3 Arcane Illusions of yourself that channel for 3 sec before unleashing Arcane Barrage at your target's location dealing up to ( 2487 * 1.1) Arcane damage to all enemies in the area.\nSell Price:"}
