MultiLanguageItemData['en'][212754] = {name = "[q3]Crystalforged Cauldron", additional_info = "[q7]Binds to Warband\nCrafting Reagent\n[q]\"Durable enough to handle the most corrosive concoctions. Can be purchased from alchemy and blacksmithing suppliers on Khaz Algar for use in flask and potion cauldrons.\"\nSell Price:"}
MultiLanguageItemData['en'][212755] = {name = "Remnant Satchel", additional_info = "Quest Item\nUnique (200)\n[q]\"A satchel full of Radiant Remnants.\""}
MultiLanguageItemData['en'][212756] = {name = "[q3]Inexorable Resonator", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 [Agility or Strength]\n[q2]Equip: Falling below 75% health activates the defense matrix for up to 15 sec, absorbing 50% of damage taken up to a maximum of 16069 . While the matrix holds, the resonator pulses every 1 sec to deal 177 Fire damage to all nearby enemies. Damage is reduced beyond 8 enemies.\n\n This may only occur once every 1.5 min.\nSell Price:"}
MultiLanguageItemData['en'][212757] = {name = "[q3]Granyth's Enduring Scale", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 [Agility or Strength]\n[q2]Use: Reduce damage taken by 75% for 20 sec or until 22723 damage has been absorbed. Your Armor is increased by 179 while the shield holds, further increasing by 9 when struck, stacking up to 20 times. The shield explodes when broken, dealing 4970 Physical damage split between all nearby enemies.\n\n Damage increased per enemy struck, up to 5. (100ms cooldown) (2 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][212758] = {name = "[q2]Incendiary Terror", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: Your abilities have a chance to inflict additional Fire damage and horrify your enemy for 3 sec.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][212759] = {name = "[q2]Meteor Storm", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: Your abilities have a chance to conjure a hail of meteors, inflicting Fire damage to nearby enemies and stunning them for 3 sec.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][212760] = {name = "[q2]Wildfire", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: Your attacks have a chance to inflict Fire damage and spread Wildfire to a nearby enemy inflicting Fire damage every 1 sec for 10 sec.\n\n Wildfire stacks and spreads to nearby enemies, stacking up to 3 times.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][212761] = {name = "[q0]Pouch of Coins", additional_info = "[q]\"Someone must have hidden these for safekeeping long, long ago.\"\nSell Price:"}
MultiLanguageItemData['en'][212762] = {name = "[q2]Tarnished Horn Signet", additional_info = "Binds when picked up\n[q2]Use: Break down this relic into a small amount of Mysterious Fragments.\n[q]\"It seems the dracthyr got the idea for horn jewelry from the dragonkin who lived here before them.\"\nSell Price:"}
MultiLanguageItemData['en'][212763] = {name = "[q0]Spoiled Honeywine", additional_info = "[q]\"The liquid in this bottle is cloudy and dull. While not good for drinking, it may be worth studying.\"\nSell Price:"}
MultiLanguageItemData['en'][212764] = {name = "[q0]Fishing Net Fragment", additional_info = "[q]\"This bit of net was torn and repaired dozens of times before finally being stowed away.\"\nSell Price:"}
MultiLanguageItemData['en'][212765] = {name = "[q0]Fish Bones", additional_info = "[q]\"Covered in marks from draconic teeth, as if someone had enjoyed every last bite.\"\nSell Price:"}
MultiLanguageItemData['en'][212766] = {name = "[q0]Amphora Fragment", additional_info = "[q]\"If you look closely, you can see clawed thumbprints preserved in the clay.\"\nSell Price:"}
MultiLanguageItemData['en'][212767] = {name = "[q0]Broken Beaker", additional_info = "[q]\"The neck has been broken off this beaker, so that it may better serve as a drinking vessel.\"\nSell Price:"}
MultiLanguageItemData['en'][212768] = {name = "[q0]Niffen-Sized Dagger", additional_info = "[q]\"This dagger is the perfect shape to be held in wide, clawed hands.\"\nSell Price:"}
