MultiLanguageItemData['en'][213163] = {name = "Cryptographic Glyph", additional_info = "Quest Item\nUnique (8)\n[q]\"The rune carved into the stone seems to shimmer and change its shape as you lay eyes upon it.\""}
MultiLanguageItemData['en'][213164] = {name = "Gnomish Gravity Launcher", additional_info = "Consumable\n[q2]Use: Deploy a Gnomish Gravity Launcher, granting anyone who steps on it the ability to soar through the air.\n\n Jump to activate. Land on enemies to inflict damage!\nSell Price:"}
MultiLanguageItemData['en'][213171] = {name = "Pristine Horn", additional_info = "Quest Item\nRequires level 70 to 73 ( 73)\n[q]\"The rings on this horn tell the age of the shalehorn. It is smooth, durable, and will make a beautiful, high-quality instrument.\""}
