MultiLanguageItemData['en'][213595] = {name = "[q4]Feathered Windsurfer String", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Check the current windspeed and elevation before mounting. Avoid trees and other tall objects. Damaged kites are ineligible for return or refund.\" - Windsurfer's Instruction Manual\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213596] = {name = "[q4]Reins of the Daystorm Windsteed", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"It is said that when lightning strikes the sun, a gleaming beast in red armor would emerge from the heavens. The Daystorm Windsteed has never heard of these legends and has been here the entire time.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213597] = {name = "[q4]Reins of the Forest Windsteed", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"The fur of this Windsteed is not only colored to match its woodland home, but also usually contains bits of bark and leaves.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213598] = {name = "[q4]Reins of the Dashing Windsteed", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Windsteeds are incredibly gentle and easy to train... if you can catch one.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213600] = {name = "[q4]Reins of the Marble Quilen", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Created by a mogu sorcerer who breathed life into their favorite pet rock.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213601] = {name = "[q4]Reins of the Guardian Quilen", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"When Quan the Relentless fell in battle, his loyal hounds waited for his return. Millenia later, they remain patient.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213602] = {name = "[q4]Reins of the Gilded Riding Crane", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"It is said that an emperor once paid a large sum for a golden crane. Upon discovering that the crane was only colored like that of the precious metal, he hid with shame in his bedchambers for a week.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213603] = {name = "[q4]Reins of the Pale Riding Crane", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"I looked, and behold, a pale... crane?\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213604] = {name = "[q4]Reins of the Tropical Riding Crane", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"This Jade Forest native uses its coloration as camouflage.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213605] = {name = "[q4]Reins of the Rose Riding Crane", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"This brightly-colored bird is often confused with a flamingo or marabou.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213606] = {name = "[q4]Reins of the Silver Riding Crane", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"This tall bird is one of the most graceful and elegant cranes, slightly moreso than the Bronze Crane but less than the Golden Crane.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213607] = {name = "[q4]Reins of the Luxurious Riding Crane", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"A majestic bird, but a rather picky eater.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213608] = {name = "[q4]Reins of the Snowy Riding Goat", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"The Kun-Lai Summit mountain goats are known for climbing even the highest peaks in search of kafa beans and salt licks.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213609] = {name = "[q4]Reins of the Little Red Riding Goat", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"What this goat lacks in size, it makes up for in stubbornness.\"\nWorld Event:\nMists of Pandaria: Remix"}
MultiLanguageItemData['en'][213610] = {name = "[q3]Crystalline Powder", additional_info = "Crafting Reagent\n[q]\"A fine, magical powder made from the crystallized fragments of a crystalline herb or ore. Can be bought and sold on the Auction House.\"\nSell Price:"}
MultiLanguageItemData['en'][213611] = {name = "[q3]Writhing Sample", additional_info = "Crafting Reagent\n[q]\"A small, writhing sample of biomass found within an Altered herb or Weeping ore. Can be bought and sold on the Auction House.\"\nSell Price:"}
MultiLanguageItemData['en'][213612] = {name = "[q3]Viridescent Spores", additional_info = "Crafting Reagent\n\"A cluster of spores, teeming with life energy. Acquired by players with the Herbalism skill. Can be bought and sold on the Auction House.\"\nSell Price:"}
MultiLanguageItemData['en'][213613] = {name = "[q3]Leyline Residue", additional_info = "Crafting Reagent\n\"A substance containing light hints of remnant arcane energy. Acquired by players with the Herbalism skill. Can be bought and sold on the Auction House.\"\nSell Price:"}
MultiLanguageItemData['en'][213621] = {name = "[q4]Reins of the Jade Pterrordax", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"This favored mount of the Zandalari is a great singer, or so it thinks.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213622] = {name = "[q4]Reins of the Night Pterrorwing", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Scholars interpret this creature's awful screeching as \"fear me, I am the night!\"\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213623] = {name = "[q4]Reins of the Bloody Skyscreamer", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"This dinosaur still harbors the rage of its ancestors from the Zandalari Invasion.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213624] = {name = "[q4]Cobalt Juggernaut", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"What started as a rideable mining and logging machine devolved quickly into chaos when engineers asked themselves if they could make it any cooler.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213625] = {name = "[q4]Fel Iron Juggernaut", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"This war machine was stolen from a timeline in which Garrosh Hellscream joined the Burning Legion. Suffice it to say, there is not much left of that timeline.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213626] = {name = "[q4]Reins of the Purple Shado-Pan Riding Tiger", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"When waking a tiger, use a long stick. Better yet, tell your friend to wake the tiger instead.\" -Pandaren Proverb\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213627] = {name = "[q4]Reins of the Palehide Mushan Beast", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"The Palehide Mushan is the tastiest of Mushan beasts, but it hates being reminded of that fact.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][213628] = {name = "[q4]Reins of the Riverwalker Mushan", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"The Mushan is a voracious beast. Though it can be tamed, it will demand a second, third, and even fourth breakfast every day.\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
