MultiLanguageItemData['en'][215147] = {name = "[q3]Beautification Iris", additional_info = "Toy\n[q2]Use: Focus a colored beam of light through a gemstone toward a helpless critter. (10 Min Cooldown)\n[q]\"The world is cruel. It does not have to be ugly.\"\nSell Price:"}
MultiLanguageItemData['en'][215158] = {name = "Freydrin's Shillelagh", additional_info = "Quest Item\n[q2]Use: Unleash Freya's life magic upon the wilds. (6 Sec Cooldown)\nRequires level 70 to 73 ( 73)\n[q]\"An otherworldly life energy resonates through the wood.\""}
