MultiLanguageItemData['en'][215160] = {name = "[q4]The Big Dig Rig", additional_info = "Binds when picked up\n[q]\"The only crate sturdy enough to survive Doomshadow. Contains many rare artifacts and supplies.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][215164] = {name = "Broodmother's Egg", additional_info = "Quest Item\n[q]\"It feels heavier than the usual grub egg.\""}
MultiLanguageItemData['en'][215169] = {name = "[q2]Everburning Lantern", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 [Agility or Intellect]\n[q2]Equip: Your harmful ranged spells and abilities have a high chance to rouse the lantern's flame, granting a stack of Lamp Light up to 15 times.\n\n After 30 sec of collecting stacks, Lamp Light is consumed to attract an equal amount of Fireflies to charge the next target you attack exploding for ( 1 * 151 ) Fire damage per Firefly.\nSell Price:"}
MultiLanguageItemData['en'][215170] = {name = "[q2]Abyssal Trap", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 [Agility or Strength]\n[q2]Use: Place an abyssal trap at your feet. When an enemy comes within 3 yards, a giant water bubble is created for 10 sec. All enemies within the bubble take ( 1 * 195 ) Frost damage every second.\n\n The trap will exist for 1 min before being automatically disarmed. (1 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][215171] = {name = "[q2]Fungal Friend Flute", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 Intellect\n[q2]Equip: Spells and abilities have a chance to unearth a Colourful Fungal Friend to heal allies for 4513 , grant you 439 mana, or deal ( 1028 * 3) Nature damage over 3 sec to a nearby enemy. (1s cooldown)\n[q]\"Fungal Friends never truly die. Instead their spores seep back into the earth, birthing the Friend anew.\"\nSell Price:"}
MultiLanguageItemData['en'][215172] = {name = "[q2]Silken Chain Weaver", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 [Agility or Strength]\n[q2]Use: Unfurl a myriad of grasping webs in front of you entangling your enemies, reducing damage they deal to you by 30% up to 5255 total damage and reducing their Attack Speed by 15% for 15 sec.\n\n [Attack Speed reduction is less effective against enemies above level 80.] (1 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][215173] = {name = "[q3]Serum of Unconstrained Senses", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 48 Dodge\n[q2]+ 48 Parry\n[q2]Equip: Systematically consume a small dosage of the serum when entering combat heightening your senses to their limit.\n In this state parrying and dodging have a chance to cause you to reposte with a Counter dealing Y Physical damage to your assailant.\n[q]\"Side effects may include loss of balance, vomiting, extreme pain, short term memory loss, long term memory loss, loss of motor functions, hallucinations, and an insatiable appetite for small insects.\"\nSell Price:"}
MultiLanguageItemData['en'][215174] = {name = "[q2]Concoction: Kiss of Death", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 [Agility or Strength or Intellect]\n[q2]Use: Drink from the vial and let the toxins course through your veins increasing all secondary stats by 106 for 30 sec.\n\n Jump to administer yourself the antidote to end the effect.\n\n If the Antidote is not administered before the end of the effect you will be stunned for 5 sec. (2 Min, 30 Sec Cooldown)\n[q]\"WARNING: Failure to administer the antidote shortly after consumption may result in death.\"\nSell Price:"}
MultiLanguageItemData['en'][215175] = {name = "[q3]Belt of Vials", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+64 [Agility or Intellect]\nSell Price:"}
