MultiLanguageItemData['en'][216624] = {name = "[q2]Mark of Arrogance", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: Attackers suffer a Mark of Arrogance inflicting Shadow damage every 2 sec for 10 sec and stacking up to 5 times.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][216625] = {name = "[q2]Quick Strike", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: Your melee abilities have a 100% chance to trigger 4 to 7 additional autoattacks. (10 Sec Cooldown)\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][216626] = {name = "[q2]Slay", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: When you attack an enemy beneath 10% health you will attempt to Slay them, inflicting Shadow damage equal to 100% of your maximum health.\n\n You will only attempt to Slay an enemy once.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][216627] = {name = "[q2]Tinkmaster's Shield", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: Grants a shield absorbing damage equal to 15% of your total health.\n\n This shield will regenerate after not suffering any damage for 5 sec.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][216628] = {name = "[q2]Victory Fire", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: Slaying an enemy causes you to erupt, inflicting Fire damage to enemies and restoring health to allies within 12 yards.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][216629] = {name = "[q3]Blink", additional_info = "Cogwheel Gem\nBinds when picked up\nUnique\n[q2]Equip: Learn the following spell.\n\n Blink\nTeleports you forward 20 yds or until reaching an obstacle, and frees you from all stuns and bonds.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Cogwheel socket.\""}
MultiLanguageItemData['en'][216630] = {name = "[q3]Heroic Leap", additional_info = "Cogwheel Gem\nBinds when picked up\nUnique\n[q2]Equip: Learn the following spell.\n\n Heroic Leap\nLeap through the air toward a target location, slamming down with destructive force to deal (23.5% of Spell Power + 23.5% of Attack Power) Physical damage to all enemies within 8 yards.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Cogwheel socket.\""}
MultiLanguageItemData['en'][216631] = {name = "[q3]Roll", additional_info = "Cogwheel Gem\nBinds when picked up\nUnique\n[q2]Equip: Learn the following spell.\n\n Roll\nRoll a short distance.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Cogwheel socket.\""}
MultiLanguageItemData['en'][216632] = {name = "[q3]Sprint", additional_info = "Cogwheel Gem\nBinds when picked up\nUnique\n[q2]Equip: Learn the following spell.\n\n Sprint\nIncreases your movement speed by 70% for 8 sec.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Cogwheel socket.\""}
