MultiLanguageItemData['en'][216647] = {name = "[q2]Hailstorm", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: Every 3 sec build a charge of Hailstorm. Upon reaching 10 stacks, unleash hail on enemies within 50 yards. Each impact inflicts Frost damage and applies Numbing Cold.\n\n Numbing Cold\nReduces movement speed by 30% and reduces damage dealt by 10%. Attacking removes a stack of Numbing Cold.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][216648] = {name = "[q2]Cold Front", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: Your abilities have a chance to grant up to 5 allies a shield absorbing damage, split evenly, and inflict Numbing Cold to all enemies within 50 yards.\n\n Numbing Cold\nReduces movement speed by 30% and reduces damage dealt by 10%. Attacking removes a stack of Numbing Cold.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][216649] = {name = "[q2]Brittle", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: Your abilities apply Brittle to enemies, accruing 10% of damage you deal. When a Brittle enemy is slain, it explodes, inflicting Frost damage to enemies within 12 yards, divided evenly.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][216650] = {name = "[q2]Memory of Vengeance", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: Every 10 sec, gain 1% Primary Stat for every 5% health you've lost.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][216651] = {name = "[q2]Searing Light", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: 10% of your healing is collected on allies as Searing Light. After 3 sec, Searing Light is consumed to heal your ally and inflict Holy damage to all enemies within 12 yards.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
