MultiLanguageItemData['en'][216671] = {name = "[q4]Thundering Orb", additional_info = "Meta Gem\nBinds when picked up\nUnique\n[q2]Equip: Learn the following spell.\n\n Thundering Orb\nTransform into a Thundering Orb, Inflicting Nature damage to enemies within 30 yards over 4 sec. While you are a Thundering Orb, damage taken is reduced by 50%, movement speed is reduced by 70%, and you are immune to loss of control effects.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Meta socket.\""}
MultiLanguageItemData['en'][216672] = {name = "The Ambush", additional_info = "Consumable\n[q2]Use: Disguise yourself as a simple bush. You and your allies are invisible while disguised.\n\n Your basic combo is replaced by Bushwhack, which stuns your current target.\nSell Price:"}
MultiLanguageItemData['en'][216677] = {name = "Korgran's Lantern", additional_info = "Quest Item\nRequires level 70 to 73 ( 73)\n[q]\"The lantern's charged core illuminates the area with cool shades of blue. On its bottom side, a carving saying \"Made by Korgran and a dear friend.\"\""}
