MultiLanguageItemData['en'][217605] = {name = "Timeless Scroll of Intellect", additional_info = "[q2]Use: Infuses the target with brilliance, increasing their Intellect by 4% for 1 hour.\n\n If the target is in your party or raid, all party and raid members will be affected.\nRequires level 10 to 80 ( 80)"}
MultiLanguageItemData['en'][217606] = {name = "Timeless Scroll of Fortitude", additional_info = "[q2]Use: Infuses the target with vitality, increasing their Stamina by 4% for 1 hour.\n\n If the target is in your party or raid, all party and raid members will be affected.\nRequires level 10 to 80 ( 80)"}
MultiLanguageItemData['en'][217607] = {name = "Timeless Scroll of the Wild", additional_info = "[q2]Use: Infuse a friendly target with the power of the wild, increasing their Versatility by 2% for 1 hour.\n\n If target is in your party or raid, all party and raid members will be affected.\nRequires level 10 to 80 ( 80)"}
MultiLanguageItemData['en'][217608] = {name = "Timeless Scroll of Battle Shout", additional_info = "[q2]Use: Increases the attack power of all raid and party members within 100 yards by 4% for 1 hour.\nRequires level 10 to 80 ( 80)"}
MultiLanguageItemData['en'][217610] = {name = "Earthen Memory Gem", additional_info = "Quest Item\nUnique\n[q]\"This square-cut gem is heavy for its size and emits a faint glow. Engineered for earthen programming and memories, this gem-like cache is removable and can be uploaded to the earthen Archive.\""}
MultiLanguageItemData['en'][217612] = {name = "[q4]Zovaal's Shadebeast Collar", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Was I a good boy?\" the soul asked Zovaal. \"No. I'm told you were the worst.\"\nAchievement:\nBack from the Beyond\nCategory:\nExpansion Features"}
