MultiLanguageItemData['en'][217894] = {name = "[q3]Nerubian Pheromone Secreter", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q0]Fragrance Socket\n[q0]Fragrance Socket\n[q2]Equip: Your spells and abilities have a chance to secrete different pheromones around you. Touching these pheromones will increase your primary stat by 2051 for 20 sec. (20s cooldown)\nSell Price:"}
MultiLanguageItemData['en'][217895] = {name = "[q2]Volatile Pheromone", additional_info = "[q]\"A strange chemical swirls within this bottle. It probably doesn't have any long-lasting side effects... right?\""}
MultiLanguageItemData['en'][217896] = {name = "Cinderbrew Mead", additional_info = "[q2]Use: A fairly weak alcoholic beverage.\n[q]\"Filled to the brim with bubbling, steaming mead.\"\nSell Price:"}
MultiLanguageItemData['en'][217897] = {name = "[q2]Volatile Pheromone", additional_info = "[q]\"This container shakes from the odd substance within it.\""}
MultiLanguageItemData['en'][217898] = {name = "Prayer of Purged Hatred", additional_info = "Binds when picked up\nUnique\n[q2]The next attack that reduces you below 35% health triggers Purged Hatred .\n\nPurged Hatred :\nFully restores your health, vigor, and class resources.\nRequires level 10 to 80 ( 80)"}
MultiLanguageItemData['en'][217899] = {name = "Prayer of Purged Pride", additional_info = "Binds when picked up\nUnique\n[q2]While out of combat, gain Purged Pride .\n\nPurged Pride :\nVanish from sight, entering stealth. Your next attack is guaranteed to be a critical strike.\nRequires level 10 to 80 ( 80)"}
MultiLanguageItemData['en'][217900] = {name = "Prayer of Purged Anger", additional_info = "Binds when picked up\nUnique\n[q2]The next time you are hit, release Purged Anger .\n\nPurged Anger :\nInflicts 2625000 Physical damage to enemies within 8 yards and stuns them for 3 sec.\nRequires level 10 to 80 ( 80)"}
MultiLanguageItemData['en'][217901] = {name = "Timeless Drums", additional_info = "[q2]Use: Increases Haste by 15% for all party and raid members. Lasts 40 sec.\n\n Allies receiving this effect will become Exhausted and be unable to benefit from Bloodlust, Heroism, or similar effects again for 10 min. (2 Min Cooldown)\nRequires level 10 to 80 ( 80)"}
MultiLanguageItemData['en'][217902] = {name = "Timerunner's Vial", additional_info = "[q2]Use: Increases your mana regeneration by 1000% for 6 sec.\n\n Reduces movement speed by 50%. (6 Sec Cooldown)\nRequires level 10 to 80 ( 80)"}
MultiLanguageItemData['en'][217903] = {name = "[q2]Vindication", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: 10% of your damage is collected as Vindication. Every 3 sec, Vindication is consumed to heal up to 3 allies within 50 yards for the amount consumed.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][217904] = {name = "Timerunner's Draught of Power", additional_info = "[q2]Use: Restores 525000 mana and increases Primary Stat by 3% for 30 min. (5 Min Cooldown)\nRequires level 10 to 80 ( 80)\n[q]\"Additional stock can be purchased from Nostwin at any Infinite Bazaar.\""}
MultiLanguageItemData['en'][217905] = {name = "Timerunner's Draught of Health", additional_info = "[q2]Use: Restores 1050000 health and increases Stamina by 3% for 30 min. (5 Min Cooldown)\nRequires level 10 to 80 ( 80)\n[q]\"Additional stock can be purchased from Nostwin at any Infinite Bazaar.\""}
MultiLanguageItemData['en'][217906] = {name = "Drake Treat", additional_info = "Unique (3)\n[q2]Use: Fully restores Skyriding Charges and grants a burst of flying speed. Only usable while dragonriding. (15 Sec Cooldown)\nRequires level 10 to 80 ( 80)"}
MultiLanguageItemData['en'][217907] = {name = "[q2]Warmth", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: Healing taken is increased by 10%. 75% of overhealing taken is collected as Warmth. Every 5 sec, Warmth is consumed to heal an injured ally within 50 yards for the amount consumed.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][217925] = {name = "Bottle of Bees", additional_info = "Binds when picked up\nUnique (3)\n[q2]Use: Annoy every enemy within 40 yards of the destination, engaging them in combat and applying Welts for 30 sec. Only usable outdoors.\n\n Welts :\nCauses an enemy to take 5% increased damage for 30 sec. Damaging the enemy has a chance to apply more Welts. (1 Min Cooldown)\nRequires level 10 to 80 ( 80)\n[q]\"Buzzing with anger.\""}
MultiLanguageItemData['en'][217926] = {name = "Bottle of Dead Bees", additional_info = "[q2]Use: Deals 26250 Physical damage to enemies within 3 yards. (1 Min Cooldown)\nRequires level 10 to 80 ( 80)\n[q]\"Oops.\""}
MultiLanguageItemData['en'][217927] = {name = "[q2]Savior", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: Healing an ally beneath 35% health will grant them a shield absorbing 50% of the amount healed.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][217928] = {name = "Timeless Scroll of Resurrection", additional_info = "[q2]Use: Brings a dead ally back to life with 35% health and mana. Cannot be cast when in combat. (30 Sec Cooldown)\nRequires level 10 to 80 ( 80)"}
MultiLanguageItemData['en'][217929] = {name = "Timeless Scroll of Cleansing", additional_info = "[q2]Use: Dispels all harmful curse, magic, poison, and disease effects from the target ally. (30 Sec Cooldown)\nRequires level 10 to 80 ( 80)\n[q]\"Time heals all wounds, diseases, curses, hangovers...\""}
MultiLanguageItemData['en'][217930] = {name = "Nostwin's Voucher", additional_info = "[q2]Use: Returns you to a nearby Infinite Bazaar. (15 Min Cooldown)\nRequires level 10 to 80 ( 80)\n[q]\"Thanks for shopping, come back soon!\""}
MultiLanguageItemData['en'][217956] = {name = "Timeless Scroll of Summoning", additional_info = "[q2]Use: Begins a ritual that creates a summoning portal for 3 min. The summoning portal can be used by allies to summon a targeted party or raid member. (30 Sec Cooldown)\nRequires level 10 to 80 ( 80)"}
MultiLanguageItemData['en'][217957] = {name = "[q2]Deliverance", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: 4% of healing is collected as Deliverance. If an ally is below 50% health after receiving healing from you, Deliverance will be consumed to heal up to 3 allies within 50 yards for the amount consumed, divided evenly.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][217958] = {name = "[q0]Used Socks", additional_info = "[q]\"Unfortunately, it seems there was more than just treasure in these chests.\"\nSell Price:"}
MultiLanguageItemData['en'][217959] = {name = "[q0]Incomplete Painting", additional_info = "[q]\"A painting that vaguely depicts a life filled with riches, though much of the details are missing.\"\nSell Price:"}
MultiLanguageItemData['en'][217960] = {name = "Forgotten Key", additional_info = "Binds when picked up\nUnique\n[q]\"Who would keep a key for a chest in a chest?\""}
MultiLanguageItemData['en'][217961] = {name = "[q2]Righteous Frenzy", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: Healing an ally will send them into a Righteous Frenzy, consuming 2% health every second and granting 7% increased Haste for 5 sec.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][217962] = {name = "[q0]Dud Bomb", additional_info = "[q]\"Luckily, this appears to be inactive.\"\nSell Price:"}
MultiLanguageItemData['en'][217964] = {name = "[q2]Holy Martyr", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: 5% of damage suffered is collected as Holy Martyrdom. Every 3 sec, Holy Martyrdom is consumed to heal 4 injured allies within 50 yards for the amount consumed. This effect cannot heal the Martyr.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][217965] = {name = "[q2]Repair Kit", additional_info = "[q]\"The sound of tools rustling around in here is enough to make you want to fix something.\""}
MultiLanguageItemData['en'][217969] = {name = "[q0]Bomb Debris", additional_info = "[q]\"Unluckily, this one was still active.\"\nSell Price:"}
MultiLanguageItemData['en'][217983] = {name = "[q3]Disengage", additional_info = "Cogwheel Gem\nBinds when picked up\nUnique\n[q2]Equip: Learn the following spell.\n\n Disengage\nLeap backwards, clearing movement impairing effects, and increasing your movement speed by 25% for 4 sec.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Cogwheel socket.\""}
MultiLanguageItemData['en'][217985] = {name = "[q3]Remembered Golden Gryphon", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\nRequires any Alliance race\nUse: Teaches you how to summon this mount. The capabilities of this mount depend on your Riding skill and location.\nSummons and dismisses a rideable Remembered Golden Gryphon mount. The capabilities of this mount depend on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price: \n[q]\"They love lions in Stormwind, and the gryphon is half lion. This is why these creatures are an air travel staple throughout the Alliance.\"\nVendor:\nRemembrancer Amuul\nZone:\nDalaran\nCost:\n25"}
MultiLanguageItemData['en'][217986] = {name = "[q2]\"Delicious\" Egg Parts", additional_info = "[q]\"Kobold chefs around the Undermine agree! No meal is complete without these eggs.\""}
MultiLanguageItemData['en'][217987] = {name = "[q3]Remembered Wind Rider", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount. The capabilities of this mount depend on your Riding skill and location.\nSummons and dismisses a rideable Green Wind Rider mount. The capabilities of this mount depend on your Riding skill and location.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price: \n[q]\"Hundreds of battles across a dozen campaigns have been fought and won on the backs of these honored creatures.\"\nVendor:\nRemembrancer Amuul\nZone:\nDalaran\nCost:\n25"}
