MultiLanguageItemData['en'][218106] = {name = "Stillstone Frog Trap", additional_info = "Binds when picked up\n[q2]Use: Throw a Frog Trap on the ground that will do 20 physical damage when an enemy walks on it, and stuns them for 6 sec.\n\n Usable at Stillstone Pond and nearby areas. (10 Sec Cooldown)"}
MultiLanguageItemData['en'][218107] = {name = "Sparkbug Jar", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: Shaking the jar causes the sparkbugs inside to glow faintly providing a dim light.\n\n With this light you can locate hidden items in Stillstone Pond and the nearby keyflame areas. (15 Sec Cooldown)\n[q]\"The small luminescent bugs inside provide a fanciful colorful light.\""}
MultiLanguageItemData['en'][218108] = {name = "[q3]Dark Pact", additional_info = "Cogwheel Gem\nBinds when picked up\nUnique\n[q2]Equip: Learn the following spell.\n\n Dark Pact\nSacrifices 20% of your current health to shield you for 200% of the sacrificed health for 20 sec. Usable while suffering from control impairing effects.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Cogwheel socket.\""}
MultiLanguageItemData['en'][218109] = {name = "[q3]Death's Advance", additional_info = "Cogwheel Gem\nBinds when picked up\nUnique\n[q2]Equip: Learn the following spell.\n\n Death's Advance\nFor 10 sec, your movement speed is increased by 35%, you cannot be slowed below 100% of normal speed, and you are immune to forced movement effects and knockbacks.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Cogwheel socket.\""}
MultiLanguageItemData['en'][218110] = {name = "[q3]Soulshape", additional_info = "Cogwheel Gem\nBinds when picked up\nUnique\n[q2]Equip: Learn the following spell.\n\n Soulshape\nTurn into a Vulpin for 12 sec, teleporting 15 yds forward and increasing your movement speed by 50%. You may reactivate Soulshape every few sec to teleport again.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Cogwheel socket.\""}
MultiLanguageItemData['en'][218111] = {name = "[q4]Reins of the Amber Pterrordax", additional_info = "Remix: Pandaria\nBinds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"The Pterrordax could and would eat you in seconds. Are you sure sitting on its back is a good idea?\"\nWorld Event:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['en'][218112] = {name = "[q3]Colorful Beach Chair", additional_info = "Binds when picked up\nUnique\nToy\n[q2]Use: Set up a colorful beach chair. (5 Min Cooldown)\n[q]\"After taking a dip to beat the summer heat, rest assured on the stylish comfort of this perfect blend of warm sunsets and relaxing rainbow hues.\""}
