MultiLanguageItemData['en'][218121] = {name = "[q3]Candle Light", additional_info = "Binds when picked up\n[q2]Use: A weak flame shines from you, unable to push back the darkness but revealing secrets hidden by darkness for 5 min.\n\n While this light persists you are unable to enter stealth.\n[q]\"You, in fact, did take candle.\"\nSell Price:"}
