MultiLanguageItemData['en'][219006] = {name = "[q2]Roaring Anglerseeker Lure", additional_info = "Use: Coat your hook in Anglerseeker bait, guaranteeing the catch from any Fishing Pool in The Ringing Deeps or Hallowfall.\n\n This bait lasts 30 min and stacks up to 50 times.\nSell Price:"}
MultiLanguageItemData['en'][219007] = {name = "[q2]Elusive Creature Lure", additional_info = "Binds when picked up\n[q2]Use: Place the bait, luring an elusive creature after a small amount of time. Who knows what might show up?\n\n The cooldown of Elusive Creature Bait is lowered by skinning creatures in Khaz Algar.\n\n Only usable outdoors in Khaz Algar.\nRequires Khaz Algar Skinning (1)\n[q]\"An enticing bait to draw elusive creatures out of hiding.\"\nSell Price:"}
MultiLanguageItemData['en'][219008] = {name = "[q4]Supreme Beast Lure", additional_info = "Binds when picked up\n[q2]Use: Place the bait, luring a supreme elusive creature out of hiding.\n\n Only usable in the Rumbling Wastes, located in the Ringing Deeps.\nRequires Khaz Algar Skinning (1)\n[q]\"An exquisite lure designed and crafted to precise specifications for which to draw out a powerful beast.\"\nSell Price:"}
MultiLanguageItemData['en'][219009] = {name = "[q3]Crystalline Creature Lure", additional_info = "Binds when picked up\n[q2]Use: Place the bait, luring an elusive creature after a small amount of time. Who knows what might show up?\n\n The cooldown of Elusive Creature Bait is lowered by skinning creatures in Khaz Algar.\n\n Only usable outdoors in Khaz Algar.\n[q]\"An enticing bait to draw elusive creatures out of hiding. Infused with crystalline power.\"\nSell Price:"}
MultiLanguageItemData['en'][219010] = {name = "[q3]Writhing Creature Lure", additional_info = "Binds when picked up\n[q2]Use: Place the bait, luring an elusive creature after a small amount of time. Who knows what might show up?\n\n The cooldown of Elusive Creature Bait is lowered by skinning creatures in Khaz Algar.\n\n Only usable outdoors in Khaz Algar.\n[q]\"An enticing bait to draw elusive creatures out of hiding. Infused with essence that weeps with malevolent energy.\"\nSell Price:"}
MultiLanguageItemData['en'][219011] = {name = "[q3]Sporefused Creature Lure", additional_info = "Binds when picked up\n[q2]Use: Place the bait, luring an elusive creature after a small amount of time. Who knows what might show up?\n\n The cooldown of Elusive Creature Bait is lowered by skinning creatures in Khaz Algar.\n\n Only usable outdoors in Khaz Algar.\n[q]\"An enticing bait to draw elusive creatures out of hiding. Infused with magical spores.\"\nSell Price:"}
MultiLanguageItemData['en'][219013] = {name = "[q4]Superb Beast Fang", additional_info = "Crafting Reagent\n[q]\"A mighty fang obtained from a particularly powerful elusive creature on Khaz Algar by skinners. Can be bought and sold on the Auction House.\"\nSell Price:"}
MultiLanguageItemData['en'][219014] = {name = "[q2]Vengeful Fire Spirit", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 493 Critical Strike\n[q2]Equip: Your ranged attacks have a chance to send a vengeful flame towards your target, dealing ( 1 * 19916 ) Fire damage when it reaches them.\n\n The spirit grows as it travels towards the target, dealing up to 100% additional Fire damage.\nSell Price:"}
