MultiLanguageItemData['en'][219294] = {name = "[q3]Charged Stormrook Plume", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Agility\n[q2]Use: Hold out the feather for [1.0][1] sec to strike with the power of the storm, crashing down on the target location and inflicting ( 1 * 124864 ) Nature damage split between nearby enemies. (1 Min, 30 Sec Cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:"}
MultiLanguageItemData['en'][219295] = {name = "[q3]Sigil of Algari Concordance", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 [Agility or Strength or Intellect]\n[q2]Equip: Your abilities have a chance to call an earthen ally to your aid, supporting you in combat. (15s cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:"}
MultiLanguageItemData['en'][219296] = {name = "[q3]Entropic Skardyn Core", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 604 Critical Strike\n[q2]Equip: Your spells have a chance to destabilize the void energy, releasing a corrupted fragment. Retrieving a fragment briefly infuses you with its power, increasing your Intellect by 1421 for 15 sec.\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:"}
MultiLanguageItemData['en'][219297] = {name = "[q3]Cinderbrew Stein", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]Equip: Occasionally share a drink with allies who assist you in combat, granting them 700 of their primary stat for 15 sec and absorbing 19079 damage. You take a sip as well, granting 377 Primary Stat and absorbing 97936 damage.\n\n When you fall below 50% health, you take an emergency sip. This may only occur once every 1 min.\n\nValid only for tank specializations.\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\n[q]\"Watered down for consumption by lesser mortals.\"\nSell Price:"}
MultiLanguageItemData['en'][219298] = {name = "[q3]Ravenous Honey Buzzer", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 [Agility or Strength]\n[q2]Use: Call in a ravenous ally and ride off into the sunset (or $443387rad1 yds, whichever is closest), inflicting ( 1 * 149371 ) Fire damage split between all enemies you ride through. (1 Min, 30 Sec Cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:"}
MultiLanguageItemData['en'][219299] = {name = "[q3]Synergistic Brewterializer", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Intellect\n[q2]Equip: Your spells have a chance to charge the device and request a Backfill Barrel near your target's location. Damaging the barrel causes it to explode, inflicting ( 1 * 84121 ) Fire damage split between nearby enemies.\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:"}
MultiLanguageItemData['en'][219300] = {name = "[q3]Skarmorak Shard", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Strength\n[q2]Use: Grasp the shard tightly to enrich yourself with crystalline energy, increasing your Mastery by 2756 for 15 sec. (1 Min, 30 Sec Cooldown)\n[q2]Equip: The shard draws in remnant energy from defeated enemies, increasing your Mastery by 58 for 15 sec, up to 5 times.\nSell Price:"}
MultiLanguageItemData['en'][219301] = {name = "[q3]Overclocked Gear-a-Rang Launcher", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]Use: Launch the superheated gear-a-rang, inflicting ( 1 * 41390 ) Flamestrike damage to enemies, losing heat as it cuts through them. (2 Min Cooldown)\n[q2]Equip: Your melee attacks have a chance to crank the launcher's gears, decreasing its cooldown by 5 sec and heating up your weapon which causes your next attack to inflict ( 1 * 23306 ) additional Fire damage.\nSell Price:"}
MultiLanguageItemData['en'][219302] = {name = "[q3]Scrapsinger's Symphony", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Intellect\n[q2]Equip: Your healing abilities have a chance to call the nearby metal to form a shield around an ally, absorbing 45216 damage.\n\n The shield reacts explosively to fire, inflicting 4162 Fire damage to nearby enemies when struck.\nSell Price:"}
MultiLanguageItemData['en'][219303] = {name = "[q3]High Speaker's Accretion", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 604 Mastery\n[q2]Use: Charge the crystal to summon a rift that draws power from nearby enemies, inflicting ( 1 * 45046 * 6) Shadow damage over 6 sec.\n\n When the rift collapses, its drawn energy returns to you to increase your Intellect by 135 for 20 sec, further increased for each enemy struck. (2 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][219304] = {name = "[q3]Conductor's Wax Whistle", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Agility\n[q2]Equip: Your attacks have a chance to direct a Kobold Cart towards your target, sending a careening troop that collides with enemies, inflicting ( 1 * 61010 ) Physical damage split between enemies impacted.\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\n[q]\"A hero's symbolic trophy, for the kobolds need not be summoned. The kobolds yearn for the catacombs.\"\nSell Price:"}
MultiLanguageItemData['en'][219305] = {name = "[q3]Carved Blazikon Wax", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Intellect\n[q2]Equip: Your spells have a chance to imbue the wax, causing it to form into a blazing candle for 15 sec which increases your Versatility by 1292 , further increased by 339 while you remain within its light.\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:"}
MultiLanguageItemData['en'][219306] = {name = "[q3]Burin of the Candle King", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Intellect\n[q2]Use: Carve a wax copy of your target, which absorbs 50% of their damage taken. The absorption heats up the wax, causing it to melt after absorbing 264398 damage. (1 Min, 30 Sec Cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:"}
MultiLanguageItemData['en'][219307] = {name = "[q3]Remnant of Darkness", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]Equip: Your abilities have a chance to call the Darkness to you, increasing your Primary Stat by 281 , up to ( 281 * 5).\n\n Upon reaching full power, the Darkness is unleashed, inflicting ( 1 * 35879 * 15 / 3) Shadow damage split between nearby enemies over 15 sec before fading back into the remnant.\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:"}
MultiLanguageItemData['en'][219308] = {name = "[q3]Signet of the Priory", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 [Agility or Strength or Intellect]\n[q2]Use: Raise your signet to the Light, increasing your highest secondary stat by 2756 for 20 sec. Your act inspires nearby signetbearers within your party, granting them 73 of the same stat for 20 sec. (2 Min Cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nComplete Priory of the Sacred Flame within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:"}
MultiLanguageItemData['en'][219309] = {name = "[q3]Tome of Light's Devotion", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]Equip: Advance to the 50 Verses of Inner Resilience, reading as you are attacked.\n Inner Resilience increases your armor by 1438 and grants your attacks a chance to invoke a ward which absorbs 67723 Magic damage. When finished, sift through the passages to another chapter.\n\nValid only for tank specializations. (500ms cooldown)\n[q2]Use: Sift through the passages in the tome with increased Radiance . (1 Min, 30 Sec Cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nComplete Priory of the Sacred Flame within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:"}
MultiLanguageItemData['en'][219310] = {name = "[q3]Bursting Lightshard", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Intellect\n[q2]Use: Summon a Bursting Lightspawn which sacrifices its health to unleash Bursts of Light, inflicting 57024 Holy damage split between nearby enemies every 2 sec while it lives. (2 Min Cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nComplete Priory of the Sacred Flame within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:"}
MultiLanguageItemData['en'][219311] = {name = "[q3]Void Pactstone", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Strength\n[q2]Equip: Your attacks have a chance to call to the pact, exploding for ( 1 * 35361 ) Shadow damage split between nearby enemies and increasing your Haste by 377 for 10 sec.\n\n Your death breaks the pact, causing a violent explosion.\nComplete the Dawnbreaker within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:"}
MultiLanguageItemData['en'][219312] = {name = "[q3]Empowering Crystal of Anub'ikkaj", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 [Agility or Intellect]\n[q2]Equip: Your spells and abilities have a chance to let loose a nascent empowerment from the crystal, increasing a random secondary stat by 1392 for 20 sec.\nComplete the Dawnbreaker within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:"}
MultiLanguageItemData['en'][219313] = {name = "[q3]Mereldar's Toll", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Intellect\n[q2]Use: Release a toll of holy light upon the target, inflicting ( 1 * 53941 ) Holy damage. The next 5 allies to attack the target will receive the Blessing of Mereldar, increasing their Versatility by 658 for 10 sec. (1 Min, 30 Sec Cooldown)\nComplete the Dawnbreaker within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:"}
MultiLanguageItemData['en'][219314] = {name = "[q3]Ara-Kara Sacbrood", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 604 Haste\n[q2]Equip: Your abilities have a chance to stir the sac, releasing an egg which grants you 213 Primary Stat. Each egg hatches after 1 min, and the new brood attacks your next target, inflicting ( 1 * 1598 * 8) Nature damage over 8 sec. (100ms cooldown)\nComplete Ara-kara, City of Echoes within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:"}
MultiLanguageItemData['en'][219315] = {name = "[q3]Refracting Aggression Module", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 [Agility or Strength]\n[q2]Equip: Your taunt abilities activate the module's refracting energy, protecting you from 50% of damage taken, up to 301603 . This may only occur once every 1 min.\n\nValid only for tank specializations. (1m cooldown)\nSell Price:"}
MultiLanguageItemData['en'][219316] = {name = "[q3]Ceaseless Swarmgland", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 [Agility or Strength]\n[q2]Equip: The gland releases pheromones that attract a Ceaseless Swarm of insects to surround you. Taking damage has a high chance to retaliate against attackers, inflicting ( 2726 * 6) Nature damage over 6 sec and reducing damage dealt to you by 3781 .\nComplete Ara-kara, City of Echoes within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:"}
MultiLanguageItemData['en'][219317] = {name = "[q3]Harvester's Edict", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 [Agility or Intellect]\n[q2]Equip: Your damaging spells and abilities have a chance to send an orb of volatile black blood drifting to your target, exploding for ( 1 * 55918 ) Shadow damage split between all nearby enemies on impact. Intercepting the orb allows you to siphon its power, instead increasing your Mastery by 1653 for 15 sec.\nComplete Ara-kara, City of Echoes within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:"}
MultiLanguageItemData['en'][219318] = {name = "[q3]Oppressive Orator's Larynx", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]Equip: Your attacks have a chance to stir the larynx, allowing its dark whispers to influence you. Each whisper flows through your mind for 30 sec, granting 198 Strength.\n[q2]Use: Wave the larynx in the air to release a tormenting chorus, inflicting ( 1 * 58370 * 3) Shadow damage over 3 sec split between nearby enemies. Your whispers leave to join the chorus, increasing its damage before falling silent. (2 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][219319] = {name = "[q3]Twin Fang Instruments", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Agility\n[q2]Use: Open the pouch and draw Nx's shadow blade to quickly strike at enemies in front of you, inflicting ( 1 * 23075 ) Shadow damage to all enemies hit.\n\n You may use the pouch up to two additional times within 20 sec before it seals itself to magically recharge its contents. (2 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][219320] = {name = "[q3]Viscous Coaglam", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Intellect\n[q2]Equip: Your excessive healing attracts nearby shadow energy to your party, storing up to 8407 healing and restoring the target's health when they receive damage.\n[q2]Use: Channel the coaglam's power, concentrating all current shadow energy to shield your target. (1 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][219321] = {name = "[q3]Cirral Concoctory", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+549 Intellect\n[q2]Equip: Your spells have a chance to inspire you to experiment on an ally, enhancing them in unforeseen ways for 20 sec.\nSell Price:"}
