MultiLanguageItemData['en'][219386] = {name = "[q4]Locus of Power", additional_info = "Meta Gem\nBinds when picked up\nUnique\n[q2]Equip: Learn the following spell.\n\n Locus of Power\nChannel arcane power for 4 sec. Every 0.40 sec, infuse yourself and 2 allies within 50 yards with Haste, Critical Strike, and Mastery for 30 sec.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Meta socket.\""}
MultiLanguageItemData['en'][219387] = {name = "[q3]Barrel of Fireworks", additional_info = "Toy\n[q2]Use: Deploy a dangerous barrel of fireworks for 5 min so you and your friends can violently illuminate the night sky!\n\n Other players can opt-in to seeing the fireworks by attacking the barrel.\n\n Cooldown reduced during drunken goblin revelries. (1 Hour Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][219388] = {name = "Sacred Flame Torch", additional_info = "Quest Item\n[q2]Use: Rally a nearby group of Arathi with their faith in the Sacred Flame!\n[q]\"The torch burns with Light, its snapping and flickering almost sounding like a song.\""}
MultiLanguageItemData['en'][219389] = {name = "[q2]Lightning Rod", additional_info = "Tinker Gem\nBinds when picked up\nUnique\n[q2]Equip: Your abilities have a chance to apply Lightning Rod to your target. Allies are granted Critical Strike for 10 sec and enemies suffer Nature damage every 2 sec for 8 sec. When Lightning Rod ends, it returns to you, granting Critical Strike for 10 sec.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Tinker socket.\""}
MultiLanguageItemData['en'][219390] = {name = "[q3]Set Keystone Map: Grim Batol", additional_info = "Duration: 12 hrs (real time)\n[q2]Use: Set the dungeon map of a Mythic Keystone to Grim Batol.\nSell Price:"}
