MultiLanguageItemData['en'][220120] = {name = "[q4]Soul Tether", additional_info = "Meta Gem\nBinds when picked up\nUnique\n[q2]Equip: Learn the following spell.\n\n Soul Tether\nTether your soul to an ally for 1 hour, redirecting 20% of their damage taken to you as Shadow damage. This effect can be used on up to 5 allies. Recasting on a tethered ally or moving further than 100 yards away removes the effect.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Meta socket.\""}
MultiLanguageItemData['en'][220122] = {name = "Offering of Pure Water", additional_info = "Binds when picked up\nUnique\n[q2]Use: Combine Offering of Pure Water and Jar of Mucus.\n[q]\"No impurity is discernable within the crystal-clear water. You are able to see through it as if there was nothing in the glass at all.\"\nSell Price:"}
