MultiLanguageItemData['en'][221871] = {name = "[q2]Prototype: Potion Bomb of Speed", additional_info = "Binds when picked up\nUnique: Prototype (1)\n[q2]Use: Throw a potion bomb which splashes up to 5 allies caught in the blast with a burst of 10-15% movement speed (based on crafting quality) for 20 sec.\n\n Enemies caught in the blast suffer 67738 fire damage, split between them.\nRequires Khaz Algar Engineering (1)\nSell Price:"}
MultiLanguageItemData['en'][221875] = {name = "[q2]Prototype: Potion Bomb of Recovery", additional_info = "Binds when picked up\nUnique: Prototype (1)\n[q2]Use: Throw a potion bomb which splashes up to 5 allies caught in the blast with a potion that increases healing received by 5-10% (based on crafting quality) for 12 sec.\n\n Enemies caught in the blast suffer 67738 fire damage, split between them.\nRequires Khaz Algar Engineering (1)\nSell Price:"}
MultiLanguageItemData['en'][221879] = {name = "[q2]Prototype: Potion Bomb of Power", additional_info = "Binds when picked up\nUnique: Prototype (1)\n[q2]Use: Throw a potion bomb which splashes up to 5 allies caught in the blast with a potion that increases their primary stat by ( 2196 / 5) for 30 sec.\n\n Enemies caught in the blast suffer 67738 fire damage, split between them.\nRequires Khaz Algar Engineering (1)\nSell Price:"}
MultiLanguageItemData['en'][221903] = {name = "[q2]Prototype: Tinker: Earthen Delivery Drill", additional_info = "Binds when picked up\nUnique: Prototype (1)\n[q2]Use: Summon an Earthen Delivery Drill to dig for an assortment of battleground buffs.\n\n The drill lasts for 28 sec and can only be summoned while in combat. Can only be used in unrated battlegrounds and in War Mode on Khaz Algar. (15 Min Cooldown)\nRequires Khaz Algar Engineering (1)\nSell Price:"}
MultiLanguageItemData['en'][221907] = {name = "[q2]Prototype: Tinker: Heartseeking Health Injector", additional_info = "Binds when picked up\nUnique: Prototype (1)\n[q2]Use: Inject a medicinal frostfire formula into your veins, instantly healing you for up to 1943637 from a jolt of frost. To prevent sudden hypothermia, you will then burn for 30% of the amount healed.\n\n Shares a cooldown with healing potions.\nRequires Khaz Algar Engineering (1)\nSell Price:"}
MultiLanguageItemData['en'][221944] = {name = "[q2]Prototype: Irresistible Red Button", additional_info = "Binds when picked up\nUnique: Prototype (1)\n[q2]Use: Deploy a device that can be activated by you or a party or raid member when a crisis is imminent. When activated, it will attempt to resurrect all nearby allies at the end of combat.\n\n Lasts for 1 hour or until activation. Must be deployed prior to combat.\nRequires Khaz Algar Engineering (1)\nSell Price:"}
MultiLanguageItemData['en'][221945] = {name = "[q2]Irresistible Red Button", additional_info = "Binds when picked up\n[q2]Use: Deploy a device that can be activated by you or a party or raid member when a crisis is imminent. When activated, it will attempt to resurrect all nearby allies at the end of combat.\n\n Lasts for 1 hour or until activation. Must be deployed prior to combat.\nRequires Khaz Algar Engineering (1)\nSell Price:"}
MultiLanguageItemData['en'][221948] = {name = "[q2]Prototype: Pausing Pylon", additional_info = "Binds when picked up\nUnique: Prototype (1)\n[q2]Use: Deploy a Pausing Pylon that will disrupt the natural metabolic processes of players standing nearby, halting the expiration of Khaz Algar Flasks, Phials, and Well Fed effects.\n\n The pylon is extremely fragile and will detonate in the presence of violence.\nRequires Khaz Algar Engineering (1)\nSell Price:"}
MultiLanguageItemData['en'][221949] = {name = "Pausing Pylon", additional_info = "[q2]Use: Deploy a Pausing Pylon that will disrupt the natural metabolic processes of players standing nearby, halting the expiration of Khaz Algar Flasks, Phials, and Well Fed effects.\n\n The pylon is extremely fragile and will detonate in the presence of violence.\nSell Price:"}
MultiLanguageItemData['en'][221952] = {name = "[q2]Prototype: Convincingly Realistic Jumper Cables", additional_info = "Binds when picked up\nUnique: Prototype (1)\n[q2]Use: Frighten a \"dead\" ally with the threat of an electric shock, restoring them to \"life\" with 35% health and 10% mana. Sometimes you fail to make a compelling case.\n\n Castable in combat. Item quality affects cast time. Cannot be used by players higher than level 80. (10 Min Cooldown)\nRequires Khaz Algar Engineering (1)\n[q]\"Sometimes they're just faking it.\"\nSell Price:"}
MultiLanguageItemData['en'][221956] = {name = "[q2]Prototype: Algari Repair Bot 11O", additional_info = "Binds when picked up\nUnique: Prototype (1)\n[q2]Use: Deploy a small earthen golem to allow you and fellow adventurers to repair your equipment.\n\n Lasts for 10 min.\nRequires Khaz Algar Engineering (1)\nSell Price:"}
MultiLanguageItemData['en'][221957] = {name = "[q2]Algari Repair Bot 11O", additional_info = "Binds when picked up\n[q2]Use: Deploy a small earthen golem to allow you and fellow adventurers to repair your equipment.\n\n Lasts for 10 min.\nRequires Khaz Algar Engineering (1)\nSell Price:"}
MultiLanguageItemData['en'][221958] = {name = "[q2]Prototype: Portable Profession Possibility Projector", additional_info = "Binds when picked up\nUnique: Prototype (1)\n[q2]Use: Summon a Possibility Projector configured to satisfy the needs of crafting tables. Only one workbench can be displayed at a time and can only be changed by the Engineer. (10 Min Cooldown)\nRequires Khaz Algar Engineering (1)\nSell Price:"}
MultiLanguageItemData['en'][221959] = {name = "[q3]Portable Profession Possibility Projector", additional_info = "[q2]Use: Summon a Possibility Projector configured to satisfy the needs of crafting tables. Only one workbench can be displayed at a time and can only be changed by the Engineer. (10 Min Cooldown)\nRequires Khaz Algar Engineering (1)\nSell Price:"}
MultiLanguageItemData['en'][221960] = {name = "[q2]Prototype: Barrel of Fireworks", additional_info = "Binds when picked up\nUnique: Prototype (1)\n[q2]Use: Deploy a dangerous barrel of fireworks for 5 min so you and your friends can violently illuminate the night sky!\n\n Other players can opt-in to seeing the fireworks by attacking the barrel.\n\n Cooldown reduced during drunken goblin revelries. (1 Hour Cooldown)\nRequires Khaz Algar Engineering (1)\nSell Price:"}
MultiLanguageItemData['en'][221961] = {name = "[q2]Prototype: Defective Escape Pod", additional_info = "Binds when picked up\nUnique: Prototype (1)\n[q2]Use: Urgently seek shelter inside a defective escape pod. You won't get very far, but at least you are safe. (10 Min Cooldown)\nRequires Khaz Algar Engineering (1)\nSell Price:"}
