MultiLanguageItemData['en'][221967] = {name = "[q4]Crowd Pummeler 2-30", additional_info = "Mount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon the Crowd Pummeler 2-30.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n[q]\"Guaranteed to knock the teeth out from your enemies with a single punch!\"\nProfession:\nKhaz Algar Engineering"}
MultiLanguageItemData['en'][221968] = {name = "[q3]Legibly Scribbled Notes", additional_info = "[q7]Binds to Warband\n[q2]Use: Arrange 15 Legibly Scribbled Notes into something comprehensible.\nRequires Khaz Algar Engineering (1)\n[q]\"Capable of being read by more than just medics; incapable of being understood by all but engineers.\""}
MultiLanguageItemData['en'][221969] = {name = "[q4]P.0.W. x2", additional_info = "Binds when picked up\n{Ranged} {Gun}\n{3,365 - 6,251 Damage} {Speed 3.00}\n(1,603 damage per second)\n+2,129 Agility\n+9,748 Stamina\n[q2]+ 728 Random Stat 1\n[q2]+ 728 Random Stat 2\nDurability 120 / 120\n[q]\"Come on, shoot faster!\"\nSell Price:"}
MultiLanguageItemData['en'][221970] = {name = "Pure Crawler Extract", additional_info = "Quest Item\n[q]\"A luminescent green liquid greatly prized by the Machine Speakers for its ability to remove rust.\""}
MultiLanguageItemData['en'][221977] = {name = "[q4]Funeral Pyre", additional_info = "Meta Gem\nBinds when picked up\nUnique\n[q2]Equip: Learn the following spell.\n\n Funeral Pyre\nGrants the caster Primary Stat for 1 min.\n\n Every 1 sec gain a stack of Funeral Pyre, suffering Fire damage per stack.\n\n Funeral Pyre will be removed early if reactivated. (2 Min Cooldown)\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Meta socket.\""}
MultiLanguageItemData['en'][221982] = {name = "[q4]Bulwark of the Black Ox", additional_info = "Meta Gem\nBinds when picked up\nUnique\n[q2]Equip: Learn the following spell.\n\n Bulwark of the Black Ox\nChannel the Bulwark of the Black Ox. Charge an enemy removing all stuns and roots, gain a shield absorbing damage, and taunt enemies within 20 yards. Every 1 sec for 5 sec inflict Physical damage to enemies within 20 yards plus 20% of damage taken by the shield.\nRequires level 10 to 80 ( 80)\n[q]\"Fits in a Meta socket.\""}
