MultiLanguageItemData['en'][222861] = {name = "[q4]Hideshaper's Workbag", additional_info = "Binds when picked up\nUnique\n36 Slot Bag\nEquip: Increases your Resourcefulness rating by 90 when crafting Leatherworking reagents.\n\n [ Equip effect requires Khaz Algar Leatherworking 1 ][ Equip effect requires Khaz Algar Leatherworking 1 ]\n[q]\"This workbag contains numerous compartments and pouches to hold various odds, ends, and specialty items.\"\nSell Price:"}
MultiLanguageItemData['en'][222862] = {name = "[q4]Magically \"Infinite\" Messenger", additional_info = "Binds when picked up\nUnique\n36 Slot Bag\nEquip: The amount of Resourcefulness, Ingenuity, and Multicraft provided by Shatter Essence is increased by 20.\n\n [ Equip effect requires Khaz Algar Enchanting 1 ][ Equip effect requires Khaz Algar Enchanting 1 ]\n[q]\"Rumors of its infiniteness have been greatly exaggerated.\"\nSell Price:"}
MultiLanguageItemData['en'][222863] = {name = "[q4]Prodigy's Toolbox", additional_info = "Binds when picked up\nUnique\n36 Slot Bag\nEquip: Increases the yield of Piles of Rusted Scrap from most sources by 1.\n\n [ Equip effect requires Khaz Algar Engineering 1 ][ Equip effect requires Khaz Algar Engineering 1 ]\n[q]\"A container of effortless genius.\"\nSell Price:"}
MultiLanguageItemData['en'][222864] = {name = "[q4]Darkmoon Duffle", additional_info = "Binds when picked up\nUnique\n36 Slot Bag\nUse: Transcribing a Khaz Algar Darkmoon Card has a 5% chance to create another.\n\n [ Equip effect requires Khaz Algar Inscription 1 ][ Equip effect requires Khaz Algar Inscription 1 ]\n[q]\"A compartment of mysteries and intrigue.\"\nSell Price:"}
MultiLanguageItemData['en'][222865] = {name = "[q4]Gardener's Seed Satchel", additional_info = "Binds when picked up\nUnique\n36 Slot Bag\nEquip: The cooldown of Overload Empowered Herb is reduced by an additional 1% when gathering herbs in Khaz Algar.\n\n [ Equip effect requires Khaz Algar Herbalism 1 ][ Equip effect requires Khaz Algar Herbalism 1 ]\n[q]\"Lingering magic radiates from the satchel, granting you a closer connection with the natural magics of Khaz Algar.\"\nSell Price:"}
MultiLanguageItemData['en'][222866] = {name = "[q4]Excavator's Haversack", additional_info = "Binds when picked up\nUnique\n36 Slot Bag\nEquip: The cooldown of Overload Empowered Deposit is reduced by an additional 1% when mining.\n\n [ Equip effect requires Khaz Algar Mining 1 ][ Equip effect requires Khaz Algar Mining 1 ]\n[q]\"Dusty, but durable.\"\nSell Price:"}
MultiLanguageItemData['en'][222867] = {name = "[q4]Jeweler's Purse", additional_info = "Binds when picked up\nUnique\n36 Slot Bag\nEquip: Increases the maximum yield of Crushed Gemstones from Algari Crushing by 1.\n\n [ Equip effect requires Khaz Algar Jewelcrafting 1 ][ Equip effect requires Khaz Algar Jewelcrafting 1 ]\n[q]\"Malleable threads make just enough space for rough edges.\"\nSell Price:"}
