MultiLanguageItemData['en'][223119] = {name = "[q3]Formula: Enchant Weapon - Authority of Air", additional_info = "[q2]Use: Teaches you how to perform the Authority of Air enchantment.\n[q2]Arathor Alterations - Fortified Flames\n\n Permanently enchants a weapon with the Authority of Air, which sometimes beckons a protective wind to your aid when taking damage that absorbs the next 204141 damage dealt to you. Cannot be applied to items lower than level 350.\nRequires Khaz Algar Enchanting (25)\nSell Price:"}
MultiLanguageItemData['en'][223120] = {name = "[q3]Formula: Enchant Weapon - Authority of Radiant Power", additional_info = "[q2]Use: Teaches you how to perform the Authority of Radiant Power enchantment.\n[q2]Arathor Alterations - Fortified Flames\n\n Permanently enchants a weapon with the Authority of Radiant Power. Dealing damage has a chance to call upon that authority, smiting your target for ( 1 * 170450) Radiant damage and temporarily increasing your Primary stat by 1560. Cannot be applied to items lower than level 350.\nRequires Khaz Algar Enchanting (25)\nSell Price:"}
