MultiLanguageItemData['en'][223138] = {name = "[q3]Formula: Enchant Cloak - Chant of Winged Grace", additional_info = "[q2]Use: Teaches you how to perform the Chant of Winged Grace enchantment.\n[q2]Nerubian Novelties - Tertiary Trivialities\n\n Permanently enchants a cloak with ancient magic that chants with power, granting 380 Avoidance and reducing fall damage by 0%. Cannot be applied to items lower than level 350.\nRequires Khaz Algar Enchanting (25)\nSell Price:"}
MultiLanguageItemData['en'][223139] = {name = "[q3]Formula: Enchant Cloak - Chant of Leeching Fangs", additional_info = "[q2]Use: Teaches you how to perform the Chant of Leeching Fangs enchantment.\n[q2]Nerubian Novelties - Tertiary Trivialities\n\n Permanently enchants a cloak with ancient magic that chants with power, granting 715 Leech and heal for 174266 every 5 sec while out of combat. Cannot be applied to items lower than level 350.\nRequires Khaz Algar Enchanting (25)\nSell Price:"}
MultiLanguageItemData['en'][223140] = {name = "[q3]Formula: Enchant Cloak - Chant of Burrowing Rapidity", additional_info = "[q2]Use: Teaches you how to perform the Chant of Burrowing Rapidity enchantment.\n[q2]Nerubian Novelties - Tertiary Trivialities\n\n Permanently enchants a cloak with ancient magic that chants with power, granting 175 Speed and causing the cooldown of your Hearthstone to recover 0% faster while in Khaz Algar. Cannot be applied to items lower than level 350.\nRequires Khaz Algar Enchanting (25)\nSell Price:"}
MultiLanguageItemData['en'][223141] = {name = "[q3]Formula: Enchant Ring - Cursed Critical Strike", additional_info = "[q2]Use: Teaches you how to perform the Cursed Critical Strike enchantment.\n[q2]Nerubian Novelties - Cursed Chants\n\n Permanently infuses a ring with a cursed chant, sapping -53 of your Haste while granting 180 Critical Strike. Cannot be applied to items lower than level 350.\nRequires Khaz Algar Enchanting (25)\nSell Price:"}
MultiLanguageItemData['en'][223142] = {name = "[q3]Formula: Enchant Ring - Cursed Mastery", additional_info = "[q2]Use: Teaches you how to perform the Cursed Mastery enchantment.\n[q2]Nerubian Novelties - Cursed Chants\n\n Permanently infuses a ring with a cursed chant, sapping -53 of your Critical Strike while granting 180 Mastery. Cannot be applied to items lower than level 350.\nRequires Khaz Algar Enchanting (25)\nSell Price:"}
MultiLanguageItemData['en'][223143] = {name = "[q3]Formula: Enchant Ring - Cursed Versatility", additional_info = "[q2]Use: Teaches you how to perform the Cursed Versatility enchantment.\n[q2]Nerubian Novelties - Cursed Chants\n\n Permanently infuses a ring with a cursed chant, sapping -53 of your Mastery while granting 180 Versatility. Cannot be applied to items lower than level 350.\nRequires Khaz Algar Enchanting (25)\nSell Price:"}
MultiLanguageItemData['en'][223144] = {name = "[q4]Formula: Enchant Weapon - Authority of the Depths", additional_info = "[q2]Use: Teaches you how to perform the Authority of the Depths enchantment.\n[q2]Nerubian Novelties\n\n Permanently enchants a weapon with the Authority of the Depths. Damaging foes may invoke it, applying Suffocating Darkness which periodically inflicts ( 1 * 24502) Shadow damage. The darkness may deepen up to 3 times. Cannot be applied to items lower than level 350.\nRequires Khaz Algar Enchanting (25)\nSell Price:"}
MultiLanguageItemData['en'][223145] = {name = "[q3]Marrlok", additional_info = "[q7]Binds to Warband\n[q2]Use: Teaches you how to summon this companion.\n[q2]Right Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)"}
MultiLanguageItemData['en'][223146] = {name = "[q3]Satchel of Stormborn Seeds", additional_info = "Binds when picked up\nUnique\nToy\n[q2]Use: Plant one of the seeds. (1 Min Cooldown)\n[q]\"A storm's power can be wielded for creation as well as destruction.\"\nSell Price:"}
MultiLanguageItemData['en'][223153] = {name = "[q4]Reins of the Soaring Meaderbee", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"This humble bee dreams of open skies. Whether or not an adventurer is along for the ride is of no consequence to it.\"\nVendor:\nCendvin\nZone:\nThe Isle of Dorn\nCost:\n900"}
MultiLanguageItemData['en'][223155] = {name = "[q3]Bop", additional_info = "Binds when picked up\n[q2]Use: Teaches you how to summon this companion.\n[q2]Right Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)"}
MultiLanguageItemData['en'][223157] = {name = "Blacksmith's Breastplate", additional_info = "Quest Item\n[q]\"Faerin recognizes this as belonging to Ryton Blackholme. It is one of his masterpieces. The bloody gouges can leave no doubt as to the blacksmith's fate.\""}
MultiLanguageItemData['en'][223158] = {name = "[q4]Raging Cinderbee", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Temper as hot as its flames, this breed of cinderbee can only be tamed by those who share its insatiable penchant for violence.\"\nAchievement:\nRuffious's Bid\nCategory:\nWorld"}
