MultiLanguageItemData['en'][223264] = {name = "[q4]Aquamarine Swarmite", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 23 with The Severed Threads.\nRequires Renown Rank 22 with The Severed Threads.\n\n\n[q]\"While it's not exactly common, the representatives of the Severed Threads assure you that swarmites are more than capable of carrying your weight if you choose to ride it.\"\nVendor:\nLady Vinazian\nZone:\nAzj-Kahet\nCost:\n3940\n\nVendor:\nY'tekhi\nZone:\nAzj-Kahet\nCost:\n3940"}
MultiLanguageItemData['en'][223265] = {name = "[q4]Nesting Swarmite", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Burrowers by nature they often lurk in small animal warrens when laying eggs or lying in wait to surprise larger prey.\"\nZone:\nVision of Stormwind (Revisited)\nZone:\nVision of Orgrimmar (Revisited)"}
MultiLanguageItemData['en'][223266] = {name = "[q4]Reins of the Shadowed Swarmite", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Swarmites are a common sight both in the wilds of Azj-Kahet and among the nerubians who have long domesticated them, but that doesn't make them any less dangerous to incautious adventurers.\"\nAchievement:\nGlory of the Nerub-ar Raider\nCategory:\nDungeons & Raids"}
MultiLanguageItemData['en'][223267] = {name = "[q4]Swarmite Skyhunter", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Typically found in the smallest nooks and crannies of rock ceilings, the swarmite skyhunter is more at home in the air than at rest.\"\nAchievement:\nKhaz Algar Glyph Hunter\nCategory:\nWar Within"}
MultiLanguageItemData['en'][223269] = {name = "[q4]Machine Defense Unit 1-11", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"One of many such mechsuits designed to guard the Machine. After years of faithful service it is no longer suited for combat. It does make for an impressive conveyance, though.\"\nTreasure:\nAwakened Cache\nZone:\nThe Ringing Deeps"}
MultiLanguageItemData['en'][223270] = {name = "[q4]Alunira", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"For so long, the very embodiment of the clouds laid trapped atop a mountain of lightning. And at last, I can feel the wind at my back once again.\"\nDrop:\nZone:\nIsle of Dorn"}
MultiLanguageItemData['en'][223274] = {name = "[q4]Ferocious Jawcrawler", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 22 with The Severed Threads.\nRequires Renown Rank 17 with The Severed Threads.\n\n\n[q]\"This particularly large jawcrawler is the perfect size to make a mount... just keep your hands and feet clear of its mouth.\"\nVendor:\nLady Vinazian\nZone:\nAzj-Kahet\nCost:\n2815\n\nVendor:\nY'tekhi\nZone:\nAzj-Kahet\nCost:\n2815"}
MultiLanguageItemData['en'][223276] = {name = "[q4]Widow's Undercrawler", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Conspirator reputation with the Weaver.\n\n\n[q]\"Surface-dwelling children often profess desires for a pony or wolf of their own upon reaching certain milestones of age. A young Widow Arak'nai had similar ambitions, though her tastes would likely be considered eclectic by some standards.\"\nVendors:\nYamas the Provider, Bobbin\nZone:\nAzj-Kahet\nCost:\n2020"}
MultiLanguageItemData['en'][223278] = {name = "[q4]Heritage Undercrawler", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Conspirator reputation with the General.\n\n\n[q]\"Arachnid husbandry is a time-honored tradition amongst the Heritage Forces. Though most specimens are used for transport labor or raised to serve as shock troops, the finest examples of their brood are occasionally trained as parade mounts.\"\nVendors:\nYamas the Provider, Anub'okki, Aspirake Kiipka\nZone:\nAzj-Kahet\nCost:\n2020"}
MultiLanguageItemData['en'][223279] = {name = "[q4]Royal Court Undercrawler", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Conspirator reputation with the Vizier.\n\n\n[q]\"Patents of lineage are used to demarcate the history and value of thoroughbred undercrawlers in Kaheti high society. This practice can prove somewhat difficult when said undercrawlers are prone to the sudden consumption of their record-keepers.\"\nVendors:\nYamas the Provider, Tulumun\nZone:\nAzj-Kahet\nCost:\n2020"}
