MultiLanguageItemData['en'][223955] = {name = "Recipe: Fine Egg Powder", additional_info = "Binds when picked up\n[q2]Use: Teaches you how to craft Fine Egg Powder.\n[q2]Recipe for 5 servings. Actual number of servings will vary based on cooking skill.\nRequires Khaz Algar Cooking (35)\nSell Price:\nFine Egg Powder\nCrafting Reagent\n\"Ground by someone with the Cooking skill. Can be bought and sold on the Auction House.\"\nSell Price:"}
MultiLanguageItemData['en'][223956] = {name = "Recipe: Everything-on-a-Stick", additional_info = "Binds when picked up\n[q2]Use: Teaches you how to craft Everything-on-a-Stick.\n[q2]Recipe for 2 servings. Actual number of servings will vary based on cooking skill.\nRequires Khaz Algar Cooking (35)\nSell Price:\n[q3]Everything-on-a-Stick\nBinds when picked up\n[q2]Use: Restores ( 375000 / 5 * 20) health over 20 sec. Must remain seated while eating.\n\n Well Fed\n If you spend at least 10 seconds eating you will become Well Fed and a gain the stats equivalent to a random Khaz Algar Meal.\n[q]\"Could be anything!\"\nSell Price:\nRequires Coagulated Yolk"}
MultiLanguageItemData['en'][223957] = {name = "Recipe: Protein Slurp", additional_info = "Binds when picked up\n[q2]Use: Teaches you how to craft Protein Slurp.\n[q2]Recipe for 1 servings. Actual number of servings will vary based on cooking skill.\nRequires Khaz Algar Cooking (35)\nSell Price:\nProtein Slurp\n[q2]Use: Restores ( 375000 / 5 * 20) mana over 20 sec. Must remain seated while drinking.\n\n Well Fed \nIf you spend at least 10 seconds eating you will become Well Fed gaining [ 470 * (0.7)] of your lowest secondary stat and increase your size by 1% for 15 min.\n[q]\"It bubbles.\"\nSell Price:\nRequires Fine Egg Powder (5)"}
MultiLanguageItemData['en'][223958] = {name = "Recipe: Spongey Scramble", additional_info = "Binds when picked up\n[q2]Use: Teaches you how to craft Spongey Scramble.\n[q2]Recipe for 1 servings. Actual number of servings will vary based on cooking skill.\nRequires Khaz Algar Cooking (35)\nSell Price:"}
