MultiLanguageItemData['en'][224023] = {name = "[q3]Herbal Embalming Techniques", additional_info = "Binds when picked up\nUnique\nUse: Study to increase your Khaz Algar Herbalism Knowledge by 10.\nRequires Khaz Algar Herbalism (1)\n[q]\"A small book describing how to use rare herbs from Khaz Algar and Northrend to perfectly preserve a corpse to retain its flavor. Could be useful for herbalists.\"\nSell Price:"}
MultiLanguageItemData['en'][224024] = {name = "[q3]Theories of Bodily Transmutation, Chapter 8", additional_info = "Binds when picked up\nUnique\nUse: Study to increase your Khaz Algar Alchemy Knowledge by 10.\nRequires Khaz Algar Alchemy (1)\n[q]\"Abstract theory about the alchemical side effects of transforming one's body permanently. Could be useful to alchemists.\"\nSell Price:"}
MultiLanguageItemData['en'][224025] = {name = "[q4]Crackling Shard", additional_info = "[q7]Binds to Warband\nUnique (10)\n[q2]Use: Combine 10 Crackling Shards to create a Storm Vessel that may free Alunira from her prison.\n[q]\"Even when idle, the wrath of a storm hums and snaps beneath its surface.\""}
