MultiLanguageItemData['en'][224041] = {name = "[q2]Holy Brigade", additional_info = "Binds when picked up\n[q2]Use: Throw a dollop of holy oil that creates an explosion dealing 29775 Holy Fire damage to all enemies within 6 yards, knocking them back and reducing movement speed by 30% for 8 sec.\n\n Knock back is more effective against enemy players."}
