MultiLanguageItemData['en'][224043] = {name = "[q2]Famished Residue", additional_info = "Binds when picked up\n[q2]Use: Fog beast residue imbues you, increasing Versatility by 10% for 30 sec."}
MultiLanguageItemData['en'][224044] = {name = "[q2]Devouring Residue", additional_info = "Binds when picked up\n[q2]Use: Fog beast residue imbues you, reducing damage taken by 15% for 30 sec."}
MultiLanguageItemData['en'][224045] = {name = "[q2]Kelp Grasp", additional_info = "Binds when picked up\n[q2]Use: Roots all enemies within 6 yards in place for 15 sec. Damage may interrupt the effect. Targets that are rooted take 10% increased damage from you."}
MultiLanguageItemData['en'][224046] = {name = "[q2]Sand Tornado", additional_info = "Binds when picked up\n[q2]Use: Douse enemies within 10 yards around you in sand dealing 278825 Nature damage and slowing by 40% and reducing their chance to critically strike by 15% for 6 sec."}
MultiLanguageItemData['en'][224047] = {name = "[q2]Water Blast", additional_info = "Binds when picked up\n[q2]Use: Knocks back the current enemy target, dealing 174266 Frost damage. Knockback is more effective against players."}
MultiLanguageItemData['en'][224048] = {name = "[q2]Electric Shock", additional_info = "Binds when picked up\n[q2]Use: Deal 46925 Nature damage, knocking enemies back and slowing them by 30% for 8 sec."}
MultiLanguageItemData['en'][224049] = {name = "[q2]Web Pull", additional_info = "Binds when picked up\n[q2]Use: Pulls an enemy within 40 yards towards the caster, temporarily stunning them."}
MultiLanguageItemData['en'][224050] = {name = "[q3]Web Sparkles: Pretty and Powerful", additional_info = "Binds when picked up\nUnique\nUse: Study to increase your Khaz Algar Enchanting Knowledge by 10.\nRequires Khaz Algar Enchanting (1)\n[q]\"A promotional package detailing a value proposition for enchanting one's personal webbing. Potentially useful for enchanters.\"\nSell Price:"}
MultiLanguageItemData['en'][224051] = {name = "Slightly Chewed Harvest Bounty", additional_info = "Quest Item\n[q]\"Still good for a stew or a pie...\""}
MultiLanguageItemData['en'][224052] = {name = "[q3]Clocks, Gears, Sprockets, and Legs", additional_info = "Binds when picked up\nUnique\nUse: Study to increase your Khaz Algar Engineering Knowledge by 10.\nRequires Khaz Algar Engineering (1)\n[q]\"A surprisingly insightful book introducing engineering concepts to nerubian children. Still might be useful to engineers.\"\nSell Price:"}
MultiLanguageItemData['en'][224053] = {name = "[q3]Eight Views on Defense against Hostile Runes", additional_info = "Binds when picked up\nUnique\nUse: Study to increase your Khaz Algar Inscription Knowledge by 10.\nRequires Khaz Algar Inscription (1)\n[q]\"Subtitled \"Lessons from the Fall of Ahn-Kahet,\" this tome examines potential ways to disrupt and deflect the runic power of the Lich King and his servants. Might be useful to scribes.\"\nSell Price:"}
MultiLanguageItemData['en'][224054] = {name = "[q3]Emergent Crystals of the Surface-Dwellers", additional_info = "Binds when picked up\nUnique\nUse: Study to increase your Khaz Algar Jewelcrafting Knowledge by 10.\nRequires Khaz Algar Jewelcrafting (1)\n[q]\"A freshly printed pamphlet theorizing about use of Resonance Crystals in nerubian gemwork. Useful for jewelcrafters.\"\nSell Price:"}
MultiLanguageItemData['en'][224055] = {name = "[q3]A Rocky Start", additional_info = "Binds when picked up\nUnique\nUse: Study to increase your Khaz Algar Mining Knowledge by 10.\nRequires Khaz Algar Mining (1)\n[q]\"A tome of nerubian mining techniques aimed at a journeyman learning the craft. Useful for miners.\"\nSell Price:"}
MultiLanguageItemData['en'][224056] = {name = "[q3]Uses for Leftover Husks (After You Take Them Apart)", additional_info = "Binds when picked up\nUnique\nUse: Study to increase your Khaz Algar Leatherworking Knowledge by 10.\nRequires Khaz Algar Leatherworking (1)\n[q]\"A grisly tome discussing productive mutilation of corpses to create useful leather works. It includes ways to use husks of both Alliance and Horde races. Useful for non-squeamish leatherworkers.\"\nSell Price:"}
