MultiLanguageItemData['en'][224256] = {name = "Bag of Angry Fungus", additional_info = "Binds when picked up\n[q2]Use: Release a bag full of angry fungus, sure to damage and distract all enemies nearby for 30 sec.\n\n Usable in Light's Blooming and the nearby keyflame areas. (1 Min Cooldown)\n[q]\"The bag is quite restless.\""}
MultiLanguageItemData['en'][224257] = {name = "Sturdy Locket", additional_info = "Quest Item\n[q]\"Where a portrait normally sits instead contains a flower pressed and preserved between glass.\""}
