MultiLanguageItemData['en'][224262] = {name = "Begrudgingly Poured Cinderbrew", additional_info = "Quest Item\n[q]\"As searingly hot as Innkeeper Brax's ire. Tastes better, though.\""}
MultiLanguageItemData['en'][224263] = {name = "[q3]Infused Fire-Honey Milk", additional_info = "Binds when picked up\nUnique\n[q2]Receiving fatal damage allows you to have one final drink, granting a shield that absorbs damage equal to 25% of your max health for 15 sec. While the shield holds, your Primary Stat is increased by 2553 .\n\n This effect can only occur once every 5 min while in the outdoors of Khaz Algar.\nSell Price:"}
MultiLanguageItemData['en'][224264] = {name = "[q3]Deepgrove Petal", additional_info = "Binds when picked up\nUse: Study to increase your Khaz Algar Herbalism Knowledge by 1.\nRequires Khaz Algar Herbalism (1)"}
MultiLanguageItemData['en'][224265] = {name = "[q4]Deepgrove Rose", additional_info = "Binds when picked up\nUse: Study to increase your Khaz Algar Herbalism Knowledge by 4.\n[q]\"You suspect it will be a while before you find a fully grown Deepgrove Rose again.\""}
MultiLanguageItemData['en'][224266] = {name = "Ivory Tinderbox", additional_info = "Binds when picked up\n[q]\"An ornate tinderbox made from an unknown ivory source. There is a noble figure carved into the lid.\""}
MultiLanguageItemData['en'][224267] = {name = "Dented Spearhead", additional_info = "Binds when picked up\n[q]\"This battleworn spearhead is attached to a chain. It appears to be a trophy of some sort.\""}
MultiLanguageItemData['en'][224268] = {name = "Filigreed Cleric", additional_info = "Binds when picked up\n[q]\"While the design of this Light's Gambit piece suggests it was intended to be decorative, it holds quite a bit of wear and tear.\""}
MultiLanguageItemData['en'][224270] = {name = "[q2]Tattered Technique: Certificate of Ownership", additional_info = "Binds when picked up\n[q2]Use: Teaches you how to craft a Tattered Certificate of Ownership.\nRequires Classic Inscription (1)\nSell Price:\n[q0]Tattered Certificate of Ownership\nClasses: Hunter\n[q]\"A deed to a pet well-loved.\"\nSell Price:\nRequires Light Parchment , Celestial Ink (2)"}
