MultiLanguageItemData['en'][224290] = {name = "[q3]Storm Defender's Axe", additional_info = "[q7]Binds to Warband until equipped\n{One-Hand} {Axe}\n{798 - 1,658 Damage} {Speed 2.60}\n(472.3 damage per second)\n+415 [Agility or Strength]\n+1,730 Stamina\nDurability 90 / 90\n[q2]Equip: Your damaging spells have a chance to cast Chain Lightning between 3 enemies, dealing 23641 Nature damage to each of them.\nSell Price:"}
MultiLanguageItemData['en'][224292] = {name = "Radiant Fuel Shard", additional_info = "Binds when picked up\nUnique (45)\nDuration: 15 min (real time)\n[q2]Use: Turn three Radiant Fuel Shards into Radiant Fuel Crystal."}
