MultiLanguageItemData['en'][224296] = {name = "Basket of Draconic Flowers", additional_info = "Binds when picked up\nUnique\n[q]\"Originally harvested for use in magical fireworks, these flowers have latent magical energies. Open to receive a flower from each of the five dragonflights!\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][224297] = {name = "[q4]Dreamsurge Cradle", additional_info = "Binds when picked up\n[q]\"This glimmering pod can be exchanged for a piece of Dreambound gear of your choosing from Archdruid Hamuul Runetotem near Dreamsurge Investigations.\"\nSell Price:"}
MultiLanguageItemData['en'][224298] = {name = "[q4]Dilated Eon Canister", additional_info = "Binds when picked up\n[q]\"Eternally filling, never full.\""}
MultiLanguageItemData['en'][224373] = {name = "[q0]Waterlord's Iridescent Gem", additional_info = "[q]\"An array of colors swirls and swims inside. Your touch excites whatever is living inside, churning quicker as if to break free.\"\nSell Price:"}
MultiLanguageItemData['en'][224374] = {name = "[q4]Reins of the Thundering Ruby Cloud Serpent", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\nSummons and dismisses a rideable Thundering Ruby Cloud Serpent. This is a flying mount. Requires Cloud Serpent Riding from the Order of the Cloud Serpent.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"From their infancy, Thundering Cloud Serpents are drawn to storms. They have been known to chase lightning through the blackened, roiling clouds, and to bathe in the pouring rain.\"\nDrop:\nAlani\nZone:\nVale of Eternal Blossoms"}
MultiLanguageItemData['en'][224395] = {name = "Secret Garlic", additional_info = "Quest Item\n[q]\"How do these grow here?\""}
MultiLanguageItemData['en'][224396] = {name = "Mangled Taro", additional_info = "Quest Item\n[q]\"Well, you tried.\""}
MultiLanguageItemData['en'][224397] = {name = "Pristine Taro", additional_info = "Quest Item\n[q]\"Starchy perfection.\""}
MultiLanguageItemData['en'][224398] = {name = "[q4]Reins of the Frayfeather Hippogryph", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"This majestic hippogryph hails from the Frayfeather Highlands of Feralas. Though it previously protected its hatchlings, now it chooses to serve a greater cause.\"\nVendor:\nBobadormu\nZone:\nTanaris\nCost:\n5000\n\nVendor:\nGrannadormu\nZone:\nTanaris\nCost:\n5000"}
MultiLanguageItemData['en'][224399] = {name = "[q4]Reins of the Amani Hunting Bear", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"The Amani trolls ride this fierce creature on ceremonial hunts in honor of the bear god Nalorakk.\"\nVendor:\nCupri\nZone:\nShattrath City\nCost:\n5000"}
MultiLanguageItemData['en'][224400] = {name = "See Where Running Candles", additional_info = "Quest Item\n[q]\"You can't flee if you can't see.\""}
MultiLanguageItemData['en'][224401] = {name = "Run Far Food", additional_info = "Quest Item\n[q]\"Supplies for the road.\""}
MultiLanguageItemData['en'][224402] = {name = "Krafting Tools", additional_info = "Quest Item\n[q]\"Needed both for clearing escape tunnels and rebuilding homes.\""}
MultiLanguageItemData['en'][224403] = {name = "Heirloom Wax", additional_info = "Quest Item\n[q]\"Passed down through the generations, this wax is a living, gooey history of the tribe.\""}
