MultiLanguageItemData['en'][224762] = {name = "Delver's Waterskin", additional_info = "[q2]Use: Restores ( 375000 / 5 * 20) mana over 20 sec. Must remain seated while drinking.\nSell Price:"}
MultiLanguageItemData['en'][224763] = {name = "[q3]Design: Cubic Blasphemia", additional_info = "[q2]Use: Teaches you how to craft Cubic Blasphemia.\n[q2]High quality Cubic Blasphemia cuts require specializing in the gemcutting techniques of the four most coveted gemstones found on Khaz Algar. Even a cheap knock-off takes a mastered technique.\nRequires Khaz Algar Jewelcrafting (50)\nSell Price:"}
MultiLanguageItemData['en'][224764] = {name = "Mosswool Thread", additional_info = "Crafting Reagent\n\"Spun from the wool of the Isle of Dorn's sheep, this thread is both durable and versatile. Sold by Tailoring vendors.\"\nSell Price:"}
MultiLanguageItemData['en'][224765] = {name = "[q3]Everburning Ignition", additional_info = "Binds when picked up\nUnique (10)\nUse: Ignite the forge.\n\n Gain Ingenuity, Multicraft, and Resourcefulness based on your Everburning Forge specialization for 10 min.\n[q]\"Siphoned from your expertise with the forge.\"\nSell Price:"}
MultiLanguageItemData['en'][224766] = {name = "[q3]Faithful Dog", additional_info = "Binds when picked up\n[q2]Use: Teaches you how to summon this companion.\n[q2]Right Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)"}
MultiLanguageItemData['en'][224767] = {name = "Giant Candle Parts", additional_info = "[q]\"The wax here is supposed to be useful to Dagran. Perhaps he'll write a good thesis doctorate on the effects of wax on the bags of adventurers.\""}
