MultiLanguageItemData['en'][224772] = {name = "Bounty from Gallywix", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires level 80 to 80 ( 80)\n[q]\"These orders describe a large bounty available to any of the Darkfuse that discover who is responsible for opening the wall at Opportunity Point.\""}
MultiLanguageItemData['en'][224773] = {name = "Knicknack's Red Candle", additional_info = "Quest Item\n[q]\"A candle of deep red wax. You don't want to know how the kobolds got that color.\""}
MultiLanguageItemData['en'][224774] = {name = "Knicknack's Potion Bottle", additional_info = "Quest Item\n[q]\"A slick, indeterminate liquid coats the inside of this glass bottle.\""}
MultiLanguageItemData['en'][224775] = {name = "Knicknack's Definitely Rubies", additional_info = "Quest Item\n[q]\"A pair of uncut red gems. They seem to be of moderate quality and whether or not they are rubies is unclear.\""}
MultiLanguageItemData['en'][224777] = {name = "Sureki Shadecaster", additional_info = "Quest Item\nUnique\n[q]\"Nerubians use these emitters to project orders and messages from their high-ranking leaders.\""}
MultiLanguageItemData['en'][224778] = {name = "Knicknack's Enbiggener", additional_info = "Quest Item\n[q]\"The Enbiggener appears to be an earthen jewel crafting tool, used for magnification purposes.\""}
MultiLanguageItemData['en'][224779] = {name = "Alhainr's Skull", additional_info = "Quest Item\n[q]\"Small leaves and vines sprout from the skull.\""}
MultiLanguageItemData['en'][224780] = {name = "[q3]Toughened Tempest Pelt", additional_info = "Binds when picked up\nUse: Study to increase your Khaz Algar Skinning Knowledge by 1.\n[q]\"A particularly rugged pelt that isn't pliable enough to use in crafting. You could study it to learn a thing or two about the local fauna, however.\""}
MultiLanguageItemData['en'][224781] = {name = "[q4]Abyssal Fur", additional_info = "Binds when picked up\nUse: Study to increase your Khaz Algar Skinning Knowledge by 2.\n[q]\"A small tuft of fur that carries a deep purple hue. It isn't of much traditional use, but such a fascinating and rare specimen won't be found very often.\""}
MultiLanguageItemData['en'][224782] = {name = "[q3]Razor Talon", additional_info = "Binds when picked up\nUse: Study to increase your Khaz Algar Skinning Knowledge by 1.\n[q]\"A small, but extremely sharp talon of a creature. While it isn't big enough to be of practical use, it is fascinating to study.\""}
MultiLanguageItemData['en'][224783] = {name = "[q3]Sovereign's Finery Chest", additional_info = "Binds when picked up\nUnique\nToy\n[q2]Use: Set down a chest of royal clothes for you and others to try on. (1 Hour Cooldown)\n[q]\"Only for those with the most exquisite taste.\"\nSell Price:"}
MultiLanguageItemData['en'][224784] = {name = "[q4]Pinnacle Cache", additional_info = "Binds when picked up\n[q]\"Weekly cache containing materials for upgrading gear, gold, Adventurer gear, and more.The first four weekly caches you earn each week contain Coffer Key Shards.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][224786] = {name = "[q2]Skeleton King Outfit", additional_info = "Binds when picked up\nUnique\n[q2]Use: Transform into the Skeleton King. (3 Sec Cooldown)"}
MultiLanguageItemData['en'][224791] = {name = "[q2]Golden Lord Outfit", additional_info = "Binds when picked up\nUnique\n[q2]Use: Transform into a Golden Lord. (3 Sec Cooldown)"}
MultiLanguageItemData['en'][224792] = {name = "[q2]Sanguine Aristocrat Outfit", additional_info = "Binds when picked up\nUnique\n[q2]Use: Transform into a Sanguine Aristocrat. (3 Sec Cooldown)"}
MultiLanguageItemData['en'][224797] = {name = "Zirdo's Ledger", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires level 80 to 80 ( 80)\n[q]\"The ledger contains deliveries of Black Blood across the Undermine that were approved by Noggenfogger, Trade-Prince of the Steamwheedle Cartel.\""}
MultiLanguageItemData['en'][224799] = {name = "Nizrek's potion", additional_info = "Quest Item\nUnique\n[q2]Use: Restores the vitality of an ally. (2 Sec Cooldown)\n[q]\"A vial of faintly glowing liquid.\""}
MultiLanguageItemData['en'][224807] = {name = "[q3]Algari Skinner's Notes", additional_info = "Binds when picked up\nUse: Study to increase your Khaz Algar Skinning Knowledge by 3."}
MultiLanguageItemData['en'][224808] = {name = "Opal Ore", additional_info = "Quest Item\nUnique (20)\n[q]\"Crucial pieces of a lost puzzle.\""}
MultiLanguageItemData['en'][224809] = {name = "[q3]Earthen Plumber's Pipe", additional_info = "Binds when picked up\n[q2]Use: Reroute water through the ancient pipe system to clear the blockage. (3 Sec Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][224810] = {name = "Woodworm Elixir", additional_info = "Quest Item\nUnique\n[q]\"Made from wood-boring worms. Famous in the City of Threads, despite being nigh undrinkable.\""}
MultiLanguageItemData['en'][224811] = {name = "[q3]Sugar Shrooms", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: The fungal essence transforms your shape and increases haste by 25% for 30 sec.\n\n Usable in Light's Blooming and the nearby keyflame areas. (30 Sec Cooldown)\nRequires Renown Rank 12 with the Hallowfall Arathi.\n[q]\"Kids absolutely love hunting for these sweet delights!\"\nSell Price:"}
MultiLanguageItemData['en'][224813] = {name = "[q3]Big Cat Whistle", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: Summon a large Battle Lynx to aid you in combat for 5 min.\n\n Usable in Light's Blooming and the nearby keyflame areas. (5 Min Cooldown)\nRequires Renown Rank 12 with the Hallowfall Arathi.\n[q]\"The biggest lynx are always just a whistle away.\"\nSell Price:"}
MultiLanguageItemData['en'][224814] = {name = "[q0]Adventurer's Warbound Boots", additional_info = "The War Within Season 1\nBinds when picked up\nUnlocked by progressing the Season 1 Delver's Journey.\n[q]\"Contains an Adventurer 4/8 piece of equipment corresponding to your class.\"\nSell Price:"}
MultiLanguageItemData['en'][224815] = {name = "[q3]Charm of the Flame", additional_info = "Binds when picked up\nUnique (20)\n[q2]Use: Imbue yourself with the sacred flame, causing your attacks and abilities to occasionally spawn an elemental of light which inflicts 3 Holy damage to targets.\n\n Usable in Light's Blooming and nearby keyflame areas.\nRequires Renown Rank 12 with the Hallowfall Arathi.\n[q]\"The dwindling supply of these is rapidly being exhausted by the Arathor.\"\nSell Price:"}
MultiLanguageItemData['en'][224816] = {name = "[q0]Nerubian Almanac", additional_info = "[q]\"Indistinguishable charts and diagrams fill the pages. The only discernable thing seems to be an illustration of seismic waves that outline a tunnel system below.\"\nSell Price:"}
MultiLanguageItemData['en'][224817] = {name = "[q3]Algari Herbalist's Notes", additional_info = "Binds when picked up\nUse: Study to increase your Khaz Algar Herbalism Knowledge by 3."}
MultiLanguageItemData['en'][224818] = {name = "[q3]Algari Miner's Notes", additional_info = "Binds when picked up\nUse: Study to increase your Khaz Algar Mining Knowledge by 3."}
MultiLanguageItemData['en'][224822] = {name = "[q4]Scour Through Scrap", additional_info = "[q]\"Rummage through scrap to find parts, forgotten prototypes, and more!\""}
MultiLanguageItemData['en'][224831] = {name = "[q4]Cube of Infinite Inventions (PTR Only)", additional_info = "Binds when picked up\nUnique\nUse: Reset the cooldown of Khaz Algar Engineering cooldowns.\n\n This item is purely for testing purposes.\nRequires Khaz Algar Engineering (1)\n[q]\"Counts as a samophlange, whatever that is.\""}
MultiLanguageItemData['en'][224835] = {name = "[q3]Deepgrove Roots", additional_info = "Binds when picked up\nUse: Study to increase your Khaz Algar Herbalism Knowledge by 1.\n[q]\"The roots continue to grow even after the rose is plucked. Not useful for any practical purposes, but rather intriguing to study.\""}
MultiLanguageItemData['en'][224837] = {name = "[q3]Cursed Pickaxe", additional_info = "[q7]Binds to Warband until equipped\n{One-Hand} {Axe}\n{1,180 - 2,452 Damage} {Speed 2.60}\n(698.5 damage per second)\n+614 [Agility or Strength]\n+3,002 Stamina\n[q2]+ 424 Critical Strike\n[q2]+ 170 Haste\nDurability 90 / 90\n[q2]While this item is in your bags, equipped, or being used for transmog you will occasionally be consumed by the curse.\n[q]\"Ancient runes decorate the metal head and trail onto the handle in the form of carved etchings. These patterns become more erratic as they reach the pommel, eventually becoming nothing more than frantic scratches.\"\nSell Price:"}
MultiLanguageItemData['en'][224838] = {name = "[q3]Null Sliver", additional_info = "Binds when picked up\nUse: Study to increase your Khaz Algar Mining Knowledge by 1.\n[q]\"The tiniest sliver of null stone which radiates a pulsing aura of emptiness. It isn't particularly useful for any crafts, but studying it could teach you more about Algari ore and minerals.\""}
