MultiLanguageItemData['en'][225241] = {name = "[q3]Refurbished Tinker: Alarm-O-Turret", additional_info = "Tinker Module\nUnique-Equipped: Alarm-O-Turret (1)\nRefurbished Alarm-O-Turret\n[q2]Equip: Insert into a Tinker Socket for the following effect:\n\n Alarm-O-Turret\nPlace a hidden Alarm-O-Turret on a nearby targeted location. If an enemy player enters its detection radius, it will alert you of their presence and attempt to defend the area for 30 sec or until destroyed.\n[q]\"Refurbished for use in Khaz Algar equipment. Success chance is equivalent to a mid-quality Algari tinker.\"\nSell Price:"}
MultiLanguageItemData['en'][225242] = {name = "[q3]Refurbished Tinker: Plane Displacer", additional_info = "Tinker Module\nUnique-Equipped: Plane Displacer (1)\nRefurbished Plane Displacer\n[q2]Equip: Insert into a Tinker Socket for the following effect:\n\n Plane Displacer\nGrants the user invisibility for 14-18 sec.\n[q]\"Refurbished for use in Khaz Algar equipment. Success chance is equivalent to a mid-quality Algari tinker.\"\nSell Price:"}
MultiLanguageItemData['en'][225243] = {name = "[q3]Refurbished Tinker: Supercollide-O-Tron", additional_info = "Tinker Module\nUnique-Equipped: Supercollide-O-Tron (1)\nRefurbished Supercollide-O-Tron\n[q2]Equip: Insert into a Tinker Socket for the following effect:\n\n Supercollide-O-Tron\nLock on to a distant enemy target, up to 12 to 60 yds away. After 1.5 sec, if your path remains unobstructed, you will charge toward them at the speed of sound. Both you and your target will be stunned for 1.5 sec upon collision.\nRequires Dragon Isles Engineering (1)\n[q]\"Refurbished for use in Khaz Algar equipment. Success chance is equivalent to a mid-quality Algari tinker.\"\nSell Price:"}
MultiLanguageItemData['en'][225244] = {name = "[q3]Refurbished Tinker: Shadowflame Rockets", additional_info = "Tinker Module\nUnique-Equipped: Shadowflame Rockets (1)\nRefurbished Shadowflame Rockets\n[q2]Equip: Insert into a Tinker Socket for the following effect:\n\n Shadowflame Rockets\nHop onto a plank of wood with a haphazard shadowflame rocket attachment. Absolutely nothing could go wrong, but if it did, deal 31949 Shadowflame damage split between you and enemies caught in the theoretical blast.\n[q]\"Refurbished for use in Khaz Algar equipment. Success chance is equivalent to a mid-quality Algari tinker.\"\nSell Price:"}
