MultiLanguageItemData['en'][225556] = {name = "[q3]Ancient Construct", additional_info = "Binds when picked up\nToy\n[q2]Use: Summon Icarus the Unbreakable at target location for 1 min. This acts as a target dummy that can be damaged and healed by opposing roles while it persists. How far up will you make the numbers go?\n\n Only usable outdoors. (1 Hour Cooldown)"}
MultiLanguageItemData['en'][225557] = {name = "Sizzling Cinderpollen", additional_info = "[q7]Binds to Warband\n[q]\"Causes particularly painful sneezing fits. The meadery might have a use for it.\"\nSell Price:"}
MultiLanguageItemData['en'][225558] = {name = "Murkfin Lure", additional_info = "Binds when picked up\nUnique\n[q2]Use: Squish together a Sunless Lure, Murkfin Lure, Hungering Shimmerfin, and a Ragefin Necrostaff. Should be fine.\n[q]\"You took this from a kobyss trying to fool you in the Velhan's Claim. With enough parts, you may be able to turn the tables.\"\nSell Price:"}
