MultiLanguageItemData['en'][226506] = {name = "[q4]Hand of Reshkigaal", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Reshkigaal bided her time as her kin each tried their hand at usurping the Banished One. She sought to attack when he was distracted, but the Jailer's spies had been tracking her. With their warning and aid, the Jailer prevailed.\"\nTrading Post"}
MultiLanguageItemData['en'][226507] = {name = "Venom Dahn's Webscrub", additional_info = "Binds when picked up\n[q2]Use: Scrub yourself down with skitterling venom to remove a single stack of Eradicator's Mark.\nRequires Crony reputation with the General.\n[q]\"A venom-base body scrub to remove grime & web build up from Eradicator's Marks. 88% natural flavors!\""}
MultiLanguageItemData['en'][226508] = {name = "Vizier's Influence", additional_info = "Binds when picked up\n[q2]Use: You've bribed the right nerubians.\n\n Next time the guards would kick you from the City of Threads, you'll be sent to the Royal Apothecary instead. This effect will last for 60 minutes.\nRequires Accomplice reputation with the Vizier.\n[q]\"A set of \"official\" paperwork. \"Encourages\" guards in the City of Threads to redirect you to the Royal Apothecary when captured.\""}
MultiLanguageItemData['en'][226509] = {name = "General's Insight", additional_info = "Binds when picked up\n[q2]Use: You can visualize the detection radius of guards in the City of Threads for 10 minutes.\n\n You've learned much from the General.\nRequires Accomplice reputation with the General.\n[q]\"A copy of Sureki patrols and methods. Allows you to see the detection radius for all guards in the City of Threads.\""}
MultiLanguageItemData['en'][226510] = {name = "Weaver's Facade", additional_info = "Binds when picked up\n[q2]Use: You assume the visage of a trueform nerubian. Guards in the City of Threads will have a reduced detection radius for 1 minute.\n\n The Weaver is a master of disguises.\nRequires Accomplice reputation with the Weaver.\n[q]\"A pheromonal concoction to fool guards in the City of Threads, significantly reducing their detection radius. A Weaver's specialty.\""}
MultiLanguageItemData['en'][226511] = {name = "Nerubimorph Poultice", additional_info = "Binds when picked up\n[q2]Use: Lob a concoction to transform a guard in the City of Threads into a less threatening form for 30 Seconds.\n\n A signature brew of the Vizier himself.\nRequires Crony reputation with the Vizier.\nRequires Crony reputation with the Weaver.\n[q]\"A throwable concoction that transforms victims into harmless weave-rats for a short duration. Only works on guards in the City of Threads.\""}
MultiLanguageItemData['en'][226512] = {name = "Treasure Map: Forgotten Memorial", additional_info = "Binds when picked up\nUnique (5)\n[q2]Use: Reveal the location of a Forgotten Memorial on your map.\nRequires Crony reputation with the General."}
MultiLanguageItemData['en'][226513] = {name = "Treasure Map: Kaheti Excavation", additional_info = "Binds when picked up\nUnique (5)\n[q2]Use: Reveal the location of a Kaheti Excavation on your map.\nRequires Crony reputation with the Vizier."}
MultiLanguageItemData['en'][226514] = {name = "Treasure Map: Weave-Rat Cache", additional_info = "Binds when picked up\nUnique (5)\n[q2]Use: Reveal the location of a Weave-Rat Cache on your map.\nRequires Crony reputation with the Weaver."}
MultiLanguageItemData['en'][226515] = {name = "Rumor Map: Bounties", additional_info = "Binds when picked up\nUnique (5)\n[q2]Use: Reveal the location of a Bounty Rumor on your map."}
MultiLanguageItemData['en'][226516] = {name = "Rumor Map: Disruption", additional_info = "Binds when picked up\nUnique (5)\n[q2]Use: Reveal the location of a Disruption Rumor on your map."}
MultiLanguageItemData['en'][226517] = {name = "Rumor Map: Espionage", additional_info = "Binds when picked up\nUnique (5)\n[q2]Use: Reveal the location of a Espionage Rumor on your map."}
MultiLanguageItemData['en'][226518] = {name = "Phero-Escape", additional_info = "Binds when picked up\n[q2]Use: Throw an implosion of various pheromones to stun guards in the City of Threads for 2 seconds, breaking you from combat.\nRequires Crony reputation with the Vizier.\n[q]\"Throw this implosion of pheromones to stun enemies and disengage from combat. Only works on guards in the City of Threads.\""}
MultiLanguageItemData['en'][226519] = {name = "[q3]General's Expertise", additional_info = "Binds when picked up\nToy\n[q2]Use: You can visualize the detection radius of guards in the City of Threads.\n\n You've learned much from the General.\nRequires Crony reputation with either the Weaver, the General, or the Vizier.\n[q]\"A transcribed copy of the combat manual all soldiers in Azj-Kahet study from. When active, allows you to see the detection radius for all guards in the City of Threads.\""}
MultiLanguageItemData['en'][226520] = {name = "Queen's Pheromone", additional_info = "Binds when picked up\n[q2]Use: The pheromones of the Queen.\n\n Guards in the City of Threads will no longer interfere with you.\nRequires Mastermind reputation with either the Weaver, the General, or the Vizier.\n[q]\"The pheromones of the Queen. Obtained discreetly. Guards in the City of Threads will no longer be able to detect you.\""}
MultiLanguageItemData['en'][226521] = {name = "[q2]Reinforced Wax Plating", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+389 [Agility or Strength]\n[q2]Equip: Apply a thick coating of reinforced wax to your armor, granting you 1922 damage reduction.\nSell Price:"}
MultiLanguageItemData['en'][226522] = {name = "Demolition Controller Fragment", additional_info = "Quest Item\n[q]\"There's some grains of sand caught in the wires.\""}
MultiLanguageItemData['en'][226524] = {name = "Partially-Charged Hologem", additional_info = "Races: Draenei , Lightforged Draenei\n[q2]Use: Activate the hologem. (30 Sec Cooldown)\n[q]\"Just enough power remaining to be used for a short time.\"\nSell Price:"}
MultiLanguageItemData['en'][226525] = {name = "Demolition Control Code", additional_info = "Quest Item"}
MultiLanguageItemData['en'][226539] = {name = "[q2]Scroll of Momentum", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+389 Agility\n[q2]Equip: Your harmful attacks and abilities have a high chance to build momentum, granting 2% bonus movement speed per stack.\n\n At 5 stacks you reach full momentum increasing your movement speed bonus to 20% for 10 sec. While at full momentum, your attacks hit the target at high velocity dealing an additional ( 1 * 2869 ) Nature damage scaling up with your current movement speed. (500ms cooldown)\nSell Price:"}
MultiLanguageItemData['en'][226643] = {name = "[q4]Plans: Beledar's Bulwark", additional_info = "[q2]Use: Teaches you how to craft Beledar's Bulwark.\nRequires Khaz Algar Blacksmithing (35)\nSell Price:"}
