MultiLanguageItemData['en'][229351] = {name = "Spiritual Incense", additional_info = "Secrets of Azeroth\nBinds when picked up\n[q2]Use: Conjures a spiritual link to Maru the Junior Sleuth. Maru can provide hints for some Secrets of Azeroth.\n[q]\"A bowl of aromatic ambergris blessed to honor Oacha'noa.\"\nSell Price:"}
