MultiLanguageItemData['en'][229354] = {name = "[q3]Algari Adventurer's Cache", additional_info = "Binds when picked up\n[q]\"Weekly cache containing leveling gear, gold, and more.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][229355] = {name = "[q4]Chromie's Premium Goodie Bag", additional_info = "Binds when picked up\n[q]\"Contains gold, valorstones, a chance for crests, and a Warbound Until Equipped item.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][229358] = {name = "Miniature Tuskarr Boat", additional_info = "Secrets of Azeroth\nQuest Item\nUnique\n[q]\"This must belong to Maru.\""}
MultiLanguageItemData['en'][229359] = {name = "[q3]Chromie's Goodie Bag", additional_info = "Binds when picked up\n[q]\"Contains a Warbound Until Equipped item appropriate for your level and class.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][229361] = {name = "[q6]Xal'atath, Blade of the Black Empire", additional_info = "Quest Item\nUnique\n[q]\"Xal'atath has a mind of its own. Ignore its maddening whispers. Do not trust the lies it spins. Take from it what you need, but always remember that the dark presence in the blade is not your ally.\""}
MultiLanguageItemData['en'][229363] = {name = "Zaranit Bud", additional_info = "Quest Item\n[q]\"A zaranit flower bud from a plant carefully grown within the intact eco-dome on K'aresh.\""}
MultiLanguageItemData['en'][229364] = {name = "[q4]Scourge Crest", additional_info = "Cosmetic\n[q7]Binds to Warband\nBack\n[q2]Use: Add this appearance to your Warband collection.\nSell Price:"}
MultiLanguageItemData['en'][229365] = {name = "[q4]Raw Singing Citrine", additional_info = "Binds when picked up\n[q2]Use: Imbue Cyrce's Circlet with the raw magic of this citrine, increasing its item level.\n[q]\"You hear an alluring song while this sits idly in your inventory. Bashfully, the song retreats into a hushed voice when held to your ear.\"\nSell Price:"}
