MultiLanguageItemData['en'][229392] = {name = "Crumpled Delivery Note", additional_info = "Quest Item\nRequires level 80 to 80 ( 80)\n[q]\"A letter written to the Underrider Gang detailing payments in the form of weapons.\""}
MultiLanguageItemData['en'][229393] = {name = "Lapbug Essence", additional_info = "Quest Item\n[q]\"You can see a cloudy substance moving in this jar. It occasionally shoots forward into the jar's edge and dissipates.\""}
MultiLanguageItemData['en'][229395] = {name = "Slateback Essence", additional_info = "Quest Item\n[q]\"The mist in this jar sits heavily on the bottom. Swirling the jar around shows it's acting more like liquid than a gas.\""}
MultiLanguageItemData['en'][229396] = {name = "Flyer Essence", additional_info = "Quest Item\n[q]\"The particles in this jar are constantly moving around. You can make out small twinkles, almost star-like in the depths of its murk.\""}
MultiLanguageItemData['en'][229401] = {name = "[q2]Artisan's Consortium Pamphlet", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\n[q]\"A special notice for eager competitors of all ranks!\""}
MultiLanguageItemData['en'][229405] = {name = "Entropic Core", additional_info = "Quest Item\n[q]\"Condensed energies siphoned from the soil of K'aresh.\""}
MultiLanguageItemData['en'][229407] = {name = "Citrus Acid", additional_info = "Quest Item\n[q]\"Whether this will improve the taste of grog is up for debate.\""}
MultiLanguageItemData['en'][229408] = {name = "Burnt Feather", additional_info = "Secrets of Azeroth\nQuest Item\nUnique\n[q]\"The feather looks battle-worn, burnt, torn in areas, and a strange green liquid is dripping off the end of it.\""}
MultiLanguageItemData['en'][229409] = {name = "Plucked Feather", additional_info = "Secrets of Azeroth\nQuest Item\nUnique\n[q]\"The feather appears to have been purposely plucked and altered to be missing exactly 48 barbs on the left and has a remaining 93 barbs on the right.\""}
MultiLanguageItemData['en'][229410] = {name = "Frozen Feather", additional_info = "Secrets of Azeroth\nQuest Item\nUnique\n[q]\"The feather is frozen and has a strange combination of scents: volcanic ash, saltwater, and engine oil.\""}
MultiLanguageItemData['en'][229411] = {name = "Normal Feather", additional_info = "Secrets of Azeroth\nQuest Item\nUnique\n[q]\"The feather appears unaltered as expected at the start of a journey.\""}
MultiLanguageItemData['en'][229412] = {name = "Devourer Anima", additional_info = "Quest Item\n[q]\"Plucked from the corpse of a devourer, this anima swirls languidly and glows with a bright blue light.\""}
MultiLanguageItemData['en'][229413] = {name = "\"Dogg-Saron\" Costume", additional_info = "[q2]Use: Dress up your Perky Pug.\n[q]\"A re-labeled knockoff of an old Hallow's End costume.\"\nSell Price:"}
MultiLanguageItemData['en'][229414] = {name = "Moira Thaurissan's Hammer", additional_info = "Binds when equipped\n{One-Hand} {Mace}\n{1 Damage} {Speed 2.60}\n(0.4 damage per second)\nSell Price:"}
MultiLanguageItemData['en'][229418] = {name = "[q4]Reins of the Trader's Gilded Brutosaur", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this three-person mount with vendors.\n[q2]Summons and dismisses your Trader's Gilded Brutosaur.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n[q]\"Morten and Killia never realized how much their new trading partnership across faction lines would pay off. That is until the day they were able to purchase this fine creature to aid them in their travels. And of course do it in gilded style.\"\nIn-Game Shop"}
MultiLanguageItemData['en'][229419] = {name = "Barrelbottom Deed", additional_info = "Quest Item\nRequires level 80 to 80 ( 80)\n[q]\"The deed to Barrelbottom Apartments. Moz won't be needing this anymore.\""}
MultiLanguageItemData['en'][229420] = {name = "Anima Orb", additional_info = "Quest Item\n[q2]Use: Throw a ball to your friendly animal.\n[q]\"A tactile ball of anima. It squeaks when you throw it. Animals seem to love it.\""}
MultiLanguageItemData['en'][229422] = {name = "[q7]Undermine Equipment Chest", additional_info = "The War Within Season 2\n[q7]Binds to Warband\n[q2]Use: Create a soulbound dungeon item appropriate for your loot specialization during The War Within Season 2."}
MultiLanguageItemData['en'][229423] = {name = "Echo Surveyor", additional_info = "Quest Item\n[q]\"A miniature version of cartel Om technology.\""}
MultiLanguageItemData['en'][229424] = {name = "Anima Vacuum", additional_info = "Quest Item\n[q2]Use: Suck up nearby critters, ne'er-do-wells, and cosmic entities (probably).\n\n May walk while casting. (3 Sec Cooldown)\n[q]\"Apparently there is a portal in the back that leads directly to K'aresh. You've been assured it's safe. Probably.\""}
