MultiLanguageItemData['en'][229924] = {name = "[q4]Darkfuse Chompactor", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 17 with the Gallagio Loyalty Rewards Club.\n\n\n[q]\"Considered the Top Dog among Stix's Junkyard Hyenas, it boasts a bite force strong enough to crush whatever - or whoever - Gallywix wants disposed of.\"\nVendor:\nAndo the Gat\nZone:\nLiberation of Undermine\nCost:"}
MultiLanguageItemData['en'][229935] = {name = "[q4]Crimson Armored Growler", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Exalted reputation with the Bilgewater Cartel in Undermine.\n\n\n[q]\"Some Goblins affectionately refer to trained hyenas as 'Growlers.' This one is fond of digging.\"\nVendor:\nRocco Razzboom\nZone:\nUndermine\nCost:\n8125"}
MultiLanguageItemData['en'][229936] = {name = "[q4]Violet Armored Growler", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 15 with the Cartels of Undermine.\n\n\n[q]\"Smaks knows a thing or two about caring for hyenas. Rule number one: keep your hands away from those teeth!\"\nVendor:\nSmaks Topskimmer\nZone:\nUndermine\nCost:\n8125"}
MultiLanguageItemData['en'][229937] = {name = "[q4]Blackwater Bonecrusher", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Best keep those bones to yourself if you don't want them crushed.\"\nDrop:\nBlackwater Trove\nZone:\nUndermine"}
MultiLanguageItemData['en'][229940] = {name = "[q4]Flarendo the Furious", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown Rank 20 with the Gallagio Loyalty Rewards Club.\n\n\n[q]\"Being the VIP of VIPs at the Gallagio has its perks, including the keys to this former King of Carnage. Cutting-edge goblin technology allows him to achieve over 100 yards per gallon!\"\nVendor:\nAndo the Gat\nZone:\nLiberation of Undermine\nCost:"}
MultiLanguageItemData['en'][229941] = {name = "[q4]Innovation Investigator", additional_info = "Binds when used\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"When the best path to a good idea is going really fast.\"\nVendor:\nSkedgit Cinderbangs\nZone:\nUndermine\nCost:\n25"}
