MultiLanguageItemData['en'][229968] = {name = "Boonful Banquet", additional_info = "Secrets of Azeroth\nQuest Item\nUnique\n[q]\"This handwritten note looks like a list of instructions, but none of it makes any sense. Maybe someone in Booty Bay can help decipher this.\"\n[q2]<Right Click to Read>"}
MultiLanguageItemData['en'][229969] = {name = "Flickering Essence", additional_info = "Quest Item\n[q]\"The mote of pure energy flickers at a set tempo with two beats. Ba-bump, ba-bump, ba-bump.\""}
MultiLanguageItemData['en'][229970] = {name = "Blood of K'aresh Deposit", additional_info = "Quest Item\nRequires level 80 to 80 ( 80)\n[q]\"These blue and transparent crystals can be found in small colonies. They are smooth with an oily film on them that seems to repel sand.\""}
MultiLanguageItemData['en'][229974] = {name = "[q4]Delver's Gob-Trotter", additional_info = "[q7]Binds to Warband\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses your Delver's Gob-Trotter.\n\n This mount can use Ride Along.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"This aircraft will help you delve straight into adventure, if it doesn't explode!\"\nWorld Quest:\nI Want My Hat Back\nZone:\nIsle of Dorn\nZone:\nDornogal"}
MultiLanguageItemData['en'][229987] = {name = "[q4]Prized Gladiator's Fel Bat", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Awakened from caves in the battlefield, and armored to the fray.\"\nAchievement:\nGladiator: The War Within Season 2\nCategory:\nPlayer vs. Player"}
MultiLanguageItemData['en'][229988] = {name = "[q4]Vicious Electro Eel", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"These aquatic beasts enjoy torturing the Alliance with their electric shocks.\"\nPvP:\nThe War Within: Season 2\nRated Arena and Rated Battleground Season Reward"}
MultiLanguageItemData['en'][229989] = {name = "[q4]Vicious Electro Eel", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"These aquatic beasts enjoy torturing the Horde with their electric shocks.\"\nPvP:\nThe War Within: Season 2\nRated Arena and Rated Battleground Season Reward"}
