MultiLanguageItemData['en'][229999] = {name = "[q2]Classic Cloudy Tabard", additional_info = "Cosmetic\n[q7]Binds to Warband\nTabard\n[q]\"A simple tabard for many occasions.\"\n[q2]Use: Add this appearance to your Warband collection."}
MultiLanguageItemData['en'][230000] = {name = "Ellie", additional_info = "Quest Item\nRequires level 80 to 80 ( 80)\n[q]\"A well-loved elekk plush with the name Ellie written on it. The seams have begun to wear and its button eyes are loose.\""}
MultiLanguageItemData['en'][230011] = {name = "[q3]Lil'Kaz's Hilt", additional_info = "[q7]Binds to Warband\n[q2]Use: Teaches you how to summon this companion.\n[q2]Right-click to summon and dismiss Lil'Doomy.\nRequires level 1 to 80 ( 80)"}
MultiLanguageItemData['en'][230017] = {name = "[q4]Master Blaster's Insignia", additional_info = "The War Within Season 2\nBinds when picked up\nUnique\n[q]\"Awarded for outstanding service to the denizens of the Undermine. Bring it to Teddo Bridgeblaster or Giggi Clobbersocket in the Incontinental Hotel to receive powerful equipment for your efforts.\""}
MultiLanguageItemData['en'][230019] = {name = "[q4]Vexie's Pit Whistle", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,108 [Agility or Strength]\n[q2]Use: Summon Pitbot Geardo to assist you for 5 sec, coating nearby enemies with rancid motor oil for additional threat. Geardo ensures you take the blame.\n\n Geardo departs explosively to deal 699165 Fire damage split between nearby enemies, increased by 15% if recently oiled. (500ms cooldown) (1 Min, 30 Sec Cooldown)\nDefeat Vexie in Liberation of Undermine on Mythic difficulty.\nSell Price:"}
MultiLanguageItemData['en'][230026] = {name = "[q4]Scrapfield 9001", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,108 [Agility or Strength]\n[q2]Equip: Falling below 60% health surrounds you with a protective vortex of junk, reducing damage taken by 50% for 15 sec or until 996802 damage is prevented. This effect may only occur every 30 sec.\n\n After 20 sec without activating while in combat, the Scrapfield overloads to energize you with 2651 Haste for 12 sec.\nValid only for tank specializations.\nDefeat Stix Bunkjunker in Liberation of Undermine on Mythic difficulty.\nSell Price:"}
MultiLanguageItemData['en'][230027] = {name = "[q4]House of Cards", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,108 [Agility or Strength or Intellect]\n[q2]Use: Deal yourself in, granting you [ 6605 * (0.9)] to [ 6605 * (1.1)] Mastery for 15 sec and stacking the deck. Stacking the deck increases the minimum Mastery on future hands by [ 6605 * (0.0333333)] until you leave combat, up to 3 times. (1 Min, 30 Sec Cooldown)\nDefeat One-Armed Bandit in Liberation of Undermine on Mythic difficulty.\nSell Price:"}
MultiLanguageItemData['en'][230029] = {name = "[q4]Chromebustible Bomb Suit", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 1,341 Haste\n[q2]Use: Rapidly deploy the bomb suit to reduce damage taken by 75% for 20 sec or until 6290790 damage has been prevented.\n\n Upon depletion, the bomb suit detonates to deal 529552 Fire damage split between nearby enemies. (1 Min, 30 Sec Cooldown)\nDefeat Gallywix in Liberation of Undermine on Mythic difficulty.\n[q]\"When the only options are initial success or total failure.\"\nSell Price:"}
MultiLanguageItemData['en'][230030] = {name = "Cartel Ve Communicator", additional_info = "Quest Item\n[q]\"This appears to be some form of worked Stygia. You can feel it pulsating slowly in your hand.\""}
MultiLanguageItemData['en'][230032] = {name = "[q4]Overflowing K'aresh Trust Trove", additional_info = "[q7]Binds to Warband\n[q]\"Contains a variety of rewards for those who have proven themselves true allies of the K'aresh Trust.\"\n[q2]<Right Click to Open>"}
