MultiLanguageItemData['en'][230186] = {name = "[q4]Mister Pick-Me-Up", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,108 Intellect\n[q2]Equip: Your healing spells and abilities have a chance to summon Mister Pick-Me-Up for 6 sec, firing a healing beam every 2 sec that jumps between 5 injured allies to restore 55137 health each.\n\n Overhealing from this effect irradiates allies to deal Nature damage to nearby enemies over 1.5 sec, increased by additional overhealing.\nDefeat Sprocketmonger Lockenstock in Liberation of Undermine on Mythic difficulty.\nSell Price:"}
MultiLanguageItemData['en'][230188] = {name = "[q4]Gallagio Bottle Service", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 1,341 Haste\n[q2]Use: Become the pinnacle of Gallagio service excellence and dole out Kaja'Cola Mega-Lite to injured allies 10 times over 4 sec, healing them for 789757 and increasing their Speed by 1407 for 5 sec. The number of servings is increased by your Haste. (1 Min, 30 Sec Cooldown)\nDefeat One-Armed Bandit in Liberation of Undermine on Mythic difficulty.\n[q]\"Contains 0.01% kaja'mite.\"\nSell Price:"}
MultiLanguageItemData['en'][230189] = {name = "[q4]Junkmaestro's Mega Magnet", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,108 Agility\n[q2]Equip: Your damaging abilities have a very high chance to charge the magnet, up to 30 times.\n[q2]Use: Reverse the magnet's polarity to violently recycle buried garbage, dealing ( 71728 * 1 ) Plague damage to your target per charge. Lingering virulence deals 10% of the damage dealt to 5 nearby enemies over 6 sec. (20 Sec Cooldown)\nDefeat Stix Bunkjunker in Liberation of Undermine on Mythic difficulty.\nSell Price:"}
MultiLanguageItemData['en'][230190] = {name = "[q4]Torq's Big Red Button", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 1,341 Mastery\n[q2]Use: Unleash your inner tempest to gain 6712 Strength for 15 sec. Your next 3 abilities cause a lightning blast dealing ( 359475 * 1 ) Nature damage to your primary target. Damage increased by 100% with each subsequent blast. (2 Min Cooldown)\nDefeat Cauldron of Carnage in Liberation of Undermine on Mythic difficulty.\nSell Price:"}
MultiLanguageItemData['en'][230191] = {name = "[q4]Flarendo's Pilot Light", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 1,341 Haste\n[q2]Use: Reignite the pilot light to gain 6712 Intellect for 15 sec. After casting 3 harmful spells, it unleashes a beam dealing ( 1997082 * 1 ) Fire damage to your primary target and ( 1997082 * 8 / 100 * 1 ) damage to up to 5 enemies in its path. (2 Min Cooldown)\nDefeat Cauldron of Carnage in Liberation of Undermine on Mythic difficulty.\nSell Price:"}
MultiLanguageItemData['en'][230192] = {name = "[q4]Mug's Moxie Jug", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,108 Intellect\n[q2]Equip: Your spells have a chance to send you into a frenzy, granting you 668 Critical Strike for 15 sec. While frenzied, each spell cast grants an additional 668 Critical Strike but does not refresh the duration. This effect may only occur every 1 sec.\nDefeat Mug'Zee in Liberation of Undermine on Mythic difficulty.\n[q]\"The word 'Moxie' is hastily scribbled on.\"\nSell Price:"}
MultiLanguageItemData['en'][230193] = {name = "[q4]Mister Lock-N-Stalk", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 1,341 Haste\n[q2]Equip: Your spells and abilities have a high chance to lase your target for Precision Blasting , calling in Mister Lock-N-Stalk to deal ( 790399 * 1 ) Physical damage to your target. (3s cooldown)\n[q2]Use: Recalibrate for Mass Destruction . (20 Sec Cooldown)\nDefeat Sprocketmonger Lockenstock in Liberation of Undermine on Mythic difficulty.\nSell Price:"}
MultiLanguageItemData['en'][230194] = {name = "[q4]Reverb Radio", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,108 [Agility or Strength or Intellect]\n[q2]Equip: Your spells and abilities have a high chance to Hype you up, granting 314 Haste up to 5 times. Upon reaching maximum Hype, amp it up by 100% for 15 sec before starting again.\nDefeat Rik Reverb in Liberation of Undermine on Mythic difficulty.\n[q]\"Rik & Roll, baby!\"\nSell Price:"}
MultiLanguageItemData['en'][230196] = {name = "[q4]11.0 Raid Template - Ranged DPS - Trinket", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+112 [Agility or Intellect]\nSell Price:"}
MultiLanguageItemData['en'][230197] = {name = "[q4]Geargrinder's Spare Keys", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,108 [Agility or Strength or Intellect]\n[q2]Use: Launch a Geargrinder trike to its final blaze of glory, exploding upon impacting the first enemy in its path to deal ( 1 * 1584503 ) Fire damage split between all nearby enemies. (2 Min Cooldown)\nDefeat Vexie in Liberation of Undermine on Mythic difficulty.\n[q]\"I'm gonna step on the gas!\"\nSell Price:"}
MultiLanguageItemData['en'][230198] = {name = "[q4]Eye of Kezan", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 1,341 Mastery\n[q2]Equip: Your spells and abilities have a high chance to empower the Eye and grant you 243 Primary Stat up to 20 times, decaying rapidly upon leaving combat. While fully empowered, the Eye instead deals ( 64528 * 1 ) Fire damage to enemies or heals allies for 96796 .\nDefeat Gallywix in Liberation of Undermine on Mythic difficulty.\nSell Price:"}
MultiLanguageItemData['en'][230199] = {name = "[q4]Zee's Thug Hotline", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,108 [Agility or Strength]\n[q2]Equip: Your abilities have a chance to call a member of the Goon Squad to attack your target for 10 sec. Gaining Bloodlust or a similar effect summons the whole crew.\nDefeat Mug'Zee in Liberation of Undermine on Mythic difficulty.\nSell Price:"}
