MultiLanguageItemData['en'][230727] = {name = "[q3]Explosive Victory", additional_info = "Binds when picked up\nToy\n[q2]Use: Emanate an aura of victory. (1 Hour Cooldown)"}
MultiLanguageItemData['en'][230728] = {name = "[q3]Experimental Go-Pack", additional_info = "Binds when picked up\nUnique (10)\n[q2]Use: Equip the Go-Pack and propel yourself upwards into the air. Usable for repeated jumps only on the Siren Island. (10 Sec Cooldown)\n[q]\"It has two speeds. \"What a view\" and \"Oh no, not again!\"\"\nSell Price:"}
MultiLanguageItemData['en'][230729] = {name = "Appropriated Azerothian Camera", additional_info = "Quest Item\n[q2]Use: Stand still to document nearby flora and fauna. (3 Sec Cooldown)\n[q]\"Has the initials \"W.F.\" on the back. How Ve'nari got this is a mystery.\""}
