MultiLanguageItemData['en'][231064] = {name = "[q3]Throwaway Gangster Disguise", additional_info = "Binds when picked up\nToy\n[q2]Use: Disguise yourself as a certified Undermine gangster, fooling the locals into leaving you alone for 20 min. Only usable in Undermine. (1 Hour Cooldown)"}
MultiLanguageItemData['en'][231089] = {name = "Correspondence from Zirdo", additional_info = "Quest Item\nUnique\n[q]\"A letter from Zirdo detailing Pamsy's involvement in opening the wall, attracting attention to Gallywix's Black Blood mining. This will prove Zirdo snitched on Pamsy, causing Gozzic to attack her engineers.\""}
MultiLanguageItemData['en'][231099] = {name = "[q3]Back-Strapped Missile", additional_info = "Binds when picked up\n[q2]Use: Instructions\n Step 1: Latch missile to back.\n Step 2: Ignite Missile.\n Step 3: Go up.\n\n Only usable in Undermine. (1 Min Cooldown)\nSell Price:"}
