MultiLanguageItemData['en'][231163] = {name = "Appropriated Azerothian Camera", additional_info = "Quest Item\n[q2]Use: Stand still to document nearby flora and fauna. (3 Sec Cooldown)\n[q]\"Has the initials \"W.F.\" on the back. How Ve'nari got this is a mystery.\""}
MultiLanguageItemData['en'][231164] = {name = "Goblin Grapnel", additional_info = "Quest Item\n[q2]Use: Toss the grappling hook at a Scrap Harvester within 40 yards, pulling it towards you. (5 Sec Cooldown)\n[q]\"Get flying robots to fall for you, hook, line, and sinker.\""}
MultiLanguageItemData['en'][231173] = {name = "[q4]Junkmaestro's Magnetomech", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\n[q]\"Well-suited for compacting trash into rollable balls. Junkmaestro apocrypha claims these might become worlds of their own if only they could get big enough.\"\nAchievement:\nGlory of the Liberation of Undermine Raider\nCategory:\nDungeons & Raids"}
MultiLanguageItemData['en'][231263] = {name = "The Case of the Superstitious and Hungry Pirates", additional_info = "Secrets of Azeroth\nQuest Item\nUnique\n[q]\"Notes detailing my adventures helping the stranded Booty Bay Buccaneers in their time of need.\"\n[q2]<Right Click to Read>"}
MultiLanguageItemData['en'][231264] = {name = "[q4]Glorious Cluster of Gilded Undermine Crests", additional_info = "Binds when picked up\n[q2]Use: Collect 15 Gilded Undermine Crests.\nYou cannot earn 15 Gilded Undermine Crests right now."}
MultiLanguageItemData['en'][231265] = {name = "[q4]The Jastor Diamond", additional_info = "Binds when picked up\nUnique-Equipped\nFinger\n+10,948 Stamina\n[q2]+ 826 Haste\n[q2]+ 4,626 Mastery\n[q2]Equip: Take Credit for your allies' deeds up to once every 12 sec, gaining 66 of their highest secondary stat up to 10 times until shortly after leaving combat. You have a 10% chance to get caught in the act, transferring all accumulated Credit to your ally for 15 sec instead.\nDefeat Gallywix in Liberation of Undermine on Mythic difficulty.\n[q]\"I'm not gonna give you a detailed receipt of all the businesses I took over, started, sold, or destroyed. I won: that's all. I won everything I wanted.\"\nSell Price:"}
