MultiLanguageItemData['en'][231757] = {name = "[q4]Fractured Spark of Starlight", additional_info = "The War Within Season 3\nBinds when picked up\n[q2]Use: Combine 2 Fractured Sparks of Starlight with 250 Valorstones to create a Spark of Starlight.\nCrafting Reagent\n[q]\"A fragment of a Spark of Starlight that can be reformed if combined with another piece. Primarily obtained through weekly caches.\"\nSell Price:"}
