MultiLanguageItemData['en'][232617] = {name = "[q4]Astral Gladiator's Fel Bat", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Awakened from caves in the battlefield, and armored to the fray.\"\nAchievement:\nGladiator: The War Within Season 3\nCategory:\nPlayer vs. Player"}
