MultiLanguageItemData['en'][232620] = {name = "[q4]Prized Gladiator's Conduit", additional_info = "Binds when picked up\nHeld In Off-hand\n+28 Intellect\n+15 Stamina\n[q2]+ 12 Versatility\n[q2]+ 6 Mastery\nComplete the achievement \"Prized Weapons of Conquest\" to be able to purchase additional weapons.\nSell Price:"}
MultiLanguageItemData['en'][232622] = {name = "Glyph of Energetic Ascendance", additional_info = "Binds when picked up\nClasses: Shaman\n[q2]Use: Permanently teaches you this glyph.\n\nYour Ascendance transformations embody energetic forms, unleashing their power.\nSell Price:"}
MultiLanguageItemData['en'][232623] = {name = "Ve'nari's Package", additional_info = "Quest Item\nUnique\n[q]\"Ve'nari has included both a cage and a portation tag that is tied to it. Simply put the tag on the target and they will be instantly teleported into the cage.\""}
MultiLanguageItemData['en'][232624] = {name = "[q4]Timely Buzzbee", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Buzzing through the time punctual as ever, these Buzzbees harvest the errant sands of time and return them safely to the Timeways.\"\nVendor:\nAny Timewalking Vendor\nCost:\n5000"}
