MultiLanguageItemData['en'][232628] = {name = "Wastelander Artifact", additional_info = "Quest Item\n[q]\"To the Wastelanders, these are priceless. To a collector, the value is a bit more negotiable.\""}
MultiLanguageItemData['en'][232629] = {name = "[q3]Distilled Knowledge of Timeways", additional_info = "[q7]Binds to Warband\nUnique (5)\n[q2]Use: Increases experience gained from killing monsters and completing quests by 5%.\n\n Completing Timewalking dungeons increases the effect and refreshes the duration.\n\n Upon reaching 4 applications, transforms to Mastery of Timeways , increasing that effect to 30%."}
