MultiLanguageItemData['en'][232804] = {name = "[q4]Capo's Molten Knuckles", additional_info = "Binds when picked up\nUnique-Equipped\n{One-Hand} {Fist Weapon}\n{24 - 34 Damage} {Speed 2.60}\n(11.2 damage per second)\n+10 [Agility or Strength]\n+28 Stamina\nDurability 80 / 80\n[q2]Equip: Gain a high chance to follow up your attacks with a fiery gilded uppercut, dealing ( 1218 * 1 ) Fire damage to your target. Molten gold continues to splatter to deal ( 68 * 1 * 5) Fire damage over 5 sec to all nearby enemies. Damage reduced beyond 8 enemies.\nDefeat Mug'Zee in Liberation of Undermine on Mythic difficulty.\nSell Price:"}
MultiLanguageItemData['en'][232805] = {name = "[q4]Best-in-Slots", additional_info = "Binds when picked up\nUnique-Equipped\n{Two-Hand} {Mace}\n{23 - 30 Damage} {Speed 3.60}\n(7.4 damage per second)\n+88 Intellect\n+55 Stamina\nDurability 120 / 120\n[q2]Equip: Your spells and abilities have a chance to grant you [ 79 * (0.9)] to [ 79 * (1.1)] of a random secondary stat for 15 sec.\n[q2]Use: Cheat to immediately gain [ 79 * (1.1)] of your highest secondary stat for 15 sec. While out of combat, reconfigure for melee combat instead. (2 Min Cooldown)\n[q]\"The wise goblin makes their own luck.\"\nSell Price:"}
MultiLanguageItemData['en'][232806] = {name = "[q3]Tiny Torq", additional_info = "Binds when picked up\n[q2]Use: Teaches you how to summon Tiny Torq, whose dad could TOTALLY beat up Flarendo's dad.\n[q2]Right Click to summon and dismiss this companion.\nRequires level 1 to 90 ( 90)\nRequires Renown Rank 9 with the Gallagio Loyalty Rewards Club."}
