MultiLanguageItemData['en'][232923] = {name = "[q3]Living Rose", additional_info = "Binds when picked up\n[q2]Use: Teaches you how to summon and dismiss this companion.\n[q2]Right Click to summon and dismiss this companion.\nRequires level 1 to 90 ( 90)\nSell Price:"}
