MultiLanguageItemData['en'][232925] = {name = "[q2]Ensemble: Truly Heartfelt Shoulders", additional_info = "[q7]Binds to Warband\n[q2]Use: Collect the appearances of the Truly Heartfelt Shoulders.\n[q]\"Includes a set of spaulders and shoulder capes in bright, tickled pink.\""}
MultiLanguageItemData['en'][232926] = {name = "[q4]Love Witch's Sweeper", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\nSummons and dismisses a rideable magical broom! This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"The original design of the feeling-fueled magic broom series \"Motion By Emotion\", this ride is sure to get you there in a swiffy!\"\nWorld Event:\nLove is in the Air\nDrop:\nApothecary Hummel"}
MultiLanguageItemData['en'][232930] = {name = "[q3]Zaps Leadfoot", additional_info = "Binds when picked up\nUnique\n[q2]Use: Employ this Venture Co. employee to increase the available time during Time Trials."}
MultiLanguageItemData['en'][232932] = {name = "[q0]Brann Bronzebeard's Mace", additional_info = "{Main Hand} {Mace}\n{1 Damage} {Speed 1.40}\n(0.7 damage per second)\nSell Price:"}
