MultiLanguageItemData['en'][232934] = {name = "[q2]Ensemble: Twilight Witch's Heartfelt Shoulders", additional_info = "[q7]Binds to Warband\n[q2]Use: Collect the appearances of the Twilight Witch's Heartfelt Shoulders.\n[q]\"Includes a set of spaulders and shoulder capes in deep violet.\""}
MultiLanguageItemData['en'][232935] = {name = "[q3]Vantus Rune: Liberation of Undermine", additional_info = "[q2]Use: Once per week, attune yourself to the energies of the targeted Undermine raid boss and gain the following aura:\n\nVantus Rune: Liberation of Undermine\n Increase your Versatility by 24 when fighting the targeted raid boss. This effect lasts the entire week.\nSell Price:"}
