MultiLanguageItemData['en'][232937] = {name = "[q3]Vantus Rune: Liberation of Undermine", additional_info = "[q2]Use: Once per week, attune yourself to the energies of the targeted Undermine raid boss and gain the following aura:\n\nVantus Rune: Liberation of Undermine\n Increase your Versatility by 27 when fighting the targeted raid boss. This effect lasts the entire week.\nSell Price:"}
MultiLanguageItemData['en'][232944] = {name = "Ethereal Warning Letter", additional_info = "Quest Item\nUnique\n[q]\"Don't worry about the bots at the pickup. Last guy spotted an ethereal watchin' us, and it ain't the first. These bots'll make sure no one gets the drop on ya.\""}
MultiLanguageItemData['en'][232946] = {name = "[q6]Verus", additional_info = "Binds when picked up\nUnique\n{Off Hand} {Warglaive}\n{4 - 9 Damage} {Speed 2.60}\n(2.5 damage per second)\n+12 Intellect\n+3 [Agility or Intellect]\n+4 Stamina\n[q2]+ 3 Critical Strike\n[q2]+ 2 Mastery\n\n[q0]Prismatic Socket\n[q0]Prismatic Socket\n[q0]Prismatic Socket"}
MultiLanguageItemData['en'][232978] = {name = "[q3]Louie Firehands", additional_info = "Binds when picked up\nUnique\n[q2]Use: Employ this Blackwater employee to provide an emergency explode button to your Breakneck."}
MultiLanguageItemData['en'][232979] = {name = "[q3]Jaks Jabberjaw", additional_info = "Binds when picked up\nUnique\n[q2]Use: Employ this Bilgewater employee who can slow enemies from the back of your Breakneck."}
MultiLanguageItemData['en'][232980] = {name = "[q3]Axel Sneakfoot", additional_info = "Binds when picked up\nUnique\n[q2]Use: Employ this Steamwheedle employee to provide temporary cover to your Breakneck."}
MultiLanguageItemData['en'][232981] = {name = "[q3]GNZ Airmaster 9000", additional_info = "Binds when picked up\n[q2]Use: Install this engine to increase the top speed of your G-99 Breakneck at the cost of acceleration.\nRequires Renown Rank 19 with the Cartels of Undermine.\n[q]\"That block's got cylinders with 80 millimeter bores and puts out 35,000 horses.\""}
MultiLanguageItemData['en'][232982] = {name = "[q3]The Pozzik Standard", additional_info = "Binds when picked up\n[q2]Use: Install this engine to increase the acceleration rate of your G-99 Breakneck at the cost of top speed.\n[q]\"When the Mirage Raceway was destroyed during the cataclysm, Pozzik needed a new place to refine his craft.The Undermine proved fertile grounds for an automatic revolution.\""}
MultiLanguageItemData['en'][232983] = {name = "[q3]Steamboil", additional_info = "Binds when picked up\n[q2]Use: Install this turbo to give your G-99 Breakneck a burst of speed. This turbo has a higher top speed at the cost of efficiency.\n[q]\"They say when it's burned as fuel it releases one hundred times more energy than gold nitro.\"\nSell Price:"}
MultiLanguageItemData['en'][232984] = {name = "[q3]Handcrank", additional_info = "Binds when picked up\n[q2]Use: Install this turbo to give your G-99 Breakneck a burst of speed. This turbo is more efficient at the cost of top speed.\n[q]\"There's nothing more effcient than some good old elbow grease.\"\nSell Price:"}
MultiLanguageItemData['en'][232985] = {name = "[q3]22H Slicks", additional_info = "[q2]Use: Install these wheels to increase the turning capability of your G-99 Breakneck at the cost of drifting stabilization.\n[q]\"Full surface contact for maximum friction.\"\nSell Price:"}
MultiLanguageItemData['en'][232986] = {name = "[q3]GE86 Advance", additional_info = "Binds when picked up\n[q2]Use: Install these wheels to increase the drifting stability of your G-99 Breakneck at the cost of turning capability.\n[q]\"For drivers who like to take long turns at the beach.\""}
MultiLanguageItemData['en'][232988] = {name = "Void Tear", additional_info = "Off-Hand\nUnique-Equipped\nEquipable Spell - Utility"}
MultiLanguageItemData['en'][232989] = {name = "S4F3-T Inspectors", additional_info = "Quest Item\n[q2]Use: Equip the goggles, allowing you to identify nearby building code violations in Hovel Hill."}
MultiLanguageItemData['en'][232990] = {name = "Bug Bits", additional_info = "Quest Item\n[q]\"These bug bits have been chopped up as finely as possible.\""}
MultiLanguageItemData['en'][232991] = {name = "[q4]The Breaker's Song", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses The Breaker's Song.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"'Tis a rare moment in history when a sailor carves the very monster that left 'em stranded to die upon the bow of their ship. Our lot is a blasphemous and piddly bunch. To think one of us might have the humility to honor such a creature is damn near mad.\"\nZone:\nSiren Isle\nAchievement:\nIsle Remember You"}
MultiLanguageItemData['en'][232992] = {name = "Large Bug Bits", additional_info = "Quest Item\n[q2]Use: Chop a large bug bit into 5 smaller bug bits. A pity Rhubarn never specified the size of the bug bits. Such a shame.\n[q]\"A very meaty and slimy portion of bug meat.\""}
MultiLanguageItemData['en'][233006] = {name = "[q3]Container of Highly Profitable Sludge", additional_info = "[q]\"This stuff smells funky and sloshes around in the container. Maybe don't drop it?\""}
MultiLanguageItemData['en'][233007] = {name = "[q2]Crate of Somewhat Profitable Sludge", additional_info = "[q]\"It doesn't feel that heavy, but definitely has some heft once you lug it around. Yet the burden must continue.\""}
MultiLanguageItemData['en'][233008] = {name = "Box of Lightly Profitable Sludge", additional_info = "[q]\"These small amounts don't seem like much, but in the big picture they really add up.\""}
MultiLanguageItemData['en'][233009] = {name = "Firebud Pollen", additional_info = "Quest Item\n[q]\"This pollen is uncharacteristically warm to the touch.\""}
MultiLanguageItemData['en'][233010] = {name = "Rak-ush Mushroom", additional_info = "Quest Item\n[q]\"A weighty mushroom that crumbles slightly when touched. It smells vaguely like cinnamon, of all things.\""}
MultiLanguageItemData['en'][233011] = {name = "Voshshroom", additional_info = "Quest Item\n[q]\"A very rare mushroom, apparently. It smells like a cross between dirt and mushroom.\""}
MultiLanguageItemData['en'][233013] = {name = "Coal Cookie", additional_info = "Binds when picked up\n[q2]Use: Restores ( 33750 / 5 * 25) health and ( 45000 / 5 * 25) mana over 25 sec. Must remain seated while eating."}
MultiLanguageItemData['en'][233014] = {name = "[q4]Bronze Celebration Cache of Treasures", additional_info = "Binds when picked up\n[q]\"Weekly cache containing materials for upgrading gear, gold, and more.The first weekly cache you earn each week contains a piece of Champion gear from Blackrock Depths and a Restored Coffer Key. Subsequent caches contain a piece of Veteran gear.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][233015] = {name = "Metal Scrap", additional_info = "Quest Item\n[q]\"Salvaged from broken machines and weapons, often used by tinkerers and engineers to craft or repair gadgets, armor, and various mechanical devices.\""}
MultiLanguageItemData['en'][233016] = {name = "Creature Bones", additional_info = "Quest Item\n[q]\"A collection of bones from animals in K'aresh.\""}
MultiLanguageItemData['en'][233018] = {name = "Essence Collector", additional_info = "Quest Item\n[q]\"Thick metal bars curve around a crackling violet core of energy. The collector thrums and pulses, sending an electric feeling up your arm.\""}
MultiLanguageItemData['en'][233019] = {name = "[q4]Sky Witch's Sweeper", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\nSummons and dismisses a rideable magical broom! This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"The sky's the limit when you mount up on this \"Motion By Emotion\" magic broom model.\"\nIn-Game Shop"}
MultiLanguageItemData['en'][233020] = {name = "[q4]Twilight Witch's Sweeper", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\nSummons and dismisses a rideable magical broom! This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"A darker look for the \"Motion By Emotion\" magic broom series of mounts. Fans of this color know that it looks good regardless of the time of day.\"\nIn-Game Shop"}
MultiLanguageItemData['en'][233021] = {name = "Grappling-Grabber 9000", additional_info = "[q]\"This gadget will allow you to grab goblins and explosives from a distance!\""}
MultiLanguageItemData['en'][233022] = {name = "[q3]Technique: Vantus Rune: Liberation of Undermine", additional_info = "Binds when picked up\n[q2]Use: Teaches you how to craft Vantus Rune: Liberation of Undermine.\nRequires Khaz Algar Inscription (35)\nRequires Khaz Algar Inscription and Renown Rank 5 with the Cartels of Undermine.\nSell Price:"}
MultiLanguageItemData['en'][233023] = {name = "[q4]Silvermoon Sweeper", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\nSummons and dismisses a rideable magical broom! This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"The Silvermoon color scheme for the \"Motion By Emotion\" has been a success all across Azeroth.\"\nTrading Post"}
MultiLanguageItemData['en'][233025] = {name = "Giant Pile of Gold", additional_info = "[q]\"This is a real haul! Who knew some nerubians carried this much gold?\""}
