MultiLanguageItemData['en'][233058] = {name = "[q4]Soweezi's Vintage Waveshredder", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses Soweezi's Vintage Waveshredder. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"This pretty lil' thing has a beautiful platinum sheen. It'll take ya sky-high in seconds! You'll be dancing around the sun to your heart's content for the low, low price of ten thousand smackeroonies.\"\nZone:\nSiren Isle\nVendor:\nSoweezi"}
MultiLanguageItemData['en'][233061] = {name = "[q2]Rock-in-a-Bottle", additional_info = "[q7]Binds to Warband\n[q2]Use: The complex engineering behind how such a large rock ended up in such a small bottle is a mystery to you, but your target enemy might have an idea. Stun it for 3 sec.\n\n Only usable inside of Delves. (1 Min Cooldown)\n[q]\"A big rock surrounded by a glass bottle.\"\nSell Price:"}
MultiLanguageItemData['en'][233062] = {name = "[q2]Pocket Pizza", additional_info = "[q7]Binds to Warband\n[q2]Use: Restores ( 9025 / 5 * 20) health over 20 sec. Must remain seated while eating.\n\nGreasy Well Fed\n If you spend at least 10 seconds eating you will become Greasy Well Fed and gain ( 16 * 1.5) of your highest secondary and lose 5% movement speed.\n\n Only usable in delves and outdoors in Khaz Algar.\n[q]\"Kept safe in its Venture Co. Pizza Pouch.\"\nSell Price:"}
MultiLanguageItemData['en'][233063] = {name = "[q0]Brann's Boomstick", additional_info = "Binds when picked up\n{Ranged} {Gun}\n{1 Damage} {Speed 3.00}\n(0.3 damage per second)\nSell Price:"}
MultiLanguageItemData['en'][233064] = {name = "[q4]Bronze Goblin Waveshredder", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses a Goblin Wave Shredder. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Even cartel employees deserve to have some R&R on occassion.\"\nDrop:\nDarkfuse Trove\nZone:\nUndermine"}
MultiLanguageItemData['en'][233066] = {name = "Radioactive Rat's Head", additional_info = "Quest Item\nUnique\n[q]\"Dripping with blood and glowing dangerously, you hope it's safe enough to stash in your bag.\""}
MultiLanguageItemData['en'][233068] = {name = "Rod of Analysis", additional_info = "Quest Item\nRequires level 80 to 80 ( 80)\n[q]\"This fragile crystal rod is one of many types of activation rods. This particular one analyzes data to properly restart a control console.\""}
MultiLanguageItemData['en'][233071] = {name = "[q0]Delver's Bounty", additional_info = "The War Within Season 2\nBinds when picked up\nUnique\n[q]\"Surely, great treasure awaits.\"\nSell Price:"}
