MultiLanguageItemData['en'][233186] = {name = "[q0]Wave Scrambler 2000", additional_info = "The War Within Season 2\n[q7]Binds to Warband\n[q]\"A small contraption able to specifically block the Underpin's incoming radio waves, preventing him from listening to his favorite gobcast.\"\nSell Price:"}
MultiLanguageItemData['en'][233187] = {name = "Botanical Report", additional_info = "Quest Item\nRequires level 80 to 80 ( 80)\n[q]\"A botanical report detailing every plant, seed, and count of every item and their progress within Eco-Dome: Primus.\""}
MultiLanguageItemData['en'][233189] = {name = "Shield Technician Report", additional_info = "Quest Item\nRequires level 80 to 80 ( 80)\n[q]\"A report regarding the integrity of all shield generators within Eco-Dome: Primus. This report shows a myriad of tables and charts, as well as a long checklist of eco-dome quadrants.\""}
MultiLanguageItemData['en'][233190] = {name = "[q3]Wanderer Liu", additional_info = "[q7]Binds to Warband\n[q2]Use: Teaches you how to summon and dismiss this companion.\n[q2]Right Click to summon and dismiss this companion.\nRequires level 1 to 90 ( 90)\nSell Price:"}
MultiLanguageItemData['en'][233192] = {name = "Shadowguard Weapon", additional_info = "Quest Item\n[q]\"This scepter emits a dark energy that pulls upon your essence.\""}
MultiLanguageItemData['en'][233193] = {name = "Shadowguard Weapon", additional_info = "Quest Item\n[q]\"This blade is inscribed with the last known name of its owner: Betrayer.\""}
MultiLanguageItemData['en'][233194] = {name = "Shadowguard Weapon", additional_info = "Quest Item\n[q]\"The handle feels cold to touch as if it pulls from your life force.\""}
MultiLanguageItemData['en'][233195] = {name = "Pheromone Disperser", additional_info = "Quest Item\n[q2]Use: Spray a pungent scent on anything in front of you. (3 Sec Cooldown)\n[q]\"Used to spray pheromones on the creatures in the Oasis. Not to be used on yourself.\""}
MultiLanguageItemData['en'][233196] = {name = "[q4]Delver's Gob-Trotter Schematic: Gold", additional_info = "Airship Schematic\nBinds when picked up\n[q2]Use: Unlocks this customization option for the Delver's Gob-Trotter at the Rostrum of Transformation."}
MultiLanguageItemData['en'][233199] = {name = "Saturated Entropic Core", additional_info = "Quest Item\n[q]\"Ultra condensed energies contained in a tiny space.\""}
MultiLanguageItemData['en'][233202] = {name = "[q3]G.O.L.E.M, Jr.", additional_info = "Binds when picked up\nUnique\nToy\n[q2]Use: Take control of the G.O.L.E.M. Jr. for 30 min. (1 Hour Cooldown)\n[q]\"After the G.O.L.E.M went berserk, Pitz decided to make something smaller, more precise, and smarter.\"\nSell Price:"}
MultiLanguageItemData['en'][233205] = {name = "[q2]Go-Go Juice", additional_info = "[q7]Binds to Warband\n[q2]Use: Take a swig of Venture Co.'s\n delicious energy beverage. Increase your movement speed by 1-60% for 12 sec.\n\n Only usable in delves and outdoors in Khaz Algar. (1 Min Cooldown)\n[q]\"Results may vary.\"\nSell Price:"}
MultiLanguageItemData['en'][233207] = {name = "[q4]The Coward's Azure Target", additional_info = "Cosmetic\n[q7]Binds to Warband\nBack\n[q]\"You are literally putting a target on your back.\"\n[q2]Use: Add this appearance to your Warband collection.\nSell Price:"}
MultiLanguageItemData['en'][233210] = {name = "[q2]Pungent Putrigill", additional_info = "[q7]Binds to Warband\n[q2]Use: Waft this fish in a cone in front of you inflicting Putrigill Stench to up to 5 enemies.\n\n Enemies inflicted with Putrigill Stench take 5% increased damage from you for 20 sec. Can only be used in delves and outdoors in Khaz Algar. (1 Min Cooldown)\n[q]\"A particularly stinky fish. Should not be bought or sold on the auction house.\"\nSell Price:"}
