MultiLanguageItemData['en'][233240] = {name = "[q4]Polly Roger", additional_info = "[q7]Binds to Warband\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\n\n This mount can use Ride Along.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"The scourge of the slightly-northeastern seas, giant parrots like Polly can live for up to 2000 years. What a wonderful curse on your next of kin.\"\nSpecial Event:\nPlunderstorm"}
MultiLanguageItemData['en'][233241] = {name = "[q4]Hooktalon", additional_info = "[q7]Binds to Warband\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\n\n This mount can use Ride Along.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"Hooktalon once sailed with the Bloodsail Buccaneers, and later with the Blackwater Raiders, but he left to see what plunder he could find beyond the high seas.\"\nSpecial Event:\nPlunderstorm"}
MultiLanguageItemData['en'][233242] = {name = "[q4]Royal Seafeather", additional_info = "[q7]Binds to Warband\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\nSummons and dismisses your Giant Parrot. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"The sharp beaks of these parrots are capable of breaking open large nuts with ease.\"\nSpecial Event:\nPlunderstorm"}
MultiLanguageItemData['en'][233243] = {name = "[q4]Silver Tidestallion", additional_info = "[q7]Binds to Warband\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount. Can only be used underwater.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"This tidestallion and its silvery scales were drawn to the glint of plunder in your pocket.\"\nSpecial Event:\nPlunderstorm"}
MultiLanguageItemData['en'][233246] = {name = "[q2]Gunk-Covered Thingy", additional_info = "Binds when picked up\n[q]\"Something's under all of this gunk. Angelo Rustbin at S.C.R.A.P. Headquarters will be interested in this.\""}
