MultiLanguageItemData['en'][233282] = {name = "[q4]Meeksi Rufflefur", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Rufflefurs are playful, clumsy and obsessed with cleanliness. This is a dangerous combination of traits.\"\nIn-Game Shop"}
MultiLanguageItemData['en'][233283] = {name = "[q4]Meeksi Softpaw", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Softpaws provide a black tea that is ideal for an early morning jolt or staying awake late into the night.\"\nIn-Game Shop"}
MultiLanguageItemData['en'][233284] = {name = "[q4]Meeksi Rollingpaw", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Rollingpaws are very proud of their tea bearing duties. They are always willing to provide a warm cup of tea to their travelling companions.\"\nIn-Game Shop"}
MultiLanguageItemData['en'][233285] = {name = "[q4]Meeksi Teatuft", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Teatufts are known for their aromatic teas. However, their playful nature can result in an excess of spilled tea.\"\nIn-Game Shop"}
MultiLanguageItemData['en'][233286] = {name = "[q4]Meeksi Brewthief", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Despite their mischievous and playful nature, these creatures make for loyal and dependable travelling companions.\"\nIn-Game Shop"}
