MultiLanguageItemData['en'][233444] = {name = "Kaja'Cola X-Treme", additional_info = "Binds when picked up\nUnique (5)\n[q2]Use: Increases movement speed by 50%, haste by 30%, and allows you to shovel twice as much trash from a S.C.R.A.P. Heap for 20 sec.\nRequires Renown Rank 7 with the Cartels of Undermine.\n[q]\"3-in-1 energy drink, brake cleaner, and hair conditioner.\"\nSell Price:"}
MultiLanguageItemData['en'][233445] = {name = "[q2]Kaja'Cola X-Treme Mega-Can", additional_info = "Binds when picked up\nUnique (5)\n[q2]Use: Increases movement speed by 50%, haste by 30%, and allows you to shovel twice as much trash from a S.C.R.A.P. Heap for 1 min.\nRequires Renown Rank 16 with the Cartels of Undermine.\n[q]\"Made with 100% recycled blue raspberry flavoring. Recognized as consumable in at least one jurisdiction.\"\nSell Price:"}
MultiLanguageItemData['en'][233446] = {name = "[q3]Multi-Pack of Kaja'Cola", additional_info = "Binds when picked up\nUnique (5)\n[q2]Use: Toss a round of Kaja'Cola X-Treme to up to 6 nearby players, plus an extra to yourself.\n\nKaja'Cola X-Treme :\nIncreases movement speed by 50%, haste by 30%, and allows you to shovel twice as much trash from a S.C.R.A.P. Heap for 20 sec.\nRequires Renown Rank 16 with the Cartels of Undermine.\n[q]\"Buy in bulk, save an ultimately negligible amount of money!\"\nSell Price:"}
