MultiLanguageItemData['en'][234217] = {name = "[q3]Funhouse Lens", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 [Agility or Strength or Intellect]\n[q2]Use: Look through the lens and randomly scale up or down, gaining 129 Critical Strike or Haste for 15 sec. (1 Min, 30 Sec Cooldown)\n[q]\"Tall today, tiny tomorrow.\"\nSell Price:"}
MultiLanguageItemData['en'][234218] = {name = "[q3]Goo-blin Grenade", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 Intellect\n[q2]Use: Coat the enemy in a layer of unstable slime, dealing 3364 Nature damage over 10 sec. If the target dies while slimed, it releases corrosive goo that deals 1612 Nature damage, split between nearby enemies. (1 Min, 30 Sec Cooldown)\nSell Price:"}
