MultiLanguageItemData['en'][234273] = {name = "[q3]A Dimmed Crystal", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires level 80 to 80 ( 80)\n[q]\"This cold and dark crystal comes to life with your touch. A faded deep blue glow emanates within it. You can hear a faint song within your mind.\""}
MultiLanguageItemData['en'][234274] = {name = "[q3]Schematic: 22H Slicks", additional_info = "Binds when picked up\n[q2]Use: Teaches you how to make 22H Slicks.\nRequires Khaz Algar Engineering (25)\nRequires Khaz Algar Engineering and Renown Rank 5 with the Cartels of Undermine.\nSell Price:"}
MultiLanguageItemData['en'][234281] = {name = "[q3]Undermine Cartel Work", additional_info = "[q]\"Your chosen cartel will assign world quests and other activities to your Warband this week.\""}
MultiLanguageItemData['en'][234282] = {name = "[q2]Decorative Yard Flamingo", additional_info = "[q2]Use: Place a Decorative Yard Flamingo to create a relaxing atmosphere anywhere you go. (5 Min Cooldown)\n[q]\"Add a bit of flamingo decor flare wherever you go.\"\nSell Price:"}
MultiLanguageItemData['en'][234287] = {name = "Radiant Focus", additional_info = "[q2]Use: Attempt to interpret the sacred energy within.\n[q]\"A faint mote of light glimmers from this radiant remnant.\"\nSell Price:"}
MultiLanguageItemData['en'][234326] = {name = "[q3]Core Recycling Unit", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 [Agility or Strength]\n[q2]Equip: Add an energy core to the container for every enemy slain, up to a maximum of 20.\n[q2]Use: Consume all stored energy cores to send a surge of restorative energy through you, instantly healing you for 5485 , with an additional 235 healing over 10 seconds for each core consumed. (1 Min, 30 Sec Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][234327] = {name = "[q3]Turbulent Fragment", additional_info = "Binds when picked up\n[q2]Use: Combine 3 Turbulent Fragments to create a Turbulent Runekey.\n[q]\"Even shattered, the stone vibrates with a restless energy. Tossing and turning, the stone rattles around in your bags constantly.\"\nSell Price:"}
MultiLanguageItemData['en'][234328] = {name = "[q3]Torrential Fragment", additional_info = "Binds when picked up\n[q2]Use: Combine 7 Torrential Fragments to create a Torrential Runekey.\n[q]\"While seemingly lifeless, peering at the stone fills your mind with images of vast oceans. Seas with unfathomable depths. A wave of fear washes over you as the sheer volume of it all overwhelms you.\"\nSell Price:"}
