MultiLanguageItemData['en'][234716] = {name = "[q4]Nightfall Skyreaver's Reins", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses an Nightfall Skyreaver. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Descending on their prey in the dead of night, the cries of these skyreavers once instilled terror in all the children of Draenor.\"\nVendor:\nKronnus\nZone:\nWarspear\nCost:\n5000\n\nVendor:\nTempra\nZone:\nStormshield\nCost:\n5000"}
MultiLanguageItemData['en'][234717] = {name = "[q3]Blastmaster3000", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 [Agility or Intellect]\n[q2]Use: Launch a random number of deadly grenades at your enemies, each dealing ( 1343 * 1 ) Fire damage split between nearby targets caught in the blast. (1 Min Cooldown)\n[q]\"Could be single, maybe double, or if you're lucky, TRIPLE explosions!\"\nSell Price:"}
MultiLanguageItemData['en'][234718] = {name = "[q0]Ancient Runic Hilt", additional_info = "[q]\"The visage of a female figure has been engraved into the rune-scripted hilt.\"\nSell Price:"}
MultiLanguageItemData['en'][234719] = {name = "[q0]Storm-Etched Vambrace", additional_info = "[q]\"The depiction of a stormy mountain peak has been engraved into the bracer.\"\nSell Price:"}
MultiLanguageItemData['en'][234720] = {name = "[q0]Memoric Residue", additional_info = "[q]\"The golden dust-like substance appear to be both spectral and physical in nature.\"\nSell Price:"}
MultiLanguageItemData['en'][234721] = {name = "[q4]Ur'zul Fleshripper Bridle", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses your Ur'zul Fleshripper.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"This terrifying ur'zul incorporates its latest victims into itself, creating a nearly unstoppable monster. Good thing you are treating it well, or you might be its next treat.\"\nVendor:\nAridormi\nZone:\nDalaran\nCost:\n5000"}
MultiLanguageItemData['en'][234722] = {name = "[q0]Carved Stone Fragment", additional_info = "[q]\"The stone fragment is all that remains of an ancient stone construct.\"\nSell Price:"}
MultiLanguageItemData['en'][234723] = {name = "[q0]Hollow Sigil", additional_info = "[q]\"Faded etchings surround a now-empty gem setting in the center of the sigil.\"\nSell Price:"}
