MultiLanguageItemData['en'][234732] = {name = "[q0]Bloodied Medallion", additional_info = "[q]\"Prized among the Bloodwake, these medallions are worn only by those who've won their first hundred bloody victories.\"\nSell Price:"}
MultiLanguageItemData['en'][234733] = {name = "[q0]Bloodwake Ritual Bowl", additional_info = "[q]\"The shallow ritual bowl is stained with blood-red... pigment, probably.\"\nSell Price:"}
MultiLanguageItemData['en'][234734] = {name = "[q0]Inscribed Drinking Horn", additional_info = "[q]\"The depiction of a vrykul vessel assaulted by winged creatures from the sea has been engraved onto the ivory.\"\nSell Price:"}
MultiLanguageItemData['en'][234735] = {name = "[q0]Battered Vrykul Lantern", additional_info = "[q]\"Even the bravest of vrykul refuse to embark on the open sea without their lantern. They believe it wards off the darkness beneath the waves.\"\nSell Price:"}
MultiLanguageItemData['en'][234736] = {name = "[q0]Tar-Sealed Scroll", additional_info = "[q]\"The seachart within depicts the Bloodwake ship routes and the many islands they lay siege to. Strangely, the Siren Isle is marked with a warning indicator.\"\nSell Price:"}
MultiLanguageItemData['en'][234740] = {name = "[q4]Copper-Maned Quilen Reins", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses an Copper-Maned Quilen. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Raised in the stables of the Iron Qon, these mounts are ardently steadfast, never leaving their posts even when they sensed the demise of their masters.\"\nVendor:\nMistweaver Xia\nZone:\nTimeless Isle\nCost:\n5000"}
