MultiLanguageItemData['en'][235230] = {name = "[q2]Impotent Potable", additional_info = "[q2]Use: Drink to quench your thirst and show off your cool.\n\n If you spend 10 seconds drinking in Undermine, you will become Well Hydrated which increases your movement speed by 10% for 1 hour. (5 Min Cooldown)\n[q]\"All of the class of a boozey drink with none of the alcohol!\"\nSell Price:"}
MultiLanguageItemData['en'][235238] = {name = "[q2]Exploded Plunger", additional_info = "[q2]Use: Place down an Exploded Plunger. You may push and pull on the plunger with all your might to demonstrate your strength to whomever might be interested.\n\n If used in Undermine, your Strength becomes 8% more impressive. (5 Min Cooldown)\nSell Price:"}
