MultiLanguageItemData['en'][235532] = {name = "[q2]Experimental Goblin-FUEL Supplement", additional_info = "[q7]Binds to Warband\n[q2]Use: Reduces maximum health by 50% and provides a random combat benefit.\n\n Only usable in Undermine. Enemies drop additional Market Research for the caster while active. (5 Min Cooldown)\n[q]\"Expiration Date: 'What are you, a quitter?'\""}
MultiLanguageItemData['en'][235533] = {name = "[q2]Prototype Auto-Advertiser", additional_info = "[q7]Binds to Warband\n[q2]Use: Place the auto-advertiser, causing all nearby creatures to become extremely annoyed and inflict 50% increased damage to you for 3 min.\n\n Only usable in Undermine. Enemies drop additional Market Research for the caster while active. (5 Min Cooldown)\n3 Charges\nRequires Friendly reputation with the Darkfuse Cartel in Undermine.\n[q]\"Comes preloaded with a minimal suite of ads. Get YOUR personal brand recognized in style!\""}
MultiLanguageItemData['en'][235535] = {name = "[q2]Discretely-Packaged Invention", additional_info = "[q7]Binds to Warband\n[q]\"Ain't no solution like a Darkfuse Solution. Wait, that's a pretty good slogan. Write that down!\""}
