MultiLanguageItemData['en'][235700] = {name = "[q4]Reins of the Void-Scarred Gryphon", additional_info = "[q7]Binds to Warband\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon a Void-Scarred Gryphon.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Abandoned by its trainers the Void-Scarred Gryphon scrounged on any scrap of food that remained, most corrupted by the void. With the void now sustaining them, they only land when their fickle tastes are satisfied by untainted food that they just remember enjoying.\"\nDrop:\nVoid-Scarred Gryphon\nZone:\nVision of Stormwind (Revisited)"}
MultiLanguageItemData['en'][235701] = {name = "Decaying Mecha-Scrapper Construction Kit", additional_info = "Duration: 1 day (real time)\n[q2]Use: Creates a mechanical scrapbot that repairs equipment and buys nearly anything. The scrapbot leaves after 5 min. (15 Min Cooldown)\n[q]\"Due to improper packaging, the components of this kit are steadily losing power.\"\nSell Price:"}
MultiLanguageItemData['en'][235703] = {name = "Noggenfogger Select DOWN", additional_info = "[q2]Use: Become slightly smaller. Stacks up to ten times.\n[q]\"Shrinkage guaranteed! Now chuggable!\"\nSell Price:"}
MultiLanguageItemData['en'][235704] = {name = "Noggenfogger Select UP", additional_info = "[q2]Use: Become slightly larger. Stacks up to ten times.\n[q]\"Tired of being looked down on? Now chuggable!\"\nSell Price:"}
MultiLanguageItemData['en'][235705] = {name = "[q4]Void-Forged Stallion's Reins", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n\"Forged just as their shoes once were, these beasts are less horses now and void energy in their likeness.\"\nDrop:\nVoid-Forged Stallion\nZone:\nVision of Stormwind (Revisited)"}
MultiLanguageItemData['en'][235706] = {name = "[q4]Void-Scarred Pack Mother's Harness", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Fighting her corrupted handlers this pack mother freed herself and her pups. However, freedom from their handlers did not free them from the void in this lost place. She taught her pups to be even more dangerous beasts, and they now stalk throughout Orgrimmar fetching her food as all compete to survive.\"\nDrop:\nVoid-Scarred Pack Mother\nZone:\nVision of Orgrimmar (Revisited)"}
MultiLanguageItemData['en'][235707] = {name = "[q4]Reins of the Void-Scarred Windrider", additional_info = "[q7]Binds to Warband\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon a Void-Scarred Windrider.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"When the void energies were released, it drove most windriders feral. They killed each other and their trainers. The gates to their roost were locked by the survivors. Some surviving windriders can still be seen gliding above, but none dare return to their new deadly domain to see what remains.\"\nDrop:\nVoid-Scarred Windrider\nZone:\nVision of Orgrimmar (Revisited)"}
MultiLanguageItemData['en'][235709] = {name = "[q4]Ny'alothan Shadow Worm", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount. This is a flying mount.\n[q2]Summons and dismisses your Ny'alothan Shadow Worm.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"A remnant of the Black Empire's past, these precursors of the abyss worms are once again resurging with the rise of Ny'alotha.\"\nAchievement:\nMastering the VisionsCategory:\nVisions of N'Zoth Revisited"}
MultiLanguageItemData['en'][235710] = {name = "Noggenfogger Select FRESH", additional_info = "Binds when picked up\nRaces: Goblin\n[q2]Use: Temporarily become cool.\n[q]\"Wear the freshest clothes, eat at the chillest restaurants, and drink the hottest potions!\"\nSell Price:"}
MultiLanguageItemData['en'][235711] = {name = "[q4]Corruption of the Aspects", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses the Corruption of the Aspects. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires the achievement We Have the Memories, fully unlocking all upgrades for the Hourglass of Horrific Visions.\n\n\n[q]\"With N'Zoth's triumph, what started with Galakrond comes to fruition. With the Aspects gone, the corruption of their species is complete.\"\nVendor:\nTorie\nZone:\nDornogal\nCost:\n40000"}
MultiLanguageItemData['en'][235712] = {name = "[q3]Void-Crystal Panther", additional_info = "[q7]Binds to Warband\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount. This mount will fly or run, depending on your riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price: \n[q]\"Although many precious gems have been corrupted by void energies in horrific visions, Master Jewelcrafters can still utilize them to craft mighty panther steeds.\"\nProfession:\nJewelcrafting"}
MultiLanguageItemData['en'][235713] = {name = "Weird Sand", additional_info = "Binds when picked up\n[q2]Use: Eat me.\n[q]\"Dregs from the bottom of a Noggenfogger Select. Must be part of the recipe.\""}
MultiLanguageItemData['en'][235715] = {name = "Blue Floristar", additional_info = "Quest Item\n[q]\"Surrounded by velvety petals, the star-shaped center smells like lemon and the sea breeze.\""}
