MultiLanguageItemData['en'][235799] = {name = "[q3]Throwin' Sawblade", additional_info = "Binds when picked up\nUnique\nToy\n[q2]Use: Throw the sawblade to a friendly player. If possible, they will automatically return it. (5 Sec Cooldown)\nRequires Revered reputation with the Venture Company Cartel in Undermine.\n[q]\"You better hope you catch it.\""}
MultiLanguageItemData['en'][235800] = {name = "Recipe: Authentic Undermine Clam Chowder", additional_info = "Binds when picked up\n[q2]Use: Teaches you the correct way to prepare Undermine Clam Chowder.\n[q2]Recipe for 3 servings. Actual number of servings will vary based on cooking skill.\nRequires Khaz Algar Cooking (35)\nSell Price:"}
MultiLanguageItemData['en'][235801] = {name = "[q3]Personal Fishing Barge", additional_info = "Binds when picked up\nUnique\nToy\n[q2]Use: You can raft across water.\nRequires Revered reputation with the Blackwater Cartel in Undermine.\n[q]\"Warning: Exposure to water voids warranty.\""}
MultiLanguageItemData['en'][235803] = {name = "Potion of Mysterious Celerity", additional_info = "[q2]On Looted: Increases your movement speed by 10%.\n\n Lasts 30 min and persists through death.\n\nThis item is consumed immediately."}
MultiLanguageItemData['en'][235805] = {name = "Authentic Undermine Clam Chowder", additional_info = "[q2]Use: Restores ( 11172 / 5 * 20) health over 20 sec. Must remain seated while eating.\n\n Well Fed\n If you spend at least 10 seconds eating you will become Well Fed and gain 16 of your highest secondary stat for 1 hour.\n[q]\"The real deal. The genuine article. The clam's shell. Perfection in a cup!\"\nSell Price:"}
MultiLanguageItemData['en'][235806] = {name = "[q2]Tytalor's Staff", additional_info = "Binds when picked up\n{Two-Hand} {Staff}\n{4 - 6 Damage} {Speed 3.60}\n(1.4 damage per second)\n+19 Intellect\n+6 Stamina\n[q2]+ 4 Haste\n[q2]+ 4 Mastery\nClasses: Mage\n[q]\"The staff is gilded in a gold veneer, much like Tytalor's personality.\"\nSell Price:"}
MultiLanguageItemData['en'][235807] = {name = "[q3]Storefront-in-a-Box", additional_info = "Binds when picked up\nUnique\nToy\n[q2]Use: Place a goblin market stall designed to last for 15 min. Can only be used outdoors. (15 Min Cooldown)\nRequires Revered reputation with the Bilgewater Cartel in Undermine.\n[q]\"Always gotta be prepared to set up shop.\""}
MultiLanguageItemData['en'][235808] = {name = "Torn Spellbook Page", additional_info = "Quest Item\n[q]\"The entry gleams with magic, freshly picked from the source.\""}
MultiLanguageItemData['en'][235809] = {name = "[q4]Mechanized Plate Chasse", additional_info = "Binds when picked up\n{Chest} {Plate}\n56 Armor\n+17 [Strength or Intellect]\n+25 Stamina\n[q2]+ 12 Versatility\n[q2]+ 22 Mastery\nDurability 165 / 165\nSell Price:"}
MultiLanguageItemData['en'][235810] = {name = "[q4]Circuit-Linked Chainmail", additional_info = "Binds when picked up\n{Chest} {Mail}\n37 Armor\n+17 [Agility or Intellect]\n+25 Stamina\n[q2]+ 12 Versatility\n[q2]+ 22 Mastery\nDurability 165 / 165\nSell Price:"}
MultiLanguageItemData['en'][235811] = {name = "[q4]Extravagant Epaulets", additional_info = "Binds when picked up\n{Shoulder} {Leather}\n17 Armor\n+13 [Agility or Intellect]\n+19 Stamina\n[q2]+ 9 Critical Strike\n[q2]+ 16 Mastery\nDurability 100 / 100\nSell Price:"}
MultiLanguageItemData['en'][235812] = {name = "[q4]Shoulderguards of Fraying Sanity", additional_info = "Binds when picked up\n{Shoulder} {Cloth}\n10 Armor\n+13 Intellect\n+19 Stamina\n[q2]+ 9 Critical Strike\n[q2]+ 16 Haste\nDurability 100 / 100\nSell Price:"}
MultiLanguageItemData['en'][235813] = {name = "[q4]Machine Gob's Iron Grin", additional_info = "Binds when picked up\nUnique-Equipped\n{Two-Hand} {Mace}\n{46 - 60 Damage} {Speed 3.60}\n(14.7 damage per second)\n+20 [Agility or Strength]\n+55 Stamina\nDurability 120 / 120\n[q2]Equip: Your harmful melee attacks and abilities have a chance to trigger the detonation mechanism, dealing up to 3176 Fire damage split between nearby enemies.\n\n Blast strength and radius may vary. (1s cooldown)\n[q]\"Advertised with the slogan 'Big bonk goes big boom!'\"\nSell Price:"}
