MultiLanguageItemData['en'][237746] = {name = "[q6]Warswords of the Valarjar", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Two-Hand} {Sword}\n{5 - 9 Damage} {Speed 3.60}\n(1.9 damage per second)\n+3 Strength\n+4 Stamina\nClasses: Warrior\nRequires level 10 to 90 ( 90)\nRequiresFury Warrior\n[q]\"Helya's betrayal shall never be forgiven. Let her rot beneath the waves, far from the Halls of Valor.\""}
MultiLanguageItemData['en'][237747] = {name = "[q6]Warswords of the Valarjar", additional_info = "Binds when picked up\nUnique\n{Two-Hand} {Sword}\n{5 - 9 Damage} {Speed 3.60}\n(1.9 damage per second)\n+3 Strength\n+4 Stamina\nClasses: Warrior\nRequires level 10 to 90 ( 90)\nRequiresFury Warrior\n[q]\"In truth, it is her power that makes these weapons truly magnificent. Her power, laced with her hatred, crashes endlessly against Odyn's spirit. The tension between those energies will forever permeate these blades...\""}
MultiLanguageItemData['en'][237748] = {name = "[q6]Scaleshard", additional_info = "Binds when picked up\nUnique\n{Main Hand} {Sword}\n{2 - 5 Damage} {Speed 2.60}\n(1.3 damage per second)\n+1 Strength\n+2 Stamina\nClasses: Warrior\nRequires level 10 to 90 ( 90)\nRequiresProtection Warrior\n[q]\"Here is whence true strength comes. From deep places... within the world, and within oneself.\""}
MultiLanguageItemData['en'][237749] = {name = "[q6]Scale of the Earth-Warder", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Off Hand} {Shield}\n44 Armor\n+1 Strength\n+4 Intellect\n+2 Stamina\nClasses: Warrior\nRequires level 10 to 90 ( 90)\nRequiresProtection Warrior\n[q]\"...it was one of Neltharion's cast-off scales. It saved Magnar's life. The blast of flame parted around the black scale, but the sheer force carried Magnar out of the lair, sending him tumbling down the slopes of Highmountain.\""}
