MultiLanguageItemData['en'][238678] = {name = "[q3]Lesser Rune of Echoing Void", additional_info = "[q7]Binds to Warband\n[q2]Use: Apply Lesser Rune of the Echoing Void to a helm.\n\n Your damaging abilities build the Echoing Void. Each time it builds, Echoing Void has a chance to collapse, dealing ( 1 * 708) Shadow damage to all nearby enemies every 1 sec until no stacks remain.\n\n Cannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:"}
MultiLanguageItemData['en'][238680] = {name = "[q4]Greater Rune of Echoing Void", additional_info = "[q7]Binds to Warband\n[q2]Use: Apply Greater Rune of the Echoing Void to a helm.\n\n Your damaging abilities build the Echoing Void. Each time it builds, Echoing Void has a chance to collapse, dealing ( 1 * 1215) Shadow damage to all nearby enemies every 1 sec until no stacks remain.\n\n Cannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:"}
