MultiLanguageItemData['en'][238897] = {name = "[q4]Spring Harvesthog", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"The Spring Harvesthog is at its most energetic in the early morning. It will spend most of its day snuffling for food or bellowing out calls for other harvesthogs.\"\nTrading Post"}
MultiLanguageItemData['en'][238900] = {name = "[q4]Summer Harvesthog", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"The Summer Harvesthog enjoys laying out in the sun or going for a swim in a clear lake. They are excellent at foraging for food, but need to be coaxed into it.\"\nTrading Post"}
MultiLanguageItemData['en'][238901] = {name = "[q4]Winter Harvesthog", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"Winter Harvesthogs are primarily nocturnal creatures. They are slightly slower than other harvesthogs, but their endurance is unmatched.\"\nTrading Post"}
MultiLanguageItemData['en'][238902] = {name = "[q4]Autumn Harvesthog", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"Autumn Harvesthogs excel in snuffling for food in the cooler months. Their keen sense of smell makes them excellent companions for a forrest forage, but difficult to control in aromatic settings.\"\nTrading Post"}
MultiLanguageItemData['en'][238903] = {name = "Appropriated Azerothian Camera", additional_info = "Quest Item\n[q2]Use: Stand still to document nearby flora and fauna. (3 Sec Cooldown)\n[q]\"Has the initials \"W.F.\" on the back. How Ve'nari got this is a mystery.\""}
MultiLanguageItemData['en'][238904] = {name = "Anima Vacuum", additional_info = "Quest Item\n[q2]Use: Suck up nearby critters, ne'er-do-wells, and cosmic entities (probably).\n\n May walk while casting. (3 Sec Cooldown)\n[q]\"Apparently there is a portal in the back that leads directly to K'aresh. You've been assured it's safe. Probably.\""}
