MultiLanguageItemData['en'][238910] = {name = "Lasso", additional_info = "Quest Item\nUnique\n[q2]Use: Lasso a Tranquil Necroray, so you can bring it in for a medical checkup and vitamins. (6 Sec Cooldown)\n[q]\"A piece of rope tied into a lasso. Nothing fancy about it.\""}
MultiLanguageItemData['en'][238911] = {name = "Pheromone Disperser", additional_info = "Quest Item\n[q2]Use: Spray a pungent scent on anything in front of you. (3 Sec Cooldown)\n[q]\"Used to spray pheromones on the creatures in the Oasis. Not to be used on yourself.\""}
MultiLanguageItemData['en'][238912] = {name = "Tranquilizing Dart", additional_info = "Quest Item\n[q2]Use: Shoots a Tranquilizer Dart at your target, causing them to fall into a deep and blissful slumber.\n[q]\"Tranquilizes anything it's thrown at by temporarily disrupting their spiritual web. Non-invasive and pain-free. Apparently a common prank to pull on unsuspecting friends.\""}
MultiLanguageItemData['en'][238913] = {name = "Condenser Disc", additional_info = "Quest Item\n[q2]Use: Throw a disc to shrink creatures to a portable size.\n[q]\"Can be thrown to shrink creatures to a portable size.\""}
