MultiLanguageItemData['en'][238966] = {name = "[q4]Felborn Cormaera", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\nSummons and dismisses a Felborn Cormaera. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"Cormaera were an early species on Azeroth that were claimed by elemental lords.\"\nPromotion"}
MultiLanguageItemData['en'][238967] = {name = "[q4]Molten Cormaera", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\nSummons and dismisses a Molten Cormaera. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"In the earliest days of Azeroth, these elemental predators dominated the inferno-choked skies of Ragnaros's domain.\"\nTrading Post"}
MultiLanguageItemData['en'][238968] = {name = "[q4]Lavaborn Cormaera", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\nSummons and dismisses a Lavaborn Cormaera. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"Under the eye of the elemental lords, many cormaera were twisted by their forces and became loyal mounts and partners.\"\nTrading Post"}
