MultiLanguageItemData['en'][239076] = {name = "[q4]Herald of Sa'bak", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"The Tol'vir tell of the legendary Sa'bak, a great crocolisk believed to have emerged from the sacred valley of Un'Goro crater. Although few have ever seen Sa'bak in the flesh, many believe he was blessed by the Titan Keepers to safeguard the vast waterways of Uldum.\"\nIn-Game Shop"}
MultiLanguageItemData['en'][239077] = {name = "[q2]Mound of Mildly-Meaningful Meat", additional_info = "Binds when picked up\n[q]\"A pile of meat left over from a creature you skinned. It could be from the creature itself, or something it ate. Only one way to find out!\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][239078] = {name = "[q3]Lesser Rune of Infinite Stars", additional_info = "[q7]Binds to Warband\n[q2]Use: Apply Lesser Rune of Infinite Stars to a helm.\n\n Your spells and abilities have a chance to strike a nearby enemy with an Infinite Star, dealing ( 1 * 2084) Arcane damage and increasing their damage taken from your Infinite Stars by ( 1 * 729), stacking up to 6 times before resetting.\n\n Cannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:"}
MultiLanguageItemData['en'][239080] = {name = "[q4]Greater Rune of Infinite Stars", additional_info = "[q7]Binds to Warband\n[q2]Use: Apply Greater Rune of Infinite Stars to a helm.\n\n Your spells and abilities have a chance to strike a nearby enemy with an Infinite Star, dealing ( 1 * 3572) Arcane damage and increasing their damage taken from your Infinite Stars by ( 1 * 1250), stacking up to 6 times before resetting.\n\n Cannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:"}
MultiLanguageItemData['en'][239082] = {name = "[q3]Sa'bak's Blessed", additional_info = "[q7]Binds to Warband\n[q2]Use: Teaches you how to summon this companion.\n[q2]Right Click to summon and dismiss this companion.\nRequires level 1 to 90 ( 90)"}
MultiLanguageItemData['en'][239083] = {name = "Head of Brulagh the Crusher", additional_info = "Quest Item\nRequires level 83 to 88 ( 88)\n[q]\"Flecked with gore and battered with bruises.\""}
MultiLanguageItemData['en'][239084] = {name = "[q3]Lesser Rune of Gushing Wound", additional_info = "[q7]Binds to Warband\n[q2]Use: Apply Lesser Rune of Gushing Wound to a helm.\n\n Your damaging spells and abilities have a chance to cause your target to ooze blood for ( 1 * 373 * 7) damage over 7 sec.\n\n Cannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:"}
MultiLanguageItemData['en'][239086] = {name = "[q4]Greater Rune of Gushing Wound", additional_info = "[q7]Binds to Warband\n[q2]Use: Apply Greater Rune of Gushing Wound to a helm.\n\n Your damaging spells and abilities have a chance to cause your target to ooze blood for ( 1 * 639 * 7) damage over 7 sec.\n\n Cannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:"}
MultiLanguageItemData['en'][239088] = {name = "[q3]Lesser Rune of the Twisted Appendage", additional_info = "[q7]Binds to Warband\n[q2]Use: Apply Lesser Rune of the Twisted Appendage to a helm.\n\n Your attacks have a chance to spawn a tentacle which Mind Flays your target for ( 1 * 938) Shadow damage every second for 10 sec.\n\n Cannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:"}
MultiLanguageItemData['en'][239090] = {name = "[q4]Greater Rune of the Twisted Appendage", additional_info = "[q7]Binds to Warband\n[q2]Use: Apply Greater Rune of the Twisted Appendage to a helm.\n\n Your attacks have a chance to spawn a tentacle which Mind Flays your target for ( 1 * 1607) Shadow damage every second for 10 sec.\n\n Cannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:"}
MultiLanguageItemData['en'][239093] = {name = "[q3]Lesser Rune of the Void Ritual", additional_info = "[q7]Binds to Warband\n[q2]Use: Apply Lesser Rune of the Void Ritual to a helm.\n\n Gain Void Ritual, giving your spells and abilities a chance to increase all secondary stats by 0 every sec for 20 sec.\n\n Cannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:"}
MultiLanguageItemData['en'][239095] = {name = "[q4]Greater Rune of the Void Ritual", additional_info = "[q7]Binds to Warband\n[q2]Use: Apply Greater Rune of the Void Ritual to a helm.\n\n Gain Void Ritual, giving your spells and abilities a chance to increase all secondary stats by 1 every sec for 20 sec.\n\n Cannot be applied to items lower than level 350. This effect is fleeting and will only work during The War Within Season 2.\nSell Price:"}
MultiLanguageItemData['en'][239098] = {name = "Neighborhood Charter", additional_info = "Quest Item\nUnique\n[q2]Use: Opens neighborhood charter. Allows you to request signatures from other players. (10 Sec Cooldown)\n[q]\"A charter to create your own neighborhood.\""}
