MultiLanguageItemData['en'][241632] = {name = "[q0]Heroic Waxy Figurine", additional_info = "Binds when picked up\n[q]\"A carefully carved and sculpted wax blob that Skibbles made to resemble you. It's clear she worked very hard on it, even though it's hard to tell where the face is.\"\nSell Price:"}
MultiLanguageItemData['en'][241633] = {name = "[q0]Tiny Decorative Rocket", additional_info = "Binds when picked up\n[q]\"When the little crank is wound, the miniature tin rocket makes a faint whirring sound and a wooden exhaust flame gently spins. A simple depiction of a small nerubian and a stick figure is scratched into one of the rocket fins.\"\nSell Price:"}
MultiLanguageItemData['en'][241635] = {name = "[q0]Patchy Spider-Silk Square", additional_info = "Binds when picked up\n[q]\"This small poorly woven square seems to depict both nerubian and Arathi-inspired patterns. It has your initials crudely stitched in one corner.\"\nSell Price:"}
MultiLanguageItemData['en'][241636] = {name = "[q0]Storm Glass and Feather Necklace", additional_info = "Binds when picked up\n[q]\"One single electric blue stormrook feather dangles gently between two fragments of Storm Glass. A small, rusty Undermine minted nut and bolt act as the clasp.\"\nSell Price:"}
