MultiLanguageItemData['en'][242553] = {name = "[q2]Sanguine Garnet", additional_info = "Garnet\nCrafting Reagent\n[q]\"Acquired by Jewelcrafters when prospecting Midnight ore. Can be bought and sold on the Auction House.\"\nSell Price:"}
MultiLanguageItemData['en'][242554] = {name = "[q2]Amani Lapis", additional_info = "Lapis\nCrafting Reagent\n[q]\"Acquired by Jewelcrafters when prospecting Midnight ore. Can be bought and sold on the Auction House.\"\nSell Price:"}
MultiLanguageItemData['en'][242555] = {name = "[q6]Ashbringer", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Two-Hand} {Sword}\n{5 - 9 Damage} {Speed 3.60}\n(1.9 damage per second)\n+3 Strength\n+4 Stamina\nClasses: Paladin\nRequires level 10 to 90 ( 90)\nRequires Retribution Paladin\n[q]\"So it was that over the course of time, the man and the weapon seemed as one. Ashbringer became a name of legend, attributed not just to the fearsome blade but also to the relentless knight who wielded it.\"\nSell Price:"}
MultiLanguageItemData['en'][242556] = {name = "[q6]Twinblades of the Deceiver", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Main Hand} {Warglaive}\n{3 - 5 Damage} {Speed 2.60}\n(1.5 damage per second)\n+7 Intellect\n+1 [Agility or Intellect]\n+2 Stamina\nClasses: Demon Hunter\nRequires level 10 to 90 ( 90)\nRequiresHavoc Demon Hunter\n[q]\"Make examples of those foolish enough to oppose you, and the rest of their kind will grovel at your feet.\"\nSell Price:"}
MultiLanguageItemData['en'][242557] = {name = "[q6]Twinblades of the Deceiver", additional_info = "Binds when picked up\nUnique\n{Off Hand} {Warglaive}\n{3 - 5 Damage} {Speed 2.60}\n(1.5 damage per second)\n+7 Intellect\n+1 [Agility or Intellect]\n+2 Stamina\nClasses: Demon Hunter\nRequires level 10 to 90 ( 90)\nRequiresHavoc Demon Hunter\n[q]\"The end has come! Let the unravelling of this world commence!\"\nSell Price:"}
MultiLanguageItemData['en'][242558] = {name = "[q6]Aluneth", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Two-Hand} {Staff}\n{3 - 4 Damage} {Speed 3.60}\n(1.0 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Mage\n[q2]Equip: Grants the Mark of Aluneth ability, which places a rune on the ground that explodes for massive damage after a short delay.\nRequires level 10 to 90 ( 90)\nRequiresArcane Mage\n[q]\"After many setbacks, Aegwynn finally bound the entity to an enchanted greatstaff. The task of containing Aluneth was done, but it would take the Guardian years to truly harness its power.\"\nSell Price:"}
MultiLanguageItemData['en'][242559] = {name = "[q6]Blades of the Fallen Prince", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Main Hand} {Sword}\n{2 - 5 Damage} {Speed 2.60}\n(1.3 damage per second)\n+1 Strength\n+2 Stamina\nClasses: Death Knight\nRequires level 10 to 90 ( 90)\nRequires Frost Death Knight\n[q]\"When my days have come to an end, you shall be king.\"\nSell Price:"}
MultiLanguageItemData['en'][242560] = {name = "[q6]Blades of the Fallen Prince", additional_info = "Binds when picked up\nUnique\n{Off Hand} {Sword}\n{2 - 5 Damage} {Speed 2.60}\n(1.3 damage per second)\n+1 Strength\n+2 Stamina\nClasses: Death Knight\nRequires level 10 to 90 ( 90)\nRequires Frost Death Knight\n[q]\"I will show you the justice of the grave... and the true meaning of fear.\""}
MultiLanguageItemData['en'][242561] = {name = "[q6]G'Hanir, the Mother Tree", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Two-Hand} {Staff}\n{3 - 4 Damage} {Speed 3.60}\n(1.0 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Druid\nRequires level 10 to 90 ( 90)\nRequires Restoration Druid\n[q]\"At the beginning, there was a source of healing and balance, a place where all life could rest and revive.\"\nSell Price:"}
MultiLanguageItemData['en'][242562] = {name = "[q6]Maw of the Damned", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Two-Hand} {Axe}\n{4 - 10 Damage} {Speed 3.60}\n(1.9 damage per second)\n+3 Strength\n+4 Stamina\nClasses: Death Knight\nRequires level 10 to 90 ( 90)\nRequires Blood Death Knight\n[q]\"The Maw's thirst is unquenchable. If it is not fed fresh victims, it will not hesitate to drink from its wielder instead.\"\nSell Price:"}
MultiLanguageItemData['en'][242563] = {name = "[q6]Apocalypse", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Two-Hand} {Sword}\n{5 - 9 Damage} {Speed 3.60}\n(1.9 damage per second)\n+3 Strength\n+4 Stamina\nClasses: Death Knight\nRequires level 10 to 90 ( 90)\nRequires Unholy Death Knight\n[q]\"It shall sow destruction and war. Famine and death. It shall tempt with power, and then bring an end to all life.\"\nSell Price:"}
MultiLanguageItemData['en'][242564] = {name = "[q6]Fangs of the Devourer", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Main Hand} {Dagger}\n{2 - 3 Damage} {Speed 1.80}\n(1.4 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Rogue\nRequires level 10 to 90 ( 90)\nRequiresSubtlety Rogue\n[q]\"The hound's bite lingers, even long after its death. A surprisingly effective and subtle tool for something so crude.\"\nSell Price:"}
MultiLanguageItemData['en'][242565] = {name = "[q6]Fangs of the Devourer", additional_info = "Binds when picked up\nUnique\n{Off Hand} {Dagger}\n{2 - 3 Damage} {Speed 1.80}\n(1.4 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Rogue\nRequires level 10 to 90 ( 90)\nRequiresSubtlety Rogue\n[q]\"Azhir manari kirel. Akim manari galar!\"\nSell Price:"}
MultiLanguageItemData['en'][242566] = {name = "[q6]Talonclaw", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Two-Hand} {Polearm}\n{5 - 9 Damage} {Speed 3.60}\n(1.9 damage per second)\n+3 Agility\n+4 Stamina\nClasses: Hunter\nRequires level 10 to 90 ( 90)\nRequires Survival Hunter\n[q]\"The Eagle Spear. Spear of the Wild Gods. Talonclaw. Bearing many names and many blessings, this is a weapon of legends.\"\nSell Price:"}
MultiLanguageItemData['en'][242567] = {name = "[q6]Doomhammer", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Main Hand} {Mace}\n{3 - 4 Damage} {Speed 2.60}\n(1.3 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Shaman\nRequires level 10 to 90 ( 90)\nRequiresEnhancement Shaman\n[q]\"A stranger will raise the hammer high, and with it justice shall reign.\"\nSell Price:"}
MultiLanguageItemData['en'][242568] = {name = "[q6]Felo'melorn", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Main Hand} {Sword}\n{1 - 2 Damage} {Speed 2.60}\n(0.6 damage per second)\n+8 Intellect\n+2 Stamina\nClasses: Mage\nRequires level 10 to 90 ( 90)\nRequiresFire Mage\n[q]\"...not elven weapons. Not when they are reforged with magic, and hatred, and a burning need for revenge. No, Arthas. Felo'melorn is stronger than ever-as am I. - Kael'thas Sunstrider\"\nSell Price:"}
MultiLanguageItemData['en'][242569] = {name = "[q6]Claws of Ursoc", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Main Hand} {Fist Weapon}\n{3 - 5 Damage} {Speed 2.60}\n(1.5 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Druid\nRequires level 10 to 90 ( 90)\nRequires Guardian Druid\n[q]\"Ursoc, brother of Ursol and guardian of the furbolg tribes... bearer of the strength of the forest itself.\"\nSell Price:"}
MultiLanguageItemData['en'][242570] = {name = "[q6]Claws of Ursoc", additional_info = "Binds when picked up\nUnique\n{Off Hand} {Fist Weapon}\n{3 - 5 Damage} {Speed 2.60}\n(1.5 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Druid\nRequires level 10 to 90 ( 90)\nRequires Guardian Druid\n[q]\"Azeroth will need you. If you do not stand ready, the world may fall.\"\nSell Price:"}
MultiLanguageItemData['en'][242571] = {name = "[q6]The Silver Hand", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Two-Hand} {Mace}\n{2 - 4 Damage} {Speed 3.60}\n(0.8 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Paladin\nRequires level 10 to 90 ( 90)\nRequires Holy Paladin\n[q]\"Tyr replied that he did not consider his argent hand a reminder of defeat. For him it was a symbol of the sacrifice he had made to defend Azeroth, and he wanted the world to see it that way as well.\"\nSell Price:"}
MultiLanguageItemData['en'][242573] = {name = "[q6]T'uure, Beacon of the Naaru", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Two-Hand} {Staff}\n{3 - 4 Damage} {Speed 3.60}\n(1.0 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Priest\nRequires level 10 to 90 ( 90)\nRequires Holy Priest\n[q]\"Blessed are the torchbearers, who bring light to the darkness.\"\nSell Price:"}
MultiLanguageItemData['en'][242574] = {name = "[q6]Thas'dorah, Legacy of the Windrunners", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Ranged} {Bow}\n{5 - 7 Damage} {Speed 3.00}\n(2.0 damage per second)\n+3 Agility\n+4 Stamina\nClasses: Hunter\nRequires level 10 to 90 ( 90)\nRequires Marksmanship Hunter\n[q]\"When it was retrieved from the Sunwell, the bow radiated power. Talanas was humbled by the gift. He named the weapon Thas'dorah, \"Valor of the Forest.\"\"\nSell Price:"}
MultiLanguageItemData['en'][242575] = {name = "[q6]Xal'atath, Blade of the Black Empire", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Main Hand} {Dagger}\n{1 - 2 Damage} {Speed 1.80}\n(0.8 damage per second)\n+8 Intellect\n+2 Stamina\nClasses: Priest\nRequires level 10 to 90 ( 90)\nRequires Shadow Priest\n[q]\"Xal'atath has a mind of its own. Ignore its maddening whispers. Do not trust the lies it spins. Take from it what you need, but always remember that the dark presence in the blade is not your ally.\"\nSell Price:"}
MultiLanguageItemData['en'][242576] = {name = "[q6]Aldrachi Warblades", additional_info = "Binds when picked up\nUnique\n{Off Hand} {Warglaive}\n{3 - 5 Damage} {Speed 2.60}\n(1.5 damage per second)\n+7 Intellect\n+1 [Agility or Intellect]\n+2 Stamina\nClasses: Demon Hunter\nRequires level 10 to 90 ( 90)\nRequiresVengeance Demon Hunter\n[q]\"His warblades howled over the clamor of battle, rending anything that came near. Each demon Toranaar vanquished seemed to fill him with renewed vigor and strength. He was an army unto himself.\""}
MultiLanguageItemData['en'][242577] = {name = "[q6]Aldrachi Warblades", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Main Hand} {Warglaive}\n{3 - 5 Damage} {Speed 2.60}\n(1.5 damage per second)\n+7 Intellect\n+1 [Agility or Intellect]\n+2 Stamina\nClasses: Demon Hunter\nRequires level 10 to 90 ( 90)\nRequiresVengeance Demon Hunter\n[q]\"The Aldrachi were a proud race. Too proud to serve. Millions of demons died before the Aldrachi were wiped out, and it took Sargeras himself to kill their king.\""}
MultiLanguageItemData['en'][242578] = {name = "[q6]Scythe of Elune", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Two-Hand} {Staff}\n{3 - 4 Damage} {Speed 3.60}\n(1.0 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Druid\nRequires level 10 to 90 ( 90)\nRequires Balance Druid\n[q]\"There is power within that would be freed. With balance and control, the wolf may be tamed, but only for a time.\"\nSell Price:"}
MultiLanguageItemData['en'][242579] = {name = "[q6]Fangs of Ashamane", additional_info = "Binds when picked up\nUnique\n{Off Hand} {Dagger}\n{2 - 3 Damage} {Speed 1.80}\n(1.4 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Druid\nRequires level 10 to 90 ( 90)\nRequires Feral Druid\n[q]\"She ripped through the demons' ranks and then disappeared into the trees. She crept along the high branches and dove down upon the Legion commanders. She was a terror, a fearsome beast, and she held nothing back, offering no mercy.\"\nSell Price:"}
MultiLanguageItemData['en'][242580] = {name = "[q6]Fangs of Ashamane", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Main Hand} {Dagger}\n{2 - 3 Damage} {Speed 1.80}\n(1.4 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Druid\nRequires level 10 to 90 ( 90)\nRequires Feral Druid\n[q]\"The sacrifice of Ashamane is remembered to this day. We live by her grace, and her children still tread the forests with us as our closest companions.\"\nSell Price:"}
MultiLanguageItemData['en'][242581] = {name = "[q6]Titanstrike", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Ranged} {Gun}\n{4 - 8 Damage} {Speed 3.00}\n(2.0 damage per second)\n+3 Agility\n+4 Stamina\nClasses: Hunter\nRequires level 10 to 90 ( 90)\nRequires Beast Mastery Hunter\n[q]\"A peerless example of techno-magical engineering, infused with the power of storms.\"\nSell Price:"}
MultiLanguageItemData['en'][242582] = {name = "[q6]Ebonchill", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Two-Hand} {Staff}\n{3 - 4 Damage} {Speed 3.60}\n(1.0 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Mage\nRequires level 10 to 90 ( 90)\nRequiresFrost Mage\n[q]\"Ebonchill contained only a sliver of Alodi's might, but even that was more than most magi could ever hope of wielding.\"\nSell Price:"}
MultiLanguageItemData['en'][242583] = {name = "[q6]Truthguard", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Off Hand} {Shield}\n44 Armor\n+1 Strength\n+4 Intellect\n+2 Stamina\nClasses: Paladin\nRequires level 10 to 90 ( 90)\nRequires Protection Paladin\n[q]\"With the first hammer fall, rivers of magma spilled from the icy mountains. With the second, the sky howled and lightning set the heavens aflame. With the third, a single ray of sunlight pierced the storm clouds and whispered over Truthguard's surface.\"\nSell Price:"}
MultiLanguageItemData['en'][242584] = {name = "[q6]Oathseeker", additional_info = "Binds when picked up\nUnique\n{Main Hand} {Sword}\n{2 - 5 Damage} {Speed 2.60}\n(1.3 damage per second)\n+1 Strength\n+2 Stamina\nClasses: Paladin\nRequires level 10 to 90 ( 90)\nRequires Protection Paladin\n[q]\"Killing for the sake of killing... conquering for the sake of conquest... there is no honor in such things. There is only shame and regret.\"\nSell Price:"}
MultiLanguageItemData['en'][242585] = {name = "[q6]Light's Wrath", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Two-Hand} {Staff}\n{3 - 4 Damage} {Speed 3.60}\n(1.0 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Priest\nRequires level 10 to 90 ( 90)\nRequires Discipline Priest\n[q]\"It was with our greatest hopes and prayers that we attended the ceremony that day... and it is with our greatest sorrows that we departed it.\"\nSell Price:"}
MultiLanguageItemData['en'][242586] = {name = "[q6]The Kingslayers", additional_info = "Binds when picked up\nUnique\n{Off Hand} {Dagger}\n{2 - 3 Damage} {Speed 1.80}\n(1.4 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Rogue\nRequires level 10 to 90 ( 90)\nRequiresAssassination Rogue\n[q]\"It was not a pleasant death. But it was fast, quiet, and efficient. When the orc took his last breath, the wound that killed him became irregular. Nobody would be able to tell whether he had died to a knife, an axe, or a spear.\"\nSell Price:"}
MultiLanguageItemData['en'][242587] = {name = "[q6]The Kingslayers", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Main Hand} {Dagger}\n{2 - 3 Damage} {Speed 1.80}\n(1.4 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Rogue\nRequires level 10 to 90 ( 90)\nRequiresAssassination Rogue\n[q]\"Countless voices hushed, and countless leaders toppled... all at the whim of his foul command. There would be no redemption for these acts, only solitude and sorrow.\"\nSell Price:"}
MultiLanguageItemData['en'][242588] = {name = "[q6]The Dreadblades", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Main Hand} {Sword}\n{2 - 5 Damage} {Speed 2.60}\n(1.3 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Rogue\nRequires level 10 to 90 ( 90)\nRequiresOutlaw Rogue\n[q]\"She saw herself commanding an impossibly large pirate fleet, one that could conquer the high seas and all the nations of Azeroth. Every ship that dared to challenge her burned, and every city gave up its treasures or was destroyed.\"\nSell Price:"}
MultiLanguageItemData['en'][242589] = {name = "[q6]Fury of the Stonemother", additional_info = "Binds when picked up\nUnique\n{Off Hand} {Mace}\n{3 - 4 Damage} {Speed 2.60}\n(1.3 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Shaman\nRequires level 10 to 90 ( 90)\nRequiresEnhancement Shaman\n[q]\"Created through the power of Doomhammer and the powerful shaman who wields it.\"\nSell Price:"}
MultiLanguageItemData['en'][242591] = {name = "[q6]Sharas'dal, Scepter of Tides", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Main Hand} {Mace}\n{1 - 2 Damage} {Speed 2.60}\n(0.6 damage per second)\n+8 Intellect\n+2 Stamina\nClasses: Shaman\nRequires level 10 to 90 ( 90)\nRequiresRestoration Shaman\n[q]\"They drifted into the abyss, but Azshara and her Highborne remained unbroken. The darkness around them was absolute, and so the queen willed Sharas'dal to bring them light...\"\nSell Price:"}
MultiLanguageItemData['en'][242592] = {name = "[q6]Shield of the Sea Queen", additional_info = "Binds when picked up\nUnique\n{Off Hand} {Shield}\n44 Armor\n+1 Strength\n+4 Intellect\n+2 Stamina\nClasses: Shaman\nRequires level 10 to 90 ( 90)\nRequiresRestoration Shaman\n[q]\"As the ocean crushed the life from their bodies, ancient creatures stirred in the darkness. Their whispers flowed through the currents. Their powers wrapped tight around the queen and her servants.\"\nSell Price:"}
MultiLanguageItemData['en'][242593] = {name = "[q6]The Fist of Ra-den", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Main Hand} {Fist Weapon}\n{1 - 2 Damage} {Speed 2.60}\n(0.6 damage per second)\n+8 Intellect\n+2 Stamina\nClasses: Shaman\nRequires level 10 to 90 ( 90)\nRequiresElemental Shaman\n[q]\"To seal Al'Akir's demise, Master Ra slammed his fist into the mountaintop. The heavens split wide, and all the fire and fury they contained crashed down atop the Windlord's head.\"\nSell Price:"}
MultiLanguageItemData['en'][242594] = {name = "[q6]The Highkeeper's Ward", additional_info = "Binds when picked up\nUnique\n{Off Hand} {Shield}\n44 Armor\n+1 Strength\n+4 Intellect\n+2 Stamina\nClasses: Shaman\nRequires level 10 to 90 ( 90)\nRequiresElemental Shaman\n[q]\"Ra and Helya crafted a shield, the Highkeeper's Ward, to act as a key to the Elemental Plane. It thrummed with the energies of the four elements, which Ra could call upon whenever he desired.\"\nSell Price:"}
MultiLanguageItemData['en'][242595] = {name = "[q6]Sheilun, Staff of the Mists", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Two-Hand} {Staff}\n{3 - 4 Damage} {Speed 3.60}\n(1.0 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Monk\nRequires level 10 to 90 ( 90)\nRequiresMistweaver Monk\n[q]\"You seek the calm, inevitable force of a deep river, the kind that carves canyons into the toughest stone and carries away warriors on its currents without so much as a ripple. Sheilun is the embodiment of that idea.\"\nSell Price:"}
MultiLanguageItemData['en'][242596] = {name = "[q6]Fu Zan, the Wanderer's Companion", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Two-Hand} {Staff}\n{6 - 8 Damage} {Speed 3.60}\n(1.9 damage per second)\n+3 Agility\n+4 Stamina\nClasses: Monk\nRequires level 10 to 90 ( 90)\nRequiresBrewmaster Monk\n[q]\"From the beginning, this staff has accompanied legendary creatures and immortal spirits as they carried out important, lasting work all across Azeroth.\"\nSell Price:"}
MultiLanguageItemData['en'][242597] = {name = "[q6]Fists of the Heavens", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Main Hand} {Fist Weapon}\n{3 - 5 Damage} {Speed 2.60}\n(1.5 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Monk\nRequires level 10 to 90 ( 90)\nRequiresWindwalker Monk\n[q]\"When Irmaat hefted his two weapons and tested the power within them, uncontrollable fury spilled forth.\"\nSell Price:"}
MultiLanguageItemData['en'][242598] = {name = "[q6]Scepter of Sargeras", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Two-Hand} {Staff}\n{3 - 4 Damage} {Speed 3.60}\n(1.0 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Warlock\nRequires level 10 to 90 ( 90)\nRequiresDestruction Warlock\n[q]\"When at last the moment arrived for Ner'zhul to act, he did so with wild abandon, heedless of the consequences. It mattered not to him if Draenor was destroyed; in fact, he welcomed it as part of his legacy.\"\nSell Price:"}
MultiLanguageItemData['en'][242599] = {name = "[q6]Ulthalesh, the Deadwind Harvester", additional_info = "Legion Remix\nBinds when picked up\nUnique\n{Two-Hand} {Staff}\n{3 - 4 Damage} {Speed 3.60}\n(1.0 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Warlock\nRequires level 10 to 90 ( 90)\nRequiresAffliction Warlock\n[q]\"The scythe's master will either overcome Sataiel or be consumed, which will only make the blade more powerful. And then another bearer will take their place. And another.\"\nSell Price:"}
MultiLanguageItemData['en'][242600] = {name = "[q6]Skull of the Man'ari", additional_info = "Legion Remix\nBinds when picked up\nUnique\nHeld In Off-hand\n+4 Intellect\n+2 Stamina\nClasses: Warlock\nRequires level 10 to 90 ( 90)\nRequiresDemonology Warlock\n[q]\"When finally Thal'kiel emerged, he was changed. He had aged by centuries, alone in the dark with his thoughts and his thralls. His back was twisted and stooped, and there was an odd glimmer in his eye. He summoned his Wakeners, and we answered the call...\"\nSell Price:"}
MultiLanguageItemData['en'][242601] = {name = "[q6]Fists of the Heavens", additional_info = "Binds when picked up\nUnique\n{Off Hand} {Fist Weapon}\n{3 - 5 Damage} {Speed 2.60}\n(1.5 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Monk\nRequires level 10 to 90 ( 90)\nRequiresWindwalker Monk\n[q]\"There was a great flash of light and a great rush of air, and when it was done, Irmaat could feel his weapons, Al'burq and Alra'ed trembling with elemental power.\"\nSell Price:"}
MultiLanguageItemData['en'][242602] = {name = "[q6]Secrets of the Void", additional_info = "Binds when picked up\nHeld In Off-hand\n+4 Intellect\n+2 Stamina\nClasses: Priest\nRequires level 10 to 90 ( 90)\nRequires Shadow Priest\n[q]\"The moment I touched the blade, a name was spoken in my mind: Xal'atath. I knew then that I could not destroy the dagger. Not yet. How can one defeat a power she does not understand?\"\nSell Price:"}
MultiLanguageItemData['en'][242603] = {name = "[q6]Heart of the Phoenix", additional_info = "Binds when picked up\nHeld In Off-hand\n+4 Intellect\n+2 Stamina\nClasses: Mage\nRequires level 10 to 90 ( 90)\nRequiresFire Mage\n[q]\"When the fighting was done, Dath'Remar stood painted in demon blood. As night fell, we knew that more battles remained, and yet, with this elf and this blade among us, we held out hope that victory did not lie beyond our grasp.\"\nSell Price:"}
MultiLanguageItemData['en'][242604] = {name = "[q6]The Dreadblades", additional_info = "Binds when picked up\nUnique\n{Off Hand} {Sword}\n{2 - 5 Damage} {Speed 2.60}\n(1.3 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Rogue\nRequires level 10 to 90 ( 90)\nRequiresOutlaw Rogue\n[q]\"No blade can shed the blood of so many innocents and not demand a toll on its wielder as well. They are no treasure.\"\nSell Price:"}
MultiLanguageItemData['en'][242605] = {name = "[q6]Spine of Thal'kiel", additional_info = "Binds when picked up\nUnique\n{Main Hand} {Dagger}\n{1 - 2 Damage} {Speed 1.80}\n(0.8 damage per second)\n+8 Intellect\n+2 Stamina\nClasses: Warlock\nRequires level 10 to 90 ( 90)\nRequiresDemonology Warlock\n[q]\"The Wakeners' screams echoed across Argus, as a grim reminder of the price paid for dealing with demons.\"\nSell Price:"}
