MultiLanguageItemData['en'][242713] = {name = "[q4]Resplendent K'arroc", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"A technological marvel in the flesh, this K'arroc represents hope for a brighter K'aresh.\"\nWorld Quest:\nThe Hope of K'aresh\nZone:\nK'aresh"}
MultiLanguageItemData['en'][242714] = {name = "[q4]Umbral K'arroc", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"A savage K'arroc particularly well-suited to prowling the perpetual twilight of K'aresh.\"\nAchievement:\nGlory of the Omega Raider\nCategory:\nDungeons & Raids"}
MultiLanguageItemData['en'][242715] = {name = "[q4]K'arroc Swiftwing", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"A gift for services rendered, this K'arroc has seen its share of hazardous flights.\"\nQuest:\nOff to Tazavesh, Again\nZone:\nK'aresh"}
MultiLanguageItemData['en'][242717] = {name = "[q4]Lavender K'arroc", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"This particularly belligerent K'arroc's previous master died while investigating Untethered Space. Perhaps it will accept you instead... or maybe not.\"\nVendor:\nShad'anis\nZone:\nK'aresh\nCost:\n10"}
