MultiLanguageItemData['en'][242728] = {name = "[q4]The Bone Freezer", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Bitter rival to The Bone Melter, this creeper was ousted from their lair near Manaforge Omega after a crushing defeat. It now seeks to learn from the one that dethroned its greatest foe.\"\nFaction:\nManaforge Vandals\nRenown:\n14\nLocation:\nShadow Point"}
MultiLanguageItemData['en'][242729] = {name = "[q4]Ruby Void Creeper", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Renown Rank 15 with the K'aresh Trust.\n\n\n[q]\"Rescued\" by the K'aresh Trust for study, this void creeper has turned out to be an incredibly sturdy mount.\nVendor:\nOm'sirik\nZone:\nK'aresh\nCost:\n8125"}
