MultiLanguageItemData['en'][243031] = {name = "[q2]Mrrmgmrl Grmmlmglrg", additional_info = "Frost Relic\nBinds when picked up\n[q2]Equip: Grants 1 additional rank of Terror From Below .\n\n Terror From Below\nYour abilities periodically draw the attention of a behemoth from the deep that seeks your enemy, inflicting [(440% Attack/Spell Power)] Nature damage split evenly between all enemies nearby.\n\n When Terror From Below strikes a Fel Touched enemy it causes Deepsurge Crash , damaging all nearby enemies for [(440% Attack/Spell Power)] nature damage.\nRequires level 10 to 90 ( 90)"}
MultiLanguageItemData['en'][243032] = {name = "[q2]Flawed Rage of the Tides", additional_info = "Binds when picked up\n[q2]Equip: Grants 1 additional rank of Touch of Malice .\n\n Touch of Malice\nYour and your minions' damaging spells and abilities periodically apply Fel Touched to enemies. The infernal dreadlord summoned by Twisted Crusade always critically strikes Fel Touched enemies.\n\n\nFel Touched\n Every 4 seconds, the targets bursts, damaging nearby enemies for 3% of damage taken over the last 4 seconds.\n\n Damage reduced beyond 5 targets.\nRequires level 10 to 90 ( 90)"}
MultiLanguageItemData['en'][243033] = {name = "[q2]Flawed Sundered Comet", additional_info = "Binds when picked up\n[q2]Equip: Grants 1 additional rank of Terror From Below .\n\n Terror From Below\nYour abilities periodically draw the attention of a behemoth from the deep that seeks your enemy, inflicting [(440% Attack/Spell Power)] Nature damage split evenly between all enemies nearby.\n\n When Terror From Below strikes a Fel Touched enemy it causes Deepsurge Crash , damaging all nearby enemies for [(440% Attack/Spell Power)] nature damage.\nRequires level 10 to 90 ( 90)"}
MultiLanguageItemData['en'][243034] = {name = "[q2]Flawed Gelmogg's Fractured Skull", additional_info = "Binds when picked up\n[q2]Equip: Grants 1 additional rank of Highmountain Fortitude .\n\n Highmountain Fortitude\nOnce every 12 sec, you begin accumulating 3% of all damage taken as Fortitude . After 8 sec, Fortitude becomes a protective barrier, absorbing the amount accumulated for 4 sec.\nRequires level 10 to 90 ( 90)"}
MultiLanguageItemData['en'][243035] = {name = "[q2]Flawed Ettin Bone Fragment", additional_info = "Binds when picked up\n[q2]Equip: Grants 1 additional rank of Souls of the Caw .\n\n Souls of the Caw\nYour spells and abilities have a chance to summon a flock of spirit eagles that dive bomb nearby enemies, exploding on impact to heal allies and inflict [[2 * (368% Attack/Spell Power)]][[(368% Attack/Spell Power)]] Nature damage to enemies within 5 yards.\nRequires level 10 to 90 ( 90)"}
MultiLanguageItemData['en'][243036] = {name = "[q2]Flawed Gleaming Iron Spike", additional_info = "Binds when picked up\n[q2]Equip: Grants 1 additional rank of Arcane Aegis .\n\n Arcane Aegis\nWhile moving backward, you channel an Arcane Aegis , absorbing up to [(2100% Attack/Spell Power)] damage but reducing your movement speed by 80%. While not channeling Arcane Aegis , it regenerates at 5% per second. If the Arcane Aegis is shattered, it becomes unusable for 30 sec.\nRequires level 10 to 90 ( 90)"}
MultiLanguageItemData['en'][243037] = {name = "[q2]Flawed Xakal's Determination", additional_info = "Binds when picked up\n[q2]Equip: Grants 1 additional rank of Temporal Retaliation .\n\n Temporal Retaliation\nWhen you absorb damage, inflict [(31% Attack/Spell Power)] Arcane damage back to the attacker and reduce their attack speed by 20% for 3 sec.\nRequires level 10 to 90 ( 90)"}
