MultiLanguageItemData['en'][246071] = {name = "[q4]Mana-Seamster's Arcane-Needle", additional_info = "Binds when picked up\n{Two-Hand} {Staff}\n{25 - 34 Damage} {Speed 3.60}\n(8.2 damage per second)\n+98 Intellect\n+99 Stamina\n[q2]+ 29 Critical Strike\n[q2]+ 15 Versatility\nDurability 120 / 120\n[q2]Equip: Your spells have a chance to grant you a stack of Ether-Plate up to 5.\n\n The next time you would take direct targeted damage, consume an Ether-Plate and reduce that instance of damage by 50% up to 657 .\nSell Price:"}
MultiLanguageItemData['en'][246072] = {name = "[q3]Intricate Everchill Pearl", additional_info = "Binds when picked up\n[q2]Equip: Grants 2 additional ranks of Volatile Magics .\n\n Volatile Magics\nYour critical strikes have a chance to create a burst of magic, inflicting [(342% Attack/Spell Power)] Arcane damage to enemies within 6 yards of your target.\n\nNaran's Everdisc now always critically strikes Fel Touched enemies.\nRequires level 10 to 90 ( 90)"}
MultiLanguageItemData['en'][246073] = {name = "[q3]Intricate Rage of the Tides", additional_info = "Binds when picked up\n[q2]Equip: Grants 2 additional ranks of Touch of Malice .\n\n Touch of Malice\nYour and your minions' damaging spells and abilities periodically apply Fel Touched to enemies. The infernal dreadlord summoned by Twisted Crusade always critically strikes Fel Touched enemies.\n\n\nFel Touched\n Every 4 seconds, the targets bursts, damaging nearby enemies for 3% of damage taken over the last 4 seconds.\n\n Damage reduced beyond 5 targets.\nRequires level 10 to 90 ( 90)"}
MultiLanguageItemData['en'][246074] = {name = "[q3]Intricate Sundered Comet", additional_info = "Binds when picked up\n[q2]Equip: Grants 2 additional ranks of Terror From Below .\n\n Terror From Below\nYour abilities periodically draw the attention of a behemoth from the deep that seeks your enemy, inflicting [(440% Attack/Spell Power)] Nature damage split evenly between all enemies nearby.\n\n When Terror From Below strikes a Fel Touched enemy it causes Deepsurge Crash , damaging all nearby enemies for [(440% Attack/Spell Power)] nature damage.\nRequires level 10 to 90 ( 90)"}
MultiLanguageItemData['en'][246075] = {name = "[q3]Intricate Gelmogg's Fractured Skull", additional_info = "Binds when picked up\n[q2]Equip: Grants 2 additional ranks of Highmountain Fortitude .\n\n Highmountain Fortitude\nOnce every 12 sec, you begin accumulating 3% of all damage taken as Fortitude . After 8 sec, Fortitude becomes a protective barrier, absorbing the amount accumulated for 4 sec.\nRequires level 10 to 90 ( 90)"}
MultiLanguageItemData['en'][246076] = {name = "[q3]Intricate Ettin Bone Fragment", additional_info = "Binds when picked up\n[q2]Equip: Grants 2 additional ranks of Souls of the Caw .\n\n Souls of the Caw\nYour spells and abilities have a chance to summon a flock of spirit eagles that dive bomb nearby enemies, exploding on impact to heal allies and inflict [[2 * (368% Attack/Spell Power)]][[(368% Attack/Spell Power)]] Nature damage to enemies within 5 yards.\nRequires level 10 to 90 ( 90)"}
MultiLanguageItemData['en'][246077] = {name = "[q3]Intricate Gleaming Iron Spike", additional_info = "Binds when picked up\n[q2]Equip: Grants 2 additional ranks of Arcane Aegis .\n\n Arcane Aegis\nWhile moving backward, you channel an Arcane Aegis , absorbing up to [(2100% Attack/Spell Power)] damage but reducing your movement speed by 80%. While not channeling Arcane Aegis , it regenerates at 5% per second. If the Arcane Aegis is shattered, it becomes unusable for 30 sec.\nRequires level 10 to 90 ( 90)"}
MultiLanguageItemData['en'][246079] = {name = "[q4]Pristine Everchill Pearl", additional_info = "Binds when picked up\nRequires level 10 to 90 ( 90)"}
MultiLanguageItemData['en'][246080] = {name = "[q4]Pristine Rage of the Tides", additional_info = "Binds when picked up\n[q2]Equip: Grants 3 additional ranks of Touch of Malice .\n\n Touch of Malice\nYour and your minions' damaging spells and abilities periodically apply Fel Touched to enemies. The infernal dreadlord summoned by Twisted Crusade always critically strikes Fel Touched enemies.\n\n\nFel Touched\n Every 4 seconds, the targets bursts, damaging nearby enemies for 3% of damage taken over the last 4 seconds.\n\n Damage reduced beyond 5 targets.\nRequires level 10 to 90 ( 90)"}
