MultiLanguageItemData['en'][246732] = {name = "[q4]Void-Forged Overseer", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"After the Sepulcher of the First Ones was opened, this construct of the First Ones was stolen by the brokers and sold to the ethereals in a transaction at the Veiled Market. Under the ethereals' ingenious modifications, it integrated the mysteries of the Aether, gliding through the air with extraordinary elegance, leaving behind a trail of shimmering stardust.\"\nPromotion"}
MultiLanguageItemData['en'][246734] = {name = "[q4]Fierce Grimlynx", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Renown Rank 16 with the Hara'ti.\n\n\n[q]\"This grimlynx has seen many battles against the creatures in the Rift of Aln.\"\nVendor:\nNaynar\nZone:\nHarandar\nCost:\n6000"}
MultiLanguageItemData['en'][246735] = {name = "[q4]Rootstalker Grimlynx", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"With fur to match the deep roots and armor to match the vast foliage, these Grimlynx are equipped to be some of the ultimate hunters of Harandar.\"\nDrop:\nHarandar Rare Creatures"}
MultiLanguageItemData['en'][246736] = {name = "[q4]Ivory Grimlynx", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Ivory grimlynxes have a strong independent streak. It takes an especially brave Haranir to ride them.\"\nAchievement:\nAllied Race: Haranir\nCategory:\nMidnight"}
