MultiLanguageItemData['en'][246904] = {name = "[q3]Unseen Path of the Phase Stalker", additional_info = "Binds when picked up\n[q2]Use: Summons a rideable phase-lost warp stalker in K'aresh. This is a very, VERY fast mount. (2 Min Cooldown)\n[q]\"Navigate the sands of K'aresh as the Wastelanders have learned.\""}
MultiLanguageItemData['en'][246905] = {name = "[q3]Overtuned K'areshi Goggles", additional_info = "Binds when picked up\nToy\n[q2]Use: View the world through K'areshi sensibilities. (30 Min Cooldown)\n[q]\"Beauty is ethereal. Always.\""}
MultiLanguageItemData['en'][246907] = {name = "[q3]Broker Supply Crate", additional_info = "Binds when picked up\nToy\n[q2]Use: Carry your crate full of Tazaveshi supplies and knick-knacks. (10 Sec Cooldown)"}
MultiLanguageItemData['en'][246908] = {name = "[q3]K'areshi Supply Crate", additional_info = "Binds when picked up\nToy\n[q2]Use: Carry your crate full of K'areshi supplies and doodads. (10 Sec Cooldown)"}
MultiLanguageItemData['en'][246910] = {name = "Vintage Vintage", additional_info = "Quest Item\n[q]\"Elrendar Reserve, 25.\""}
MultiLanguageItemData['en'][246911] = {name = "Discarded Wand", additional_info = "Quest Item\n[q]\"A plain, dormant wand. A note is attached to its handle: \"DEEMED UNSUITABLE. RECYCLE.\"\""}
MultiLanguageItemData['en'][246912] = {name = "Unstable Arcana", additional_info = "Quest Item\n[q]\"The glass vial pulses with shifting arcane energy, unpredictable and uncontrollable.\""}
MultiLanguageItemData['en'][246913] = {name = "Magical Mango", additional_info = "Quest Item\n[q]\"Likely pilfered from a Magister's party table.\""}
MultiLanguageItemData['en'][246914] = {name = "Perfectly Fine Grain", additional_info = "Quest Item\n[q]\"Triple inspected, this grain is surely safe to handle and consume.\""}
MultiLanguageItemData['en'][246915] = {name = "[q4]Arsenal: Ethereal Weaponry", additional_info = "Binds when picked up\n[q2]Use: Collect the appearances of the Ethereal Weaponry weapon set."}
MultiLanguageItemData['en'][246917] = {name = "[q4]Thunder-Ridged Elekk", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"Even infusion with demonic magics could not break the spirits of these majestic beasts, and their twisted forms were never integrated into the Legion's service.\"\nTrading Post"}
MultiLanguageItemData['en'][246919] = {name = "[q4]Cinder-Seared Elekk", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"The Burning Legion sought to destroy, steal or corrupt anything that brought joy to the draenei, and the elekks of Draneor were no exception.\"\nTrading Post"}
MultiLanguageItemData['en'][246920] = {name = "[q4]Void-Razed Elekk", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"Their temperament is as wild as the twisted forces that warped their creation and they only serve who they choose.\"\nTrading Post"}
MultiLanguageItemData['en'][246921] = {name = "[q4]Legion-Forged Elekk", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"The Burning Legion envied the draenei's bond with the elekks of Draenor. Many demonic beast-masters warped the breed to serve their needs, but none could control them.\"\nTrading Post"}
MultiLanguageItemData['en'][246923] = {name = "Frillfish Fillet", additional_info = "Quest Item\n[q]\"Prized for its tender texture, the fillet has wave-like marbling and a subtly briny flavor.\""}
MultiLanguageItemData['en'][246924] = {name = "Root Drift Jelly", additional_info = "Quest Item\n[q]\"Sweet and shimmering, it is rumored to tingle on the tongue and glow faintly in the dark.\""}
MultiLanguageItemData['en'][246926] = {name = "Nutrient-Rich Soil", additional_info = "Quest Item\n[q]\"Soil packed in nutrients needed for a growing rutaani. A meal replacement for those not inclined to consuming solids.\""}
MultiLanguageItemData['en'][246936] = {name = "[q4]Resonant Epoch Memento", additional_info = "Binds when picked up\n[q2]Use: Fuse this Epoch Memento with your artifact weapon, creating a ripple across all timelines and versions of \"you\".\n\n This powerful relic resonates with your Warband, permanently increasing all experience gains in Legion Remix by 1%.\nRequires level 10 to 90 ( 90)\n[q]\"A tiny piece of an epoch story.\""}
MultiLanguageItemData['en'][246937] = {name = "[q5]Perfected Epoch Memento", additional_info = "Binds when picked up\n[q2]Use: Fuse this Epoch Memento with your artifact weapon, creating a ripple across all timelines and versions of \"you\".\n\n This perfect relic resonates with your Warband, permanently increasing all experience gains in Legion Remix by 10%.\nRequires level 10 to 90 ( 90)\n[q]\"A crucial piece of an epoch story.\""}
MultiLanguageItemData['en'][246939] = {name = "[q2]Essence-Hunter's Eyeglass", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 [Agility or Intellect]\n[q2]Equip: Your harmful spells and ranged abilities critical strikes have a high chance to grant you Arcane Hunter up to 5 times, increasing your Critical Strike rating by 7 per stack for 8 sec.\nSell Price:"}
MultiLanguageItemData['en'][246940] = {name = "[q2]Manaforged Aethercell", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 Intellect\n[q2]Equip: Your healing abilities have a chance to power the Aethercell increasing your Mastery by 116 , decreasing by ( 116 / 15) each sec. Lasts 15 sec.\nSell Price:"}
MultiLanguageItemData['en'][246941] = {name = "[q2]Symbiotic Ethergauze", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+44 Stamina\n[q2]Equip: Blocking, parrying, or dodging has a chance to awaken the Gauze causing it to lash out dealing 1746 Arcane damage split between nearby enemies while shielding you for 10113 damage for 15 sec.\nSell Price:"}
MultiLanguageItemData['en'][246942] = {name = "Corpse Rind", additional_info = "Quest Item\n[q]\"Freshly slain, the plant-based flesh still shines with a moist glow.\""}
MultiLanguageItemData['en'][246944] = {name = "[q2]Mind-Fracturing Odium", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 [Agility or Strength]\n[q2]Equip: Your harmful abilities may cause your mind to tear piece by piece. At the tenth tear, you succumb to Arcane Insanity granting you 55 Haste while periodically recovering your sanity over time.\n\n Slaying an enemy or witnessing an ally's death instantly tears at your sanity.\n[q]\"Were there always this many tentacles around here?\"\nSell Price:"}
MultiLanguageItemData['en'][246945] = {name = "[q2]Incorporeal Essence-Gorger", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 [Agility or Strength or Intellect]\n[q2]Use: Rip magical essence out of your target and consume it dealing ( 833 * 1 ) Arcane damage while granting you 120 of your lowest secondary stat for 20 sec.\n\n If the target was an Ethereal, your highest secondary stat is increased instead. (2 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][246947] = {name = "[q2]Twisted Mana Sprite", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 28 Versatility\n[q2]Equip: Your healing spell and abilities have a very high chance to summon a Twisted Mana Sprite to assist you in combat for 10 sec. Twisted Mana Sprite periodically heal a random nearby ally for ( 629 * 1 ). Overhealing is converted into an absorb shield for 5 sec.\nSell Price:"}
