MultiLanguageItemData['en'][247720] = {name = "[q4]The Headless Horseman's Chilling Charger", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Through the air you will fly, on your foes you descend, this charger will carry you to deliver their end.\"\nTrading Post"}
MultiLanguageItemData['en'][247721] = {name = "[q4]The Headless Horseman's Ghoulish Charger", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Tricks have been played, your enemies beaten, this ghoulish charger awaits a treat, friend.\"\nDrop:\nLoot-Filled Pumpkin\nHoliday:\nHallow's End"}
