MultiLanguageItemData['en'][247791] = {name = "[q4]Adorned Northeron Gryphon", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"The elder gryphon riders and high shamans of the Northeron Wildhammer often adorned their gryphons in ornate, feather-clad pieces, indicating their rank and status.\"\nTrading Post"}
MultiLanguageItemData['en'][247792] = {name = "[q4]High Shaman's Aerie Gryphon", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"The ancient Wildhammer shamans who first encountered gryphons believed them to be elemental spirits in mortal form. This encounter would forever imprint on the Wildhammer clan for generations to come.\"\nTrading Post"}
MultiLanguageItemData['en'][247793] = {name = "[q4]Cinder-Plumed Highland Gryphon", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"According to Wildhammer legend, the orange plumage found on gryphons is believed to be a hereditary trait passed down from their elemental ancestry.\"\nTrading Post"}
MultiLanguageItemData['en'][247794] = {name = "[q4]Emberwing Sky Guide", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"From the foothills of Khaz Modan, we followed its ember-lit wings--a northbound torch across the dark summer sky.\" - The Pilgrimage of the First Wildsage\nTrading Post"}
MultiLanguageItemData['en'][247795] = {name = "[q4]Ornery Breezestrider", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses your Ornery Breezestrider.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"This talbuk is a stubborn, obstinate mount, even after getting to know its rider. Riders beware.\"\nTrading Post"}
MultiLanguageItemData['en'][247808] = {name = "[q6]Bronze Simulacrum", additional_info = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires level 10 to 90 ( 90)\n[q]\"An artifact forgery flawlessly fabricated by Momentus. Now that you have reclaimed this copy, you can scrap it for the bronze it's made of.\""}
