MultiLanguageItemData['en'][248088] = {name = "[q4]Jade, Bright Foreseer", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"The presence of this majestic Pandaren rabbit spirit brings joy and happiness and is heralded as a wonderful omen. Legend says that in its eyes, you can glimpse the greatest happiness of your life, even if it is yet to come.\"\nIn-Game Shop"}
MultiLanguageItemData['en'][248089] = {name = "[q4]Tangled Dreamweaver", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"The last of the sleepers are finally awakening, bringing the dreams of the dragons back to the lands.\"\nPromotion:\nDragonflight Heroic Edition"}
