MultiLanguageItemData['en'][248135] = {name = "[q3]B1P, Scorcher of Souls", additional_info = "Optional Crafting Reagent\n[q2]+15 Recipe Difficulty\n[q2]Provides the following property: Summons Bip, Scorcher of Souls to spray soul sparks on your enemies dealing ( 846 * (12)) Fire damage in a cone in front of you for 6 sec.\nUsable with: Midnight Engineering Crafted Equipment \"Summons Bip, Soul Scorcher. Created by players with the Engineering skill. Can be bought and sold on the Auction House.\"\nSell Price:"}
MultiLanguageItemData['en'][248136] = {name = "[q3]M3DDY, Travel-Sized", additional_info = "Optional Crafting Reagent\n\n[q2]Provides the following property:\n\n A pocket-sized version of your buddy Meddy that will revive you upon your untimely demise while outdoors.\n[q]Usable with: Midnight recipes for most unembellished equipment.\nSell Price:"}
MultiLanguageItemData['en'][248137] = {name = "[q3]M3DDY", additional_info = "[q2]Use: Upon your untimely demise, summon Meddy to... medicalize you and your raid back to life!\n\n Does not work on players whose spirits have been released and are above level 90.\nSell Price:"}
MultiLanguageItemData['en'][248138] = {name = "[q2]Curious Red Button", additional_info = "[q2]Use: Deploy a particularly curious device.\n\n Lasts for 10 min. Must be deployed prior to combat. Only usable outdoors. (10 Min Cooldown)\nSell Price:"}
