MultiLanguageItemData['en'][248592] = {name = "[q3]B1P, Scorcher of Souls", additional_info = "Optional Crafting Reagent\n[q2]+5 Recipe Difficulty\n[q2]Provides the following property: Summons Bip, Scorcher of Souls to spray soul sparks on your enemies dealing ( 846 * (12)) Fire damage in a cone in front of you for 6 sec.\nUsable with: Midnight Engineering Crafted Equipment \"Summons B1P, Scorcher of Souls. Created by players with the Engineering skill. Can be bought and sold on the Auction House.\"\nSell Price:"}
MultiLanguageItemData['en'][248593] = {name = "Nascent Blade", additional_info = "Quest Item\n[q2]Use: Quench the blade in the essence of dead creatures near you. (3 Sec Cooldown)\n[q]\"The blade churns with conflicting energy--the spark of Light trembling against the torrent of Void. Its chaos emanates bloodlust.\""}
MultiLanguageItemData['en'][248608] = {name = "Blackrock Bulletin Message", additional_info = "Quest Item\n[q]\"Nagosh, it's time we teach the lesser races to fear the Dark Horde once more. Have your forces ready to strike Redridge by the end of the month. Warlord Grazla\""}
MultiLanguageItemData['en'][248610] = {name = "Blackrock Bulletin Message", additional_info = "Quest Item\n[q]\"83 days since anyone fell in the lava. Keep it that way!\""}
MultiLanguageItemData['en'][248611] = {name = "Blackrock Bulletin Message", additional_info = "Quest Item\n[q]\"We have a big operation coming up soon! If I'm not yelling orders at you, and you aren't bleeding, you should always be training. Stop reading and get to it! - Nagosh\""}
MultiLanguageItemData['en'][248612] = {name = "Blackrock Bulletin Message", additional_info = "Quest Item\n[q]\"I've heard some of you are mad you didn't get a badge. If anyone thinks I was wrong, challenge me directly. Win, you get a badge. Lose and you won't have any more complaints. -Nagosh\""}
MultiLanguageItemData['en'][248614] = {name = "Quel'dorei Artifact", additional_info = "Quest Item\n[q]\"An arcane relic used by Magisters to amplify long-distance communication and scrying.\""}
