MultiLanguageItemData['en'][250192] = {name = "[q4]Reins of the Ghastly Ur'zul", additional_info = "Legion Remix\nBinds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount. This is a flying mount.\n[q2]Summons and dismisses your Ghastly Ur'zul.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\nSell Price:\n[q]\"A ravenous breed of demon, the ghastly ur'zul tears through withered flesh and bone the way one would graze a salad.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250214] = {name = "[q3]Lightspire Core", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Intellect]\n[q2]Equip: You are embraced by the Light, increasing Mastery by 20 .\n\n Your damaging spells and abilities can call a beam of radiant light nearby. Standing in the light blesses you with 35 Mastery while you stand in it.\n[q]\"Stand in the Light, and be made whole.\"\nSell Price:"}
MultiLanguageItemData['en'][250215] = {name = "[q3]Freightrunner's Flask", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Intellect]\n[q2]Use: Take a sip of the drink you swiped from the freight, increasing your Critical Strike by 52 for 15 sec. (1 Min, 30 Sec Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][250223] = {name = "[q3]Soulcatcher's Charm", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Intellect\n[q2]Equip: Your damaging spells have a chance to haunt the target, dealing ( 180 * 12) Shadow damage over 12 sec.\n\n If the target dies while haunted, the effect transfers to a nearby enemy, inflicting 150% of the Shadow damage over the remaining duration.\n[q]\"Vordaza's necromantic fetish is covered in inscrutable carvings and has a heavy, ominous aura.\"\nSell Price:"}
MultiLanguageItemData['en'][250224] = {name = "[q3]Mindpiercer's Sigil", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]Equip: Your damaging spells have a chance to stir the Void near your target, erupting for 2491 Shadow damage split among nearby enemies. You siphon energy from the Void, gaining 52 Intellect for 10 sec.\nSell Price:"}
MultiLanguageItemData['en'][250225] = {name = "[q3]Void Execution Mandate", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Agility\n[q2]Use: Mark your target for execution, increasing your Haste by 59 for 20 sec. While the target is marked, each of your attacks against them grants an additional 4 Critical Strike, as the Void urges you to finish the kill, up to a maximum of ( 4 * 15) Critical Strike. (2 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][250226] = {name = "[q3]Latch's Crooked Hook", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\n[q2]Use: Hurl a massive hook toward your target, cleaving through enemies in its path and dealing ( 1 * 577 ) Physical damage to each. When the hook crashes into the target, it inflicts ( 1 * 385 ) Physical damage split among enemies within 7 yards. (1 Min, 30 Sec Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][250227] = {name = "[q3]Kroluk's Warbanner", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\n[q2]Equip: Your melee attacks have a chance to summon an elite Axethrower who hurls an axe at your target, inflicting ( 1 * 3676 ) Physical damage.\nSell Price:"}
MultiLanguageItemData['en'][250228] = {name = "[q3]Resonant Bellowstone", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\n[q2]Equip: Your damaging abilities have a chance to echo with Xathuux's furious roar, increasing Critical Strike by 33 for 30 sec.\n\n During this time, each of your attacks increases your Critical Strike by an additional 5 , stacking up to a maximum of 5 times. (30s cooldown)\nSell Price:"}
MultiLanguageItemData['en'][250229] = {name = "[q3]Idol of the War Loa", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 10 Critical Strike\n[q2]Equip: You have proven your worth to Nalorakk. Your abilities have a chance to echo with the war god's furious roar, granting you 49 Strength for 15 sec.\n\n Nearby allies with Nalorakk's favor are rallied, gaining 25% movement speed for 10 sec.\nSell Price:"}
