MultiLanguageItemData['en'][250241] = {name = "[q3]Mark of Light", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Strength\n[q2]Equip: Your attacks have a chance to unleash a Radiant Strike at your target, dealing ( 816 * 1 ) Holy damage split among nearby enemies.\nSell Price:"}
MultiLanguageItemData['en'][250242] = {name = "[q3]Jelly Replicator", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\n[q2]Equip: Taking damage has a chance to form a jelly shield for 10 sec, absorbing 40% of incoming damage, up to 4952 .\n\nIf your health falls below 35%, the jelly instinctively thickens around you for 5 sec, absorbing up to 2147 damage. This effect can only activate once every 1 min.\nSell Price:"}
MultiLanguageItemData['en'][250243] = {name = "[q3]Manaheart's Binding Flame", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\n[q2]Use: Form a Fel Shield for 10 sec, absorbing 30% of incoming damage, up to 1907 . While the shield holds, a portion of the absorbed damage is stored as volatile Fel energy.\n\n When the shield expires or breaks, the energy erupts and inflicts Fire damage to split between nearby enemies. (1 Min, 30 Sec Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][250244] = {name = "[q3]Permafrost Essence", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]Equip: You gain Nalorakk's Favor of Enduring. Taking damage has a chance to grant a Mark of Frost, increasing your Critical Strike by 36 for 15 sec. Stacks up to 10 times.\n\n If your health falls below 25%, the reservoir ruptures, consuming all marks to form a Frost Barrier that absorbs 4567 damage per mark for 10 sec.\nSell Price:"}
MultiLanguageItemData['en'][250245] = {name = "[q3]Tumor of the Swarm", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\n[q2]Equip: Your attacks have a chance to release toxic parasites that burst around you, dealing 964 Nature damage split among nearby enemies and healing you for 607 .\nSell Price:"}
MultiLanguageItemData['en'][250246] = {name = "[q3]Refueling Orb", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Intellect\n[q2]Equip: Your spells and abilities have a chance to release an energy orb that bounces between up to 5 nearby allies, increasing their Versatility by 13 for 12 sec. If an ally is below 50% health, the orb heals them for 514 instead.\nSell Price:"}
MultiLanguageItemData['en'][250247] = {name = "[q4]Amulet of the Abyssal Hymn", additional_info = "Binds when picked up\nNeck\n+8 Stamina\n[q2]+ 4 Haste\n[q2]+ 22 Mastery\n\n[q0]Prismatic Socket\nSell Price:"}
MultiLanguageItemData['en'][250248] = {name = "[q3]Mycolic Medicine", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Intellect\n[q2]Equip: You gain Nalorakk's Favor of Growth. Your healing spells and abilities have a chance to instantly heal your target for 1821 and spawn a glowing mushroom near them that lasts for 10 sec.\n\n If an ally steps on and consumes the mushroom, they are healed for an additional 1041 .\n[q]\"A draught from a species long lost everywhere but in dreams.\"\nSell Price:"}
MultiLanguageItemData['en'][250253] = {name = "[q3]Whisper of the Duskwraith", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Intellect\n[q2]Equip: Your healing spells and abilities have a chance to release a spirit of the Duskwraith, leaping to your target and healing them for 1795 .\n\n If the target's health is below 40%, the spirit empowers them further, granting 18 Versatility for 10 sec.\nSell Price:"}
MultiLanguageItemData['en'][250254] = {name = "[q3]Seed of Radiant Hope", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Intellect\n[q2]Use: Surround your target ally with Lightblossoms, healing them for [ 870 * (8)] over 12 sec.\n\n If their health falls below 50%, the Lightblossoms fully bloom in radiant light, instantly healing them for 1225 . (1 Min, 30 Sec Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][250255] = {name = "[q3]Unstable Felheart Crystal", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Intellect\n[q2]Use: Unleash the fel energy stored within the crystal, sacrificing 824 of your health to infuse a target ally for 10 sec, absorbing 2178 damage. (2 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][250256] = {name = "[q3]Heart of Wind", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength or Intellect]\n[q2]Equip: Your spells and abilities have a chance to awaken the Heart of Wind, surrounding you with strong gales that increase your Haste by 56 for 10 sec.\nSell Price:"}
MultiLanguageItemData['en'][250257] = {name = "[q3]Eye of the Drowning Void", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Intellect]\n[q2]Equip: Your damaging spells and abilities have a chance to tear open a rift of the Void within your target, erupting for ( 1 * 1242 ) Shadow damage split among nearby enemies.\nSell Price:"}
MultiLanguageItemData['en'][250258] = {name = "[q3]Vessel of Tortured Souls", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 10 Mastery\n[q2]Equip: Your spells and abilities have a chance to awaken a soul within the vessel. Each soul you collect increases your Primary Stat by 9 for 1 min.\n[q]\"Don't tap the glass. They don't like that.\"\nSell Price:"}
