MultiLanguageItemData['en'][250423] = {name = "[q4]Reins of the Slag Basilisk", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Originally dwelling deep underground where their diet consisted of obsidian and basalt, the slag basilisks surfaced when their homes were disturbed by the Legion.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250424] = {name = "[q4]Reins of the Leystone Basilisk", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"This beautiful basilisk is often hunted for the magical properties of its organs. Fortunately for the basilisk, its connection to ley lines gives it a prescient sense of approaching predators.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250425] = {name = "[q4]Reins of the Felslate Basilisk", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Once common on the Broken Isles, felslate basilisks have been hunted heavily by miners seeking their precious skins.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250426] = {name = "[q4]Reins of the Aquamarine Basilisk", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Despite their name, aquamarine basilisks feast on a variety of coastal crystals and oceanic rocks.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250427] = {name = "[q4]Reins of the Illidari Blightstalker", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"These demons devour plague and relish in decay. Who thought it would be a good idea to ride them?\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250428] = {name = "[q4]Reins of the Illidari Dreadstalker", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Despite their taste for flesh and unnatural ability to smell fear, these lesser demons have been dominated by the Illidari as one would tame a hunting companion.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250429] = {name = "[q4]Reins of the Highland Elderhorn", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"The hide of a highland elderhorn is incredibly thick. Never in recorded history has a highland elderhorn even blinked in response to insults thrown at them.\"\nWorld Event:\nWoW Remix: Legion"}
