MultiLanguageItemData['en'][250693] = {name = "[q3]Altar of the Corrupted Flames", additional_info = "3\n[q3]Altar of the Corrupted Flames\nHousing Decor\n[q7]Binds to Warband\n[q2]Use: Add this Decor to your House Chest.\nComplete the achievement \"Broken Isles World Quest V\""}
MultiLanguageItemData['en'][250694] = {name = "[q3]Draconic Metalshaper's Anvil", additional_info = "5\n[q3]Draconic Metalshaper's Anvil\nHousing Decor\n[q7]Binds to Warband\n[q2]Use: Add this Decor to your House Chest.\nReach the fourth milestone of the endeavor.\n[q]\"Once used to shape metal purely for war, these anvils are now used by dracthyr artisans to make whatever they want.\""}
MultiLanguageItemData['en'][250695] = {name = "[q2]Replica Grathardormu's Hammer", additional_info = "1\n[q2]Replica Grathardormu's Hammer\nHousing Decor\n[q7]Binds to Warband\n[q2]Use: Add this Decor to your House Chest.\nReach the third milestone of the endeavor.\n[q]\"A replica of a legendary hammer once used to swear an oath of vengeance. These replicas are often used by blacksmiths to infuse their craft with a bit of mystique.\""}
MultiLanguageItemData['en'][250696] = {name = "[q2]Green Thumb's Watering Can", additional_info = "1\n[q2]Green Thumb's Watering Can\nHousing Decor\n[q7]Binds to Warband\n[q2]Use: Add this Decor to your House Chest.\nReach the first milestone of the endeavor.\n[q]\"It's a watering can. Everyone needs a watering can. Even dracthyr.\""}
MultiLanguageItemData['en'][250697] = {name = "[q2]Draconic Auctioneer's Lectern", additional_info = "3\n[q2]Draconic Auctioneer's Lectern\nHousing Decor\n[q7]Binds to Warband\n[q2]Use: Add this Decor to your House Chest.\nReach the third milestone of the endeavor.\n[q]\"A stylish lectern. Tavern tales tell that standing at once of these makes your speech increase in speed threefold.\""}
MultiLanguageItemData['en'][250698] = {name = "[q2]Obsidian Warder Pennant", additional_info = "5\n[q2]Obsidian Warder Pennant\nHousing Decor\n[q7]Binds to Warband\n[q2]Use: Add this Decor to your House Chest.\n[q]\"A banner proudly displaying the symbol of the Obsidian Warder weyrn.\""}
MultiLanguageItemData['en'][250699] = {name = "[q2]Dark Talon Pennant", additional_info = "5\n[q2]Dark Talon Pennant\nHousing Decor\n[q7]Binds to Warband\n[q2]Use: Add this Decor to your House Chest.\n[q]\"A banner proudly displaying the symbol of the Dark Talon weyrn.\"\nSell Price:"}
MultiLanguageItemData['en'][250700] = {name = "[q2]Roasted Ram Leg", additional_info = "1\n[q2]Roasted Ram Leg\nHousing Decor\n[q7]Binds to Warband\n[q2]Use: Add this Decor to your House Chest.\n[q]\"It's a succulent roasted leg of ram. Despite this, it is named after the inn of Valdrakken, and not just because it's a roasted leg of ram.\""}
MultiLanguageItemData['en'][250701] = {name = "[q2]Draconic Trader's Cart", additional_info = "5\n[q2]Draconic Trader's Cart\nHousing Decor\n[q7]Binds to Warband\n[q2]Use: Add this Decor to your House Chest.\nReach the first milestone of the endeavor.\n[q]\"A status symbol for some, this stylish cart will let you transport anything smaller than it to wherever you need it to be.\""}
MultiLanguageItemData['en'][250702] = {name = "[q2]Artisan's Measuring Scales", additional_info = "1\n[q2]Artisan's Measuring Scales\nHousing Decor\n[q7]Binds to Warband\n[q2]Use: Add this Decor to your House Chest.\nReach the second milestone of the endeavor.\n[q]\"Useful for measuring out ingredients or anything else that need weighing. Not recommended for weighing anything larger than a small dog. Or a very large rat.\""}
MultiLanguageItemData['en'][250703] = {name = "[q2]War Creche Teaching Crystal", additional_info = "3\n[q2]War Creche Teaching Crystal\nHousing Decor\n[q7]Binds to Warband\n[q2]Use: Add this Decor to your House Chest.\nReach the second milestone of the endeavor.\n[q]\"Crystals like these were once used to store Neltharion's teachings for the dracthyr. Not this one, though.\""}
MultiLanguageItemData['en'][250704] = {name = "[q3]Ancient Weyrn Device", additional_info = "5\n[q3]Ancient Weyrn Device\nHousing Decor\n[q7]Binds to Warband\n[q2]Use: Add this Decor to your House Chest.\nReach the fourth milestone of the endeavor.\n[q]\"An ancient device from one of the dracthyr weyrns. It doesn't work anymore other than making a colorful glow.\""}
