MultiLanguageItemData['en'][250721] = {name = "[q4]Reins of the Snowy Highmountain Eagle", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"To find the feather of a snowy eagle in Highmountain is an omen of shifting winds and temperature drops.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250722] = {name = "[q3]Ethereal Stall", additional_info = "Binds when picked up\nToy\n[q2]Use: Drop down an ethereal stall that lasts for 15 min. Can only be used outdoors. (15 Min Cooldown)"}
MultiLanguageItemData['en'][250723] = {name = "[q4]Reins of the Treetop Highmountain Eagle", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"The majestic eagle is a symbol of pride for the Highmountain tribes. This great beast's ability to carry tauren on their backs speaks to the sheer strength and size of the creatures of Highmountain.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250724] = {name = "[q3]Add Keystone Affix: Tyrannically Fortified", additional_info = "Duration: 12 hrs (real time)\n[q2]Use: Add the Tyrannically Fortified affix to a Mythic Keystone.\nSell Price:"}
MultiLanguageItemData['en'][250726] = {name = "[q4]Reins of the Leyfrost Manasaber", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding"}
MultiLanguageItemData['en'][250727] = {name = "[q4]Reins of the Nightwell Manasaber", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding"}
MultiLanguageItemData['en'][250728] = {name = "[q4]Reins of the Arcberry Manasaber", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\n[q]\"Named for their resemblance to the bright berries made into arcwine, these proud cats have a keen awareness of the ley lines that travel beneath them.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250741] = {name = "[q4]Puzzling Cartel Chip", additional_info = "The War Within Season 3\nBinds when picked up\nUnique (200)\n[q]\"Only nine per customer. Spend it wisely!\""}
MultiLanguageItemData['en'][250745] = {name = "[q4]Reins of the Fel-Scarred Mana Ray", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\nSummons and dismisses a Fel-Scarred Mana Ray. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\n\n\n[q]\"Surviving on Argus is not an easy task. Its leathery hide scarred by fel corruption, this mana ray is prone to fits of aggression, moreso than usual.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250746] = {name = "[q4]Reins of the Bloodtooth Mana Ray", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\nSummons and dismisses a Bloodtooth Mana Ray. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\n\n\n[q]\"The shattering of Argus drove this breed of mana ray to bloodthirst. It now subsists on the corrupted blood of any creatures it can sink its many teeth into.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250747] = {name = "[q4]Reins of the Albino Mana Ray", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\nSummons and dismisses a Albino Mana Ray. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\n\n\n[q]\"The shattering of Argus caused the mana rays to mutate and adapt to their surroundings. Some of them abandoned their pigments in favor of strengthening their senses.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250748] = {name = "[q4]Reins of the Luminous Mana Ray", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\nSummons and dismisses a Luminous Mana Ray. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\n[q]\"Mana rays can emit a bright glow to lure in prey.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250750] = {name = "[q2]Pouch of Sprouted Clippings", additional_info = "Binds when picked up\nRequires Midnight Herbalism (25)\n[q]\"Filled with herbs gathered during Abundance events.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][250751] = {name = "[q4]Reins of the Twilight Courser", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"To evade predators, this courser dims its horn while hiding and flashes with dazzling radiance when provoked.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250752] = {name = "[q4]Reins of the Golden Sunrunner", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"This free spirit enjoys long trots on the beach and frolicking through varicolored floral fields.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250753] = {name = "[q2]Bag of Cracked Orebits", additional_info = "Binds when picked up\nRequires Midnight Mining (25)\n[q]\"Filled with ore gathered during Abundance events.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][250754] = {name = "[q2]Bag of Wild Skinnings", additional_info = "Binds when picked up\nRequires Midnight Skinning (25)\n[q]\"Filled with leather and scales gathered during Abundance events.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][250755] = {name = "[q2]Pouch of Mystic Grindings", additional_info = "Binds when picked up\nRequires Midnight Enchanting (25)\n[q]\"Filled with enchanting materials gathered during Abundance events.\"\n[q2]<Right Click to Open>"}
MultiLanguageItemData['en'][250756] = {name = "[q4]Reins of the Turquoise Courser", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Named for its uniquely colored eyes that seem to pierce your soul, the turquoise courser shows more intelligence than her dreamrunner cousins and is known to be an excellent judge of character.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250757] = {name = "[q4]Reins of the Gloomdark Nightmare", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Touched by the Emerald Nightmare, this creature's presence in one's dreams is an omen of misfortune. To see one while awake portends absolute catastrophe.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250758] = {name = "[q4]Reins of the Bonesteed of Oblivion", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\n[q]\"A good warhorse is loyal to its bones. Having shed its mortal coil, this steed is an omen of scarcity and death.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250759] = {name = "[q4]Reins of the Bonesteed of Plague", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\n[q]\"A good warhorse is loyal to its bones. Having shed its mortal coil, this steed is an omen of sickness and suffering.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250760] = {name = "[q4]Reins of the Bonesteed of Bloodshed", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\n[q]\"A good warhorse is loyal to its bones. Having shed its mortal coil, this steed is an omen of eternal strife.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250761] = {name = "[q4]Reins of the Bonesteed of Triumph", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\n[q]\"A good warhorse is loyal to its bones. Having shed its mortal coil, this steed is an omen of bold conquest.\"\nWorld Event:\nWoW Remix: Legion"}
