MultiLanguageItemData['en'][250802] = {name = "[q4]Reins of the Longhorned Sable Talbuk", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\n[q]\"The talbuks of Argus have grown long, coarse fur of brilliant colors that reflects the hues of their broken planet.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250803] = {name = "[q4]Garnet Ruinstrider", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\n[q]\"Outfitted with sturdy barding, Argussian ruinstriders fearlessly carry their riders across the broken wastes of Argus and beyond.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250804] = {name = "[q4]Longhorned Bleakhoof Talbuk", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\n[q]\"Scarred by the chaos wrought by decades of conflict, this fel-infused steed is a perfect match for an intrepid adventurer.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250805] = {name = "[q4]Reins of the Longhorned Argussian Talbuk", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\n[q]\"Few talbuks managed to remain unscathed despite the Legion's exploitation of their homeworld. Their tenacity is befitting of a noble steed.\"\nWorld Event:\nWoW Remix: Legion"}
MultiLanguageItemData['en'][250806] = {name = "[q4]Reins of the Longhorned Beryl Talbuk", additional_info = "Legion Remix\nBinds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\n[q]\"This wild talbuk found among the ruins of Argus has survived and persevered through decades of strife.\"\nWorld Event:\nWoW Remix: Legion"}
