MultiLanguageItemData['en'][251782] = {name = "[q4]Withered Saptor's Paw", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 13 Haste\n[q2]Equip: Your critical strikes have a chance to stir the void within granting you 52 Strength or Agility for 10 sec.\nSell Price:"}
MultiLanguageItemData['en'][251783] = {name = "[q4]Lost Idol of the Hash'ey", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n[q2]+ 13 Speed\n[q2]Equip: Your attacks and abilities have a low chance to beckon a random Loa spirit to your side, increasing your combat capabilities for 30 sec. (5s cooldown)\nSell Price:"}
MultiLanguageItemData['en'][251784] = {name = "[q4]Sylvan Wakrapuku", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 [Agility or Intellect]\n[q2]Equip: Your harmful spells and ranged abilities have a chance to call forth Loa aspects to bombard your target three times, each time dealing ( 1 * 591 ) Physical damage split between all nearby enemies.\nSell Price:"}
MultiLanguageItemData['en'][251785] = {name = "[q4]Void-Reaper's Libram", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 [Agility or Intellect]\n[q2]Equip: Your harmful spells and abilities have a chance to brand your target with sacred text dealing ( 42 * 30) Holy damage over 30 sec.\n\n Rebranding an enemy ignites the text, granting you 21 Critical Strike for 15 sec and immediately dealing all remaining damage. (5s cooldown)\nSell Price:"}
MultiLanguageItemData['en'][251786] = {name = "[q4]Ever-Collapsing Void Fissure", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 Intellect\n[q2]Use: Hold the fissure open causing time to distort itself reducing your movement speed by 50% while increasing your Haste by 26 each second over 10 sec. (2 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][251787] = {name = "[q4]Sealed Chaos Urn", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 [Agility or Strength or Intellect]\n[q2]Use: Unseal the urn causing the void within to pour out and engulf you for 20 sec, increasing all secondary stats by 43 .\n\n As the void dissipates, you become horrified for 5 sec. Killing an enemy while engulfed prevents this effect from occurring. (2 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][251788] = {name = "[q4]Gift of Light", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 Intellect\n[q2]Equip: Your healing spells and abilities have a chance to increase your Mastery by 77 for 10 sec.\n If this occurs while healing an ally below 40% health, grant double the mastery.\n\n Can only occur once every 1 min.\nSell Price:"}
MultiLanguageItemData['en'][251789] = {name = "[q4]Consecrated Chalice", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 Intellect\n[q2]Equip: Your healing spells and abilities have a high chance to fill the chalice with Hope, drop by drop, up to 15 times.\n[q2]Use: Empty the chalice upon an ally granting them ( 1 * 223 ) absorb for each drop spilled for 20 sec. (20 Sec Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][251790] = {name = "[q4]Desecrated Chalice", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 [Agility or Strength]\n[q2]Equip: Taking damage has a high chance to fill the chalice with Despair, drop by drop, up to 10 times. Once full, the chalice spills, blanketing the ground beneath you in a dark mire dealing 364 Void damage each second split between enemies inside for 10 sec while granting you 110 versatility. (1s cooldown)\nSell Price:"}
MultiLanguageItemData['en'][251791] = {name = "[q4]Holy Retributor's Order", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 [Agility or Strength]\n[q2]Equip: The light blesses your weapon granting your attacks a chance to deal 315 additional Holy damage and heal you for 2896 health.\nSell Price:"}
MultiLanguageItemData['en'][251792] = {name = "[q4]Glorious Crusader's Keepsake", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 [Agility or Strength or Intellect]\n[q2]Equip: During combat you have a chance to become consumed by Fanatical Inspiration, increasing your highest secondary by 56 for 15 sec.\n\n Party members also equipped with the keepsake have their lowest secondary increased by 6 for 15 sec.\nSell Price:"}
