MultiLanguageItemData['en'][252411] = {name = "[q3]Radiant Sunstone", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+4 Intellect\n[q2]Use: Bathe your target ally in radiant light, healing them for 497 and imbuing them for 20 sec.\n While imbued, your healing spells and abilities also heal this ally for 27 . (2 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][252415] = {name = "[q4]Trovehunter's Bounty", additional_info = "Midnight Season 1\nBinds when picked up\nUnique\n[q2]Use: At any time, decipher the map and guarantee that you'll find a Hidden Trove at the end of the next Tier 4+ Delve you complete.\n\n Hidden Trove's contents depend on the completed Delve Tier.\n[q]\"Surely, great treasure awaits.\""}
