MultiLanguageItemData['en'][252418] = {name = "[q3]Solar Core Igniter", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+4 [Agility or Strength]\n[q2]Use: Ignite the Solar Core within you for 15 sec, forming a radiant shield that absorbs 50% of incoming damage, up to 828 . Gain up to 24 Versatility for 10 sec if the shield expires, based on its remaining power. (1 Min, 30 Sec Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][252419] = {name = "[q2]Lush Garden Fungal Basin", additional_info = "3\n[q2]Lush Garden Fungal Basin\nHousing Decor\n[q7]Binds to Warband\n[q2]Use: Add this Decor to your House Chest."}
MultiLanguageItemData['en'][252420] = {name = "[q3]Solarflare Prism", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+4 [Agility or Strength]\n[q2]Equip: Your damaging abilities have a chance to unleash the prism's radiant light, increasing your Critical Strike by 50 for 10 sec, further increased by 0 for every 1% of the target's missing health, up to a maximum of 61 .\nSell Price:"}
MultiLanguageItemData['en'][252421] = {name = "[q4]Rotting Globule", additional_info = "Binds when picked up\nUnique-Equipped\nTrinket\n+4 [Agility or Strength]\n[q2]Use: Cover yourself in four fetid pustules, absorbing 768 damage for 15 sec. Each time the shield loses 25% of its value, a pustule erupts, dealing 20 Plague damage split among nearby enemies.\n\n If all pustules erupt, the final burst deals 11 additional Plague damage. (2 Min Cooldown)\nSell Price:"}
