MultiLanguageItemData['en'][253222] = {name = "[q3]Corrupted Thorn of the Dream", additional_info = "Legion Remix: Skies of Fire\nBinds when picked up\n[q2]Use: Combine 10 of these to create an item belonging to the Emerald Nightmare.\nRequires level 10 to 90 ( 90)\n[q]\"In the Emerald Nightmare, even a thorn can blossom into something potent and deadly.\""}
MultiLanguageItemData['en'][253223] = {name = "[q3]Fractal Felshard", additional_info = "Legion Remix: Legionfall\nBinds when picked up\n[q2]Use: Combine 10 of these to create an item belonging to Tomb of Sargeras.\nRequires level 10 to 90 ( 90)\n[q]\"The Deceiver's might is so great that even a drop of his blood, cooled and crystallized to a sliver, contains near-infinite potential.\""}
MultiLanguageItemData['en'][253224] = {name = "[q3]Mote of a Broken Time", additional_info = "Legion Remix\nBinds when picked up\n[q2]Use: Combine 10 of these to create an item belonging to an available raid in Legion: Remix.\nRequires level 10 to 90 ( 90)\n[q]\"A prismatic shard that resonates with this fractured timeline. Simultaneously it takes shape as a corrupted thorn, a warlock's gem, a fel-bright sliver, or an echo of death.\""}
