MultiLanguageItemData['en'][253523] = {name = "[q2]Astalor's Hookah", additional_info = "1\n[q2]Astalor's Hookah\nHousing Decor\n[q7]Binds to Warband\n[q2]Use: Add this Decor to your House Chest.\n[q]\"The same type of hookah found in Astalor's Sanctum. Comes with a card that says \"With my compliments - A\".\""}
MultiLanguageItemData['en'][253524] = {name = "[q2]590 Quel'Lithien Red Display Bottle", additional_info = "1\n[q2]590 Quel'Lithien Red Display Bottle\nHousing Decor\n[q7]Binds to Warband\n[q2]Use: Add this Decor to your House Chest.\nReach the first milestone of the endeavor.\n[q]\"Some bottles of wine are for drinking, other bottles of wine are for showing off to people what you could have been drinking if you opened it. This is the latter.\""}
MultiLanguageItemData['en'][253525] = {name = "[q2]Thalassian Academy Dictation Device", additional_info = "1\n[q2]Thalassian Academy Dictation Device\nHousing Decor\n[q7]Binds to Warband\n[q2]Use: Add this Decor to your House Chest.\nReach the second milestone of the endeavor.\n[q]\"For when one has just the most incredible thoughts, and simply can't pick up a pen with which to write them down. Or taking notes in university while not paying attention to the lecturer.\""}
MultiLanguageItemData['en'][253526] = {name = "[q2]Sin'dorei Wine Display", additional_info = "1\n[q2]Sin'dorei Wine Display\nHousing Decor\n[q7]Binds to Warband\n[q2]Use: Add this Decor to your House Chest.\nReach the third milestone of the endeavor.\n[q]\"Some bottles of wine are for drinking, other bottles of wine are for showing off to people what you could have been drinking if you opened it. This is the later but dialed up to the nines.\""}
