MultiLanguageItemData['en'][253573] = {name = "[q4]Cobalt Phase-Hunter", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Due to the otherworldly energies that irradiated Draenor, these creatures can shift through space at will. As such, they are rarely seen... until it is too late.\"\nPromotion:\nBurning Crusade Classic"}
MultiLanguageItemData['en'][253574] = {name = "Everlasting Rock", additional_info = "Binds when picked up\nUnique\n[q2]Use:\nRequires level 10 to 90 ( 90)\n[q]\"Every time you take a bite, this curious geode seems to rewind its timeline to when it was whole.\""}
