MultiLanguageItemData['en'][257444] = {name = "[q4]Hexed Vilefeather Eagle", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Once a proud sky-hunter, she now soars on withered wings, her spirit twisted by lingering necromantic curses that seep through every rotting plume and ghostlit eye.\"\nTreasure:\nAbandoned Ritual Skull\nZone:\nZul'Aman"}
MultiLanguageItemData['en'][257445] = {name = "[q4]Ravenous Shredclaw", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Renown Rank 17 with The Singularity.\n\n\n[q]\"Fast and dependable, Shredclaws were one of the first creatures tamed in the Voidstorm. Their owners learned quickly not to leave them alone with their pets.\"\nVendor:\nVoid Researcher Anomander\nZone:\nVoidstorm\nCost:\n6000"}
MultiLanguageItemData['en'][257446] = {name = "[q4]Reins of the Insatiable Shredclaw", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"The shredclaw has fully embraced the way of the Void: never satisfied, constantly seeking out new strength to dominate and new prey to devour.\"\nTreasure:\nFinal Clutch of Predaxas\nZone:\nVoidstorm"}
MultiLanguageItemData['en'][257447] = {name = "[q4]Prowling Shredclaw", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequiresSlayer's Duellum\n- Exalted\n\n\n[q]\"According to ren'dorei scouts, shredclaws are often seen hunting in packs.\"\nVendor:\nThraxadar\nZone:\nMasters' Perch\nFaction:\nSlayer's Duellum - Exalted\nCost:\n6000"}
MultiLanguageItemData['en'][257448] = {name = "[q4]Frenzied Shredclaw", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequiresSlayer's Duellum\n- Exalted\n\n\n[q]\"Once a pack member dies, these shredclaws enter a frenzy of rage that not even a hulking ultradon can stop.\"\nVendor:\nThraxadar\nZone:\nMasters' Perch\nFaction:\nSlayer's Duellum - Exalted\nCost:\n6000"}
MultiLanguageItemData['en'][257502] = {name = "[q4]Vicious Snaplizard", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"These creatures are found sneaking through the battlefield and climbing over obstactles, ready to cause trouble for the Alliance.\"\nPvP:\nMidnight: Season 1\nRated Arena and Rated Battleground Season Reward"}
