MultiLanguageItemData['en'][258475] = {name = "[q4]Tuskarr Shoreglider", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"The Tuskarr learned long ago that some of the bones of the sea creatures they hunted were light and buoyant, making for effective glider materials.\"\nPromotion"}
MultiLanguageItemData['en'][258476] = {name = "[q4]Frostbrood Proto-Wyrm", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"The same magic of undeath that raised the Frostbrood into the Lich King's service has infused this primal wyrm. Its loyalty and ferocity now serve those who defend Azeroth.\"\nPromotion:\nWrath of the Lich King Classic"}
MultiLanguageItemData['en'][258477] = {name = "[q4]Telix the Stormhorn", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Once a simple beetle of the Forbidden Reach, Telix became infused with storm magic when Raszageth was unleashed. With its newly heightened senses, Telix roams the Dragon Isles alongside the Dragonscale Expedition--and you!\"\nPromotion"}
MultiLanguageItemData['en'][258479] = {name = "[q4]Algarian Stormrider", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Flying true even in the harshest conditions, this lightning-infused rook was trained to soar through the skies of the Isle of Dorn and into the depths below.\"\nPromotion:\nThe War Within Heroic Edition"}
