MultiLanguageItemData['en'][259171] = {name = "Head-Mounted Beam Bummer", additional_info = "[q4]Head-Mounted Beam Bummer\nBinds when picked up\nUnique-Equipped: Head (1)\nEngineering Accessory[q2]+ 18 Multicraft\nEquip: +11 Midnight Engineering Skill\nRequires Midnight Engineering (1)\n[q]\"For when the lights are too bright.\"\nSell Price:"}
MultiLanguageItemData['en'][259172] = {name = "Schematic: Head-Mounted Beam Bummer", additional_info = "[q4]Schematic: Head-Mounted Beam Bummer\nBinds when picked up\n[q2]Use: Teaches you how to craft Head-Mounted Beam Bummer.\nRequires Midnight Engineering (50)"}
MultiLanguageItemData['en'][259173] = {name = "[q4]Rock Bonkin' Hardhat", additional_info = "Binds when picked up\nUnique-Equipped: Head (1)\nMining Accessory[q2]+ 22 Deftness\n[q2]+ 22 Perception\nEquip: +11 Midnight Mining Skill\nRequires Midnight Mining (1)\n[q]\"Ain't no rock getting through this time tested accessory.\"\nSell Price:"}
