MultiLanguageItemData['en'][259175] = {name = "[q4]Heavy-Duty Rock Assister", additional_info = "Binds when picked up\nUnique-Equipped: Back (1)\nMining Accessory[q2]+ 45 Finesse\nEquip: +11 Midnight Mining Skill\nRequires Midnight Mining (1)\n[q]\"Grabs even more rocks!\"\nSell Price:"}
MultiLanguageItemData['en'][259176] = {name = "[q4]Schematic: Heavy-Duty Rock Assister", additional_info = "Binds when picked up\n[q2]Use:\nRequires Midnight Engineering (50)"}
MultiLanguageItemData['en'][259177] = {name = "[q4]Self-Sharpening Sin'dorei Snippers", additional_info = "Binds when picked up\nTailoring Tool[q2]+ 84 Random Stat 1\nEquip: +18 Midnight Tailoring Skill\nRequires Midnight Tailoring (1)\n[q]\"That first cut feeling, every time.\"\nSell Price:"}
MultiLanguageItemData['en'][259178] = {name = "[q4]Schematic: Self-Sharpening Sin'dorei Snippers", additional_info = "Binds when picked up\n[q2]Use:\nRequires Midnight Engineering (50)"}
MultiLanguageItemData['en'][259179] = {name = "[q4]Sin'dorei Reeler's Rod", additional_info = "Binds when picked up\nFishing Tool[q2]+ 56 Perception\nEquip: +18 Midnight Fishing Skill\nRequires Fishing (1)\nSell Price:"}
MultiLanguageItemData['en'][259180] = {name = "[q4]Schematic: Sin'dorei Reeler's Rod", additional_info = "Binds when picked up\n[q2]Use:\nRequires Midnight Engineering (50)"}
MultiLanguageItemData['en'][259181] = {name = "[q4]Giga-Gem Grippers", additional_info = "Binds when picked up\nJewelcrafting Tool[q2]+ 48 Random Stat 1\nEquip: +18 Midnight Jewelcrafting Skill\nRequires Midnight Jewelcrafting (1)\n[q]\"When they ask \"How do you do it?\", show them this.\"\nSell Price:"}
MultiLanguageItemData['en'][259182] = {name = "[q4]Schematic: Giga-Gem Grippers", additional_info = "Binds when picked up\n[q2]Use:\nRequires Midnight Engineering (50)"}
MultiLanguageItemData['en'][259183] = {name = "[q4]Turbo-Junker's Multitool v9", additional_info = "Binds when picked up\nEngineering Tool[q2]+ 48 Random Stat 1\nEquip: +18 Midnight Engineering Skill\nRequires Midnight Engineering (1)\n[q]\"Final_Version_V9_REAL_ACTUALLY_FINAL. Nothing better than this.\"\nSell Price:"}
MultiLanguageItemData['en'][259184] = {name = "[q4]Schematic: Turbo-Junker's Multitool v9", additional_info = "Binds when picked up\n[q2]Use:\nRequires Midnight Engineering (50)"}
MultiLanguageItemData['en'][259188] = {name = "[q3]Lightbloomed Spore Sample", additional_info = "Binds when picked up\nUse: Study to increase your Midnight Alchemy Knowledge by 1.\nRequires Midnight Alchemy (1)"}
MultiLanguageItemData['en'][259189] = {name = "[q3]Aged Cruor", additional_info = "Binds when picked up\nUse: Study to increase your Midnight Alchemy Knowledge by 1.\nRequires Midnight Alchemy (1)"}
MultiLanguageItemData['en'][259190] = {name = "[q3]Thalassian Whestone", additional_info = "Binds when picked up\nUse: Study to increase your Midnight Blacksmithing Knowledge by 2.\nRequires Midnight Blacksmithing (1)\n\"While the craftsmanship is impressive, this aged whetstone is no longer practically useful. You can study it though to improve your Blacksmithing knowledge!\""}
MultiLanguageItemData['en'][259191] = {name = "[q3]Infused Quenching Oil", additional_info = "Binds when picked up\nUse: Study to increase your Midnight Blacksmithing Knowledge by 2.\nRequires Midnight Blacksmithing (1)\n[q]\"An advanced product utilizing the skills of Alchemists, Enchanters, and Blacksmiths, studying this oil can help deepen your understanding of practical application of Thalassian smithing techniques.\""}
MultiLanguageItemData['en'][259192] = {name = "[q3]Voidstorm Ashes", additional_info = "Binds when picked up\nUse: Study to increase your Midnight Enchanting Knowledge by 2.\nRequires Midnight Enchanting (1)\n[q]\"A fine dust from the Voidstorm, it contains latent magic for enchanters to study. Doing so will yield knowledge!\""}
MultiLanguageItemData['en'][259193] = {name = "[q3]Lost Thalassian Vellum", additional_info = "Binds when picked up\nUse: Study to increase your Midnight Enchanting Knowledge by 2.\nRequires Midnight Enchanting (1)\n\"A previously-lost vellum containing Thalassian-based magics. While it doesn't have any practical use, you can study it for Enchanting Knowledge!\""}
MultiLanguageItemData['en'][259194] = {name = "[q3]Dance Gear", additional_info = "Binds when picked up\nUse: Study to increase your Midnight Engineering Knowledge by 1.\nRequires Midnight Engineering (1)\n[q]\"While they don't have any practical applications, studying them can help improve your knowledge of Thalassian engineering techniques. They also happen to pair well with Song Gears.\""}
MultiLanguageItemData['en'][259195] = {name = "[q3]Dawn Capacitor", additional_info = "Binds when picked up\nUse: Study to increase your Midnight Engineering Knowledge by 1.\nRequires Midnight Engineering (1)\n\"A strange device that emits a bright, golden glow. While you don't have any practical uses for it, you could disassemble it and study it to improve your Engineering knowledge!\""}
MultiLanguageItemData['en'][259196] = {name = "[q3]Brilliant Phoenix Ink", additional_info = "Binds when picked up\nUse: Study to increase your Midnight Inscription Knowledge by 2.\nRequires Midnight Inscription (1)\n[q]\"The magic flowing through this ink has long expired, but its brilliant hue is still a sight to behold. Studying it can help you deepen your understanding of Thalassian scribe techniques.\""}
MultiLanguageItemData['en'][259197] = {name = "[q3]Loa-Blessed Rune", additional_info = "Binds when picked up\nUse: Study to increase your Midnight Inscription Knowledge by 2.\nRequires Midnight Inscription (1)\n[q]\"An ancient rune blessed with the power of the Loa. While you're unsure what it would do, or how to even utilize it, the masterful craftsmanship of the rune can help you with your studies as a scribe.\""}
MultiLanguageItemData['en'][259198] = {name = "[q3]Void-Touched Eversong Diamond Fragments", additional_info = "Binds when picked up\nUse: Study to increase your Midnight Jewelcrafting Knowledge by 2.\nRequires Midnight Jewelcrafting (1)\n\"Unusable, but hints of voidlight shimmer within the depths of the gem. Studying it can yield new Jewelcrafting Knowledge.\""}
MultiLanguageItemData['en'][259199] = {name = "[q3]Harandar Stone Sample", additional_info = "Binds when picked up\nUse: Study to increase your Midnight Jewelcrafting Knowledge by 2.\nRequires Midnight Jewelcrafting (1)\n\"A sample of stone from Harandar, steeped in the primal magic of Azeroth. Studying it will yield Jewelcrafting Knowledge.\""}
MultiLanguageItemData['en'][259200] = {name = "[q3]Amani Tanning Oil", additional_info = "Binds when picked up\nUse: Study to increase your Midnight Leatherworking Knowledge by 2.\nRequires Midnight Leatherworking (1)\n[q]\"Made from the trees of Zul'Aman, the Amani trolls use this for treating their leather. Studying it will yield new knowledge!\""}
MultiLanguageItemData['en'][259201] = {name = "[q3]Thalassian Mana Oil", additional_info = "Binds when picked up\nUse: Study to increase your Midnight Leatherworking Knowledge by 2.\nRequires Midnight Leatherworking (1)\n\"Perfect for treating hides in the use of powerful armor. Also great for studying to improve your Leatherworking!\""}
MultiLanguageItemData['en'][259202] = {name = "[q3]Embroidered Memento", additional_info = "Binds when picked up\nUse: Study to increase your Midnight Tailoring Knowledge by 2.\nRequires Midnight Tailoring (1)"}
MultiLanguageItemData['en'][259203] = {name = "[q3]Finely Woven Lynx Collar", additional_info = "Binds when picked up\nUse: Study to increase your Midnight Tailoring Knowledge by 2.\nRequires Midnight Tailoring (1)"}
MultiLanguageItemData['en'][259204] = {name = "Raider Ash Remains", additional_info = "Quest Item\nUnique (15)\n[q]\"The result of many failures piling up...\""}
