MultiLanguageItemData['en'][260202] = {name = "[q2]Visage of Akil'zon, Loa of Victory", additional_info = "1\n[q2]Visage of Akil'zon, Loa of Victory\nHousing Decor\n[q7]Binds to Warband\n[q2]Use: Add this Decor to your House Chest.\nRequires Renown Rank 18 with the Amani Tribe."}
MultiLanguageItemData['en'][260227] = {name = "Frostbitten Tabard", additional_info = "Quest Item\n[q]\"Well-worn and battered, this tabard is mostly recognizable under all the dust and frost.\""}
MultiLanguageItemData['en'][260228] = {name = "[q4]Galactic Gladiator's Goredrake", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Originating from the void, fully armored and ready for combat.\"\nAchievement:\nGladiator: Midnight Season 1\nCategory:\nPlayer vs. Player"}
MultiLanguageItemData['en'][260231] = {name = "[q4]Lucent Hawkstrider", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"A loyal creature of Thalassian nobility, it finds comfort holed up in the Magisters' Terrace.\"\nDrop:\nDegentrius\nZone:\nMagister's Terrace (Mythic)\n\nDrop:\nChallenger's Cache\nZone:\nMagister's Terrace"}
MultiLanguageItemData['en'][260232] = {name = "[q2]Thalassian Skeleton Key", additional_info = "[q2]Use: Allows opening of locks that require up to 90 lockpicking skill. The lockpick is consumed in the process.\nSell Price:"}
MultiLanguageItemData['en'][260233] = {name = "[q4]Emerald Hawkstrider", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"Its rider died during battle, and so the saddle is passed to you.\"\nWorld Quest:\nThe Battle of the Bridge\nZone:\nSilvermoon City"}
MultiLanguageItemData['en'][260235] = {name = "[q4]Umbral Plume", additional_info = "Binds when picked up\nUnique-Equipped: Plume of Belo'ren (1)\nTrinket\n+9 [Agility or Strength]\n[q2]Equip: The Plume's gloom grants you 21 Critical Strike, waning over 60 sec before returning to full darkness. The Plume's power also regenerates while out of combat.\n[q2]Use: While out of combat, invoke the Plume's dual nature to transform it into a Radiant Plume. (5 Min Cooldown)\nSell Price:"}
MultiLanguageItemData['en'][260246] = {name = "[q2]Plans: Thalassian Skeleton Key", additional_info = "Binds when picked up\n[q2]Use: Teaches you how to craft Coreforged Skeleton Key.\nRequires Midnight Blacksmithing (35)\nSell Price:"}
