MultiLanguageItemData['en'][260263] = {name = "Silvermoon Soiree Spread", additional_info = "[q2]Use: Restores 7% of your maximum health and mana every second over 20 sec. Must remain seated while eating.\n[q]\"A collection of sun-golden apples, arcane infused 'blue' cheese, and native Eversong nuts, paired with fine Arcwine.\"\nSell Price:"}
MultiLanguageItemData['en'][260264] = {name = "Quel'Danas Rations", additional_info = "[q2]Use: Restores 7% of your maximum health and mana every second over 20 sec. Must remain seated while eating.\n[q]\"A simple but nourishing bag of dense bread and dried meats.\"\nSell Price:"}
