MultiLanguageItemData['en'][260267] = {name = "Steamed Hexx'alor Lobster", additional_info = "[q2]Use: Restores 5% of your maximum health every second over 20 sec. Must remain seated while eating.\n[q]\"A whole lobster, harvested straight from the ocean, steamed in two fingers (troll) of Hexx'alor salt water.\"\nSell Price:"}
MultiLanguageItemData['en'][260268] = {name = "Pango and Mash", additional_info = "[q2]Use: Restores 5% of your maximum health every second over 20 sec. Must remain seated while eating.\n[q]\"Thick slices of straw-seared Pango shank topping a heaping bowl of mashed spiced pinetatoes.\"\nSell Price:"}
MultiLanguageItemData['en'][260269] = {name = "Jerk Boar Jerky", additional_info = "[q2]Use: Restores 6% of your maximum health every second over 20 sec. Must remain seated while eating.\n[q]\"Strips of dried boar meat, marinated first in tongue-melting conpeppers and a potent blend of spices.\"\nSell Price:"}
MultiLanguageItemData['en'][260270] = {name = "Bog Legs", additional_info = "[q2]Use: Restores 6% of your maximum health every second over 20 sec. Must remain seated while eating.\n[q]\"An assortment of fried, leg-meat drumsticks. Meats include amazard, toad, boggorm, and all other manner of Leech Bog dwellers.\"\nSell Price:"}
MultiLanguageItemData['en'][260271] = {name = "Root Juice", additional_info = "[q2]Use: Restores 6% of your maximum mana every second over 20 sec. Must remain seated while drinking.\n[q]\"Hand-squeezed roots, tubors, and toadstools sourced throughout Zul'Aman's clilffsides.\"\nSell Price:"}
MultiLanguageItemData['en'][260272] = {name = "Crisp Bluff Bock", additional_info = "[q2]Use: Restores 6% of your maximum mana every second over 20 sec. Must remain seated while drinking.\n[q]\"Toasted malt flavor with a sharp bitter tang. Heavily preferred by Witherbark fishers on overcast afternoons.\"\nSell Price:"}
MultiLanguageItemData['en'][260273] = {name = "Tea of Mists and Rain", additional_info = "[q2]Use: Restores 7% of your maximum mana every second over 20 sec. Must remain seated while drinking.\n[q]\"A mix of fresh-cut buds and dried petals from the Miststone Wells, mixed warm with bear milk. Recommended before sleep to help rejuvenate sore muscles.\"\nSell Price:"}
MultiLanguageItemData['en'][260274] = {name = "Denshroom Deep Roast", additional_info = "[q2]Use: Restores 7% of your maximum mana every second over 20 sec. Must remain seated while drinking.\n[q]\"Mushrooms harvested from Zul'Aman's caves, roasted for a day then ground into a fine powder. Mix with boiling water and drink to stay alert through any overnight hunt.\"\nSell Price:"}
MultiLanguageItemData['en'][260275] = {name = "Mukleech Curry", additional_info = "[q2]Use: Restores 7% of your maximum health and mana every second over 20 sec. Must remain seated while eating.\n[q]\"Overnight-boiled mukleech meat in a boggorm bone broth. Plate of assorted vegetables for dipping.\"\nSell Price:"}
