MultiLanguageItemData['en'][262705] = {name = "[q4]Vicious Snapvine", additional_info = "[q7]Binds to Warband\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount. This is a flying mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"The Snapvines have always been dangerous, but we never realized that the deep variants were independent, and could fly. This Snapvine is always wanting to see more of the world and be fed.\"\nTrading Post"}
MultiLanguageItemData['en'][262706] = {name = "[q4]Ferocious Snapvine", additional_info = "[q7]Binds to Warband\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount. This is a flying mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"The Snapvines have always been dangerous, but we never realized that the deep variants were independent, and could fly. The fruit from this beast is especially delicious when baked in a pie.\"\nTrading Post"}
MultiLanguageItemData['en'][262707] = {name = "[q4]Blooded Snapvine", additional_info = "[q7]Binds to Warband\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount. This is a flying mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"The Snapvines have always been dangerous, but we never realized that the deep variants were independent, and could fly. The distinct, bold coloring means the creature has eaten recently.\"\nTrading Post"}
MultiLanguageItemData['en'][262708] = {name = "[q4]Savage Snapvine", additional_info = "[q7]Binds to Warband\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount. This is a flying mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n[q]\"The Snapvines have always been dangerous, but we never realized that the deep variants were independent, and could fly. Why would anyone want to find one of those things, much less ride one? But the fruit is good.\"\nTrading Post"}
