MultiLanguageItemData['en'][263579] = {name = "[q4]Vivacious Chloroceros", additional_info = "Binds when picked up\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\n[q]\"Catching a chloroceros mane leaf mid-air is considered a sign of good luck among the Haranir. The more vivacious the leaf, the greater the luck.\"\nAchievement:\nTreasures of Harandar\nCategory:\nMidnight"}
MultiLanguageItemData['en'][263580] = {name = "[q4]Vivid Chloroceros", additional_info = "Binds when picked up\nUnique\nMount\n[q0](Account-wide)\n[q2]Use: Teaches you how to summon this mount.\n[q2]Summons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nYou must capture at least 50 Glowing Moth's before Mothkeeper Wew'tam will trade this item with you.\n\n\n[q]\"The healthier the chloroceros, the more vivid the foliage.\"\nVendor:\nMothkeeper Wew'tam\nZone:\nHarandar\nCost:\n10"}
